CREATE OR ALTER  PROCEDURE DBO.SPQ_IZSOL
@JSON  NVARCHAR(MAX)
WITH ENCRYPTION
AS
DECLARE @TBLERRORES TABLE (ERROR VARCHAR(MAX))
DECLARE  @PARAMETROS NVARCHAR(MAX)	,@NOLOTEPEDIDO VARCHAR(50)	,@CANTIDAD INT, @COMPLETA BIT	,@CANTIDAD_ENTREGA INT
		, @MODELO    VARCHAR(100)	,@IDARTICULO_REAL VARCHAR(50)	,@NOLOTE VARCHAR(50)		,@CANTIDADSOL INT
		, @METODO    VARCHAR(100)	,@CNSMOV VARCHAR(20)			,@CNSIZSOLDT VARCHAR(20)	, @SYS_ENTREGA VARCHAR(100)
		, @USUARIO   VARCHAR(12)	,@IDTERCERO VARCHAR(20)			,@IDAREA VARCHAR(20)		, @CCOSTO VARCHAR(20)
		, @ID INT					,@ESTADO_IMOV VARCHAR(20)		,@CODIGO VARCHAR(20)		, @MENSAJE VARCHAR(20)
		, @MODELOACT NVARCHAR(MAX)	,@CANTIDAD_SOLICITADA INT		,@EXISLOTE INT				, @CNSTRAN VARCHAR(20)
		, @A INT					,@IDBODEGA_DESC VARCHAR(200)	,@CANTIDAD_PENDIENTE INT	, @NODOCUMENTO VARCHAR(20)
		, @SYS_ComputerName VARCHAR(100)	,@IDITAR VARCHAR(20)	,@NVOCONSEC VARCHAR(20)		, @IDTIPOMOV     VARCHAR(2)
		, @IDBODEGACONSUMO VARCHAR(20)		,@PROCEDENCIA VARCHAR(20)	, @ACCION VARCHAR(20)	, @MOTIVO VARCHAR(50)
		, @IDSEDE VARCHAR(20)		,@SEDE VARCHAR(20)	,@OBSERVACION VARCHAR(200)				,@datoIMOVH NVARCHAR(MAX), @PROCESO VARCHAR(50)
		, @NOADMISION VARCHAR(20)	,@CONSECUTIVOHCA VARCHAR(20)	, @datoIMOV NVARCHAR(MAX)		,@CNSITRA VARCHAR(20)		, @CNSFCOM  VARCHAR(20)
		, @IDBODEGASOL VARCHAR(20)	,@DATOS NVARCHAR(MAX)			,@ITEM INT					, @CNSRPDX_2 VARCHAR(20)
		, @SECTOR VARCHAR(30)		,@F_VIGENCIAINV DATE			,@CODIGOBARRA VARCHAR(20)	, @CNSRPDX_NEW VARCHAR(20)	
		, @CNSIZSOL VARCHAR(20)		,@PCOSTO DECIMAL(14,2)			,@CANTIDAD_TOTAL DECIMAL(14,2)	,@ITEM_2 INT	, @NUEVOCNS VARCHAR(20)
		, @CNSIZSOLD VARCHAR(20)	,@IDCAUSA VARCHAR(20)			,@CODBARRA VARCHAR(50)		,@CNSRINVIMA VARCHAR(20)
		, @IDPLAN VARCHAR(6)		,@DATO VARCHAR(10)				,@IDARTICULOORI VARCHAR(20)	,@NOAUT VARCHAR(20)	,@IDAUT VARCHAR(20)
		, @TIPO_USUARIO VARCHAR(12)	,@PREFIJO VARCHAR(20)			,@GRUPOABO VARCHAR(20),		 @GRUPORH VARCHAR(20)
		, @IDTE VARCHAR(5)			,@IDARTICULO_SEL VARCHAR(20)	,@IDIEXI INT,				 @DATOS_ARTICULOS NVARCHAR(MAX), @IVA_PORCENTAJE DECIMAL(14,2)
		, @CLASE VARCHAR(50) = 'SENFER', @CNSMOV_GENERADO VARCHAR(20), @CEDULA VARCHAR(20),		 @CUMPLE_CONDICIONES BIT
		, @ESTA_APROBADO BIT,		@TEMP_ALMACENAMIENTO DECIMAL(14,2), @IDAFILIADO VARCHAR(20), @NOMBRE_PACIENTE VARCHAR(200) = ''
		, @FDESDE DATE,				@FHASTA DATE, @COMPANIA VARCHAR(20), @ESTADO VARCHAR(20),	 @IDBODEGA VARCHAR(20)
		, @ENCONTRADO BIT = 0,		@BARCODE VARCHAR(50),@TEMPERATURA DECIMAL(14,2),	@CANTIDADREV DECIMAL(14,2), @PIVA DECIMAL(14,2)	, @CUMPLE BIT
		, @ES_MANUALCE BIT = 0  , @NOPRESTACION VARCHAR(20), @NOPRESUPUESTO VARCHAR(20),  @SQL NVARCHAR(MAX)
		, @ERR_TRANSCE VARCHAR(500)
		, @SKU_TRANSCE VARCHAR(20)
		, @CNSRES VARCHAR(20)
		, @IDBODEGA_FMT VARCHAR(20)
DECLARE @FECHAVENCE DATE,			@PC_SINIVA DECIMAL(14,2), @IDTIPOMOV_TIPO VARCHAR(20), @IDSERVICIO_CIR VARCHAR(20)
	,@APROBADO BIT	,@VALIDA_STOCKS VARCHAR(200) 
DECLARE @CNSRPDX          VARCHAR(20)
DECLARE @ERROR AS INT
		,@IART_DESCRIPCION VARCHAR(MAX)
		,@FVENCE DATE
		,@RAZONSOCIAL VARCHAR(MAX)
		,@CODCUM VARCHAR(100)
		,@REGINVIMA VARCHAR(100)
		,@IDUNIDAD VARCHAR(100)
		,@GENEROCAJA SMALLINT
		,@CLASEPLANTILLA_HCA VARCHAR(20)
		,@FECHA_IZSOL DATETIME
		,@FECHA_PREPRO DATETIME
		,@FECHA_RESPUESTA DATETIME
		,@MENSAJE_PROA NVARCHAR(400)
		,@TIENE_AUTORIZADOS BIT
		,@IDARTICULO_PROA VARCHAR(20)
		,@MAUTORIZACION_ART BIT
		,@PROA_ESTADO_ART VARCHAR(20)
		,@PROA_INF VARCHAR(20)
		,@PROA_EPI VARCHAR(10)
		,@PROA_IDSERV VARCHAR(20)
		,@PROA_DIAS_SOL DECIMAL(14,2)
		,@PROA_DIAS_AUT DECIMAL(14,2)
		,@PROA_OBS VARCHAR(MAX)
		,@PROA_CNS_INICIAR VARCHAR(13)
BEGIN       
	SET DATEFORMAT dmy
	SET LANGUAGE Spanish; 

	BEGIN TRY

	SELECT *
	INTO #JSON
	FROM OPENJSON (@json)
	WITH (
		MODELO         VARCHAR(100)     '$.MODELO',
		METODO         VARCHAR(100)     '$.METODO',
		USUARIO        VARCHAR(12)      '$.USUARIO',
		PARAMETROS     NVARCHAR(MAX)     AS JSON
	)

	SELECT @MODELO = MODELO , @METODO = METODO , @PARAMETROS = PARAMETROS, @USUARIO = USUARIO
	FROM #JSON

	-- Normalizar usuario (evita fallos por espacios en el JSON)
	SET @USUARIO = LTRIM(RTRIM(@USUARIO))

	SELECT @SYS_COMPUTERNAME = LTRIM(RTRIM(SYS_ComputerName)) FROM USUSU WHERE USUARIO = @USUARIO
	SELECT @IDSEDE = IDSEDE, @SEDE = IDSEDE, @COMPANIA=COMPANIA, @IDBODEGA = COALESCE(IDBODEGA, IDBODEGA2, IDBODEGANOCHE, IDBODEGACONSUMO) FROM UBEQ WHERE SYS_ComputerName = @SYS_COMPUTERNAME
	SELECT @IDTE     = DBO.FNK_VALORVARIABLE ('@IDTE')
	
   IF COALESCE(@SYS_COMPUTERNAME,'') = ''
   BEGIN
      INSERT INTO @TBLERRORES(ERROR) SELECT 'Este Usuario no tiene Equipo Asignado en Configuraci�n (UBEQ)'
      SELECT 'KO' OK
      SELECT ERROR FROM @TBLERRORES
      RETURN
   END

   IF (SELECT COUNT(*) FROM UBEQ WHERE SYS_COMPUTERNAME = @SYS_COMPUTERNAME) <= 0
   BEGIN 
      INSERT INTO @TBLERRORES(ERROR) SELECT 'El Equipo Configurado en el Usuario No Existe en la tabla de Equipos.(UBEQ)'
      SELECT 'KO' OK
      SELECT ERROR FROM @TBLERRORES
      RETURN
   END


	IF @METODO = 'SOLICITUD_CONSUMO'
	BEGIN
      
		--{"MODELO":"HTX","METODO":"CONSULTA","PARAMETROS":{"ADMISIONES":[{"NOADMISION":"0100000004"},{"NOADMISION":"01P00000030"}]},"USUARIO":"AOLAYA"}
		SELECT @MODELOACT = ARTICULOS,
			@NOADMISION = NOADMISION,
			@IDPLAN=IDPLAN
		FROM   OPENJSON (@PARAMETROS)
		WITH ( 
			NOADMISION  VARCHAR(20)   '$.NOADMISION',
			IDPLAN      VARCHAR(6)    '$.IDPLAN',
			ARTICULOS   NVARCHAR(MAX)  AS JSON
		)

		SELECT @SYS_ComputerName = SYS_ComputerName, @IDSEDE=IDSEDE, @IDBODEGASOL=IDBODEGA FROM USUSU WHERE USUARIO=@USUARIO
		SELECT @TIPO_USUARIO = TIPO_USUARIO FROM MED INNER JOIN USUSU ON USUSU.IDMEDICO=MED.IDMEDICO WHERE USUARIO=@USUARIO
		SELECT @IDBODEGACONSUMO = IDBODEGA, @CCOSTO=CCOSTO FROM UBEQ WHERE SYS_COMPUTERNAME = @SYS_ComputerName
		SELECT TOP 1 @SECTOR = SECTOR/*, @HABCAMA=HABCAMA*/ FROM HHAB WHERE NOADMISION = @NOADMISION
      
		IF COALESCE(@NOADMISION,'')='' -- SIGNIFICA QUE EL CONSUMO LO ESTA HACIENDO EL USUARIO PARA SU SERVICIO
		BEGIN
		SET @NOADMISION = 'ENFERMERIA'
		SELECT @NOADMISION = CASE @TIPO_USUARIO
			WHEN 'Enfermera' THEN 'ENFERMERIA'
			WHEN 'Fisioterapia' THEN 'TERAPIA'
			WHEN 'Medico' THEN 'ASISTENCIAL'
			WHEN 'Nutricion' THEN 'ENFERMERIA'
			ELSE 'AMBULATORIO' END
		SET @CLASE = 'Consumo'
		SET @SECTOR= @CCOSTO
		END
      
		SELECT * INTO #ARTICULOS
		FROM  OPENJSON (@MODELOACT)
		WITH  ( 
		IDARTICULO  VARCHAR(20) '$.IDARTICULO',
		CANTIDAD    INT '$.CANTIDAD'
		)  

		--EXEC SPK_GENCONSECUTIVO '01',@IDSEDE,'@IZSOL', @CNSIZSOL OUTPUT  
		--SELECT @CNS
		SELECT IZSOL = @IDSEDE + REPLACE(SPACE(10 - LEN(@CNSIZSOL))+LTRIM(RTRIM(@CNSIZSOL)),SPACE(1),0)
		EXEC SPQ_GENSEQUENCE @SEDE=@SEDE,@PREFIJO='@IZSOL', @NVOCONSEC=@CNSIZSOL OUTPUT  


		INSERT INTO IZSOL(CNSIZSOL,FECHASOL,USUARIOSOL,ESTADO,IDSEDE,SECTOR,IDBODEGASOLICITA,IDBODEGAATIENDE,CLASE,NOADMISION,SYS_COMPUTER,IDPLAN)
		SELECT @CNSIZSOL,DBO.FNK_FECHA_SIN_MLS(GETDATE()),@USUARIO,0,@IDSEDE,@SECTOR,@IDBODEGASOL,@IDBODEGACONSUMO,@CLASE, @NOADMISION, @SYS_ComputerName,@IDPLAN
      
		DECLARE @IDARTICULO VARCHAR(20),  @IDSERVICIO VARCHAR(20)
	  /* -- SE COMENTA AC 2024-08-01
		DECLARE @CANT_ITEMS INT = (SELECT COUNT(1) FROM #ARTICULOS)
		WHILE @CANT_ITEMS>0
		BEGIN
			EXEC SPQ_GENSEQUENCE @SEDE=@SEDE,@PREFIJO='@IZSOLD', @NVOCONSEC=@CNSIZSOLD OUTPUT  
			
			SELECT TOP 1 @IDARTICULO = IDARTICULO, @CANTIDAD = CANTIDAD FROM #ARTICULOS
			SELECT @IDSERVICIO=IDSERVICIO FROM IART WHERE IDARTICULO=@IDARTICULO
			DELETE FROM #ARTICULOS WHERE IDARTICULO=@IDARTICULO
			SET @CANT_ITEMS = @CANT_ITEMS-1

			INSERT INTO IZSOLD(CNSIZSOL,CNSIZSOLD,IDARTICULO,CANTIDADSOL,ESTADO,CODOM,CANTIDAD,IDSERVICIO)
			SELECT @CNSIZSOL, @CNSIZSOLD, @IDARTICULO, @CANTIDAD, 0, '', 0, @IDSERVICIO

		END
		*/

		INSERT INTO IZSOLD(CNSIZSOL,IDARTICULO,CANTIDADSOL,ESTADO,CODOM,CANTIDAD,IDSERVICIO, NEWCNSIZOLD)
		SELECT @CNSIZSOL,  #ARTICULOS.IDARTICULO, #ARTICULOS.CANTIDAD, 0, '', 0, IART.IDSERVICIO, ''
		FROM #ARTICULOS
		INNER JOIN IART ON #ARTICULOS.IDARTICULO = IART.IDARTICULO


		UPDATE IZSOL SET ESTADO=1 WHERE CNSIZSOL=@CNSIZSOL
		UPDATE IZSOLD SET ESTADO=1 WHERE CNSIZSOL=@CNSIZSOL

		RETURN
	END

	IF @METODO = 'CONSULTA'
	BEGIN
		SELECT @NOADMISION = NOADMISION
		FROM   OPENJSON (@PARAMETROS)
		WITH ( 
		NOADMISION VARCHAR(20)
		)
		SELECT USUSU.NOMBRE NOMBRESOL, CONVERT(VARCHAR,FECHASOL,103)+' '+CONVERT(VARCHAR,FECHASOL,108) FECHASOLFORMAT, ESTADO_STR = CASE IZSOL.ESTADO WHEN 0 THEN 'Abierta' WHEN 1 THEN 'Solicitada' WHEN 2 THEN 'Cerrada' END,IZSOL.* FROM IZSOL LEFT JOIN USUSU ON USUSU.USUARIO=IZSOL.USUARIOSOL WHERE NOADMISION=@NOADMISION AND CLASE<>'HTX' ORDER BY FECHASOL DESC
		SELECT IZSOLD.*,IART.DESCRIPCION FROM IZSOLD LEFT JOIN IART ON IART.IDARTICULO=IZSOLD.IDARTICULO WHERE CNSIZSOL IN (SELECT CNSIZSOL FROM IZSOL WHERE NOADMISION=@NOADMISION AND CLASE<>'HTX')
	END

	IF @METODO = 'DETALLES'
	BEGIN
		SELECT IZSOLD.*,IART.DESCRIPCION 
		FROM IZSOLD LEFT JOIN IART ON IART.IDARTICULO=IZSOLD.IDARTICULO 
		WHERE CNSIZSOL IN (
			SELECT CNSIZSOL
			FROM   OPENJSON (@PARAMETROS)
			WITH (   
					CNSIZSOL     VARCHAR(20)   '$.CNSIZSOL'
			)   
		)
		RETURN
	END

	IF @METODO = 'GUARDAR_SOLICITUD'
	BEGIN

		SELECT @CNSIZSOL = JSON_VALUE(@PARAMETROS,'$.CNSIZSOL')

		BEGIN TRY
			IF COALESCE(@CNSIZSOL, '') = ''
			BEGIN
				--EXEC SPK_GENCONSECUTIVO @COMPANIA,@IDSEDE,'@IZSOL', @CNSIZSOL OUTPUT  
				--SELECT @CNSIZSOL = @IDSEDE + REPLACE(SPACE(10 - LEN(@CNSIZSOL))+LTRIM(RTRIM(@CNSIZSOL)),SPACE(1),0)
				DECLARE @EXISTS BIT = 1
				WHILE @EXISTS = 1 OR COALESCE(@CNSIZSOL, '')=''
				BEGIN
					SET @EXISTS = 0
					EXEC SPQ_GENSEQUENCE @SEDE=@SEDE,@PREFIJO='@IZSOL', @NVOCONSEC=@CNSIZSOL OUTPUT  
					SELECT @EXISTS = 1 FROM IZSOL WHERE CNSIZSOL=@CNSIZSOL
				END

				INSERT INTO IZSOL (CNSIZSOL,FECHASOL,USUARIOSOL,ESTADO,IDBODEGASOLICITA
					,IDBODEGAATIENDE,SECTOR,CLASE,NOADMISION,SYS_COMPUTER
					,IDSEDE)
				SELECT 
					CNSIZSOL = @CNSIZSOL
					,DBO.FNK_FECHA_SIN_MLS(GETDATE()) AS FECHASOL
					,@USUARIO AS USUARIOSOL
					,ESTADO = 0
					,@IDBODEGA AS IDBODEGASOLICITA
					,IDBODEGAATIENDE
					,SECTOR = CCOSTO
					,CLASE = 'Consumo'
					,NOADMISION
					,SYS_COMPUTERNAME = @SYS_COMPUTERNAME
					,IDSEDE = @IDSEDE
				FROM OPENJSON(@PARAMETROS)
				WITH(
					CCOSTO VARCHAR(20) '$.CCOSTO'
					,IDBODEGAATIENDE VARCHAR(20) '$.IDBODEGAATIENDE'
					,NOADMISION VARCHAR(20) '$.NOADMISION'
				)
			END
			ELSE
			BEGIN
				UPDATE IZSOL
				SET SECTOR = #T.CCOSTO
					,IDBODEGAATIENDE = #T.IDBODEGAATIENDE
				--SELECT #T.*, IZSOL.* 
				FROM OPENJSON(@PARAMETROS)
				WITH(
					CCOSTO VARCHAR(20) '$.CCOSTO'
					,IDBODEGAATIENDE VARCHAR(20) '$.IDBODEGAATIENDE'
					--,NOADMISION VARCHAR(20) '$.NOADMISION'
				) AS #T INNER JOIN IZSOL ON IZSOL.CNSIZSOL = @CNSIZSOL
			END
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()          
		END CATCH

		IF(SELECT COUNT(*) FROM @TBLERRORES) >0
		BEGIN
			SELECT 'KO' OK, '' CONSECUTIVO
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT OK = 'OK', * 
		FROM IZSOL 
		WHERE CNSIZSOL = @CNSIZSOL 
		
	END
	
	/* GUARDAR_SOLICITUD_CE ya no se usa: no llama SPK_IZSOL_A_AUT.
	   Nueva transcripci�n = CEFM.CRUDCEFM + CEFM.AUDITAR (AUT.MANUALCE=1). */
	IF @METODO = 'GUARDAR_SOLICITUD_CE'
	BEGIN
		SELECT 'KO' OK, '' CNSIZSOL, 'GUARDAR_SOLICITUD_CE ya no se usa. Utilice CEFM.CRUDCEFM + CEFM.AUDITAR.' ERROR
		SELECT 'GUARDAR_SOLICITUD_CE ya no se usa. Utilice CEFM.CRUDCEFM + CEFM.AUDITAR.' ERROR
		RETURN
	END

	IF @METODO = 'BORRAR_SOLICITUD'
	BEGIN

		SELECT @CNSIZSOL = JSON_VALUE(@PARAMETROS,'$.CNSIZSOL')
		IF EXISTS(SELECT 1 FROM IZSOLD WHERE CNSIZSOL=@CNSIZSOL )
		BEGIN
			SELECT 'KO'
			SELECT ERROR ='No puede eliminar una solicitud con detalles'
			RETURN
		END

		BEGIN TRY
			PRINT 'ANTES'
			DELETE FROM IZSOL WHERE CNSIZSOL=@CNSIZSOL
			PRINT 'DESPUES'
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()          
		END CATCH

		IF(SELECT COUNT(*) FROM @TBLERRORES) >0
		BEGIN
			SELECT 'KO' OK, '' CONSECUTIVO
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT OK = 'OK'
		RETURN		
	END

	IF @METODO = 'CONFIRMAR_SOLICITUD'
	BEGIN
		SELECT @CNSIZSOL = JSON_VALUE(@PARAMETROS, '$.CNSIZSOL')
		BEGIN TRY

			UPDATE IZSOL SET ESTADO=1 WHERE CNSIZSOL=@CNSIZSOL

			UPDATE IZSOLD SET IDPRINCIPIO=IART.IDSERVICIO 
			FROM IZSOLD INNER JOIN IART ON IART.IDARTICULO=IZSOLD.IDARTICULO 
			WHERE CNSIZSOL=@CNSIZSOLD

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()          
		END CATCH

		IF(SELECT COUNT(*) FROM @TBLERRORES) >0
		BEGIN
			SELECT 'KO' OK, '' CONSECUTIVO
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT OK = 'OK', CNSIZSOL = @CNSIZSOL 
	END

	IF @METODO = 'DESHACER_PEDIDO'
	BEGIN
		SELECT @CNSIZSOL = JSON_VALUE(@PARAMETROS, '$.CNSIZSOL')

		IF (SELECT COUNT(1) FROM IZSOLD WHERE CNSIZSOL=@CNSIZSOL AND COALESCE(ESTADO,0)=0)<>0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'La solicitud ya fue respondida en farmacia/bodega. �No es posible cancelar pedido!'
		END

		IF(SELECT COUNT(*) FROM @TBLERRORES) <= 0
		BEGIN TRY

			UPDATE IZSOL SET ESTADO=0 WHERE CNSIZSOL=@CNSIZSOL

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()          
		END CATCH

		IF(SELECT COUNT(*) FROM @TBLERRORES) > 0
		BEGIN
			SELECT 'KO' OK, '' CONSECUTIVO
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT OK = 'OK', CNSIZSOL = @CNSIZSOL 
	END
	IF @METODO = 'ENTREGAR'
	BEGIN
		SELECT @CNSIZSOL =  CNSIZSOL, @NOLOTEPEDIDO = NOLOTEPEDIDO, @CANTIDAD = CANTIDAD, @COMPLETA = COMPLETA, @CNSIZSOLD = CNSIZSOLD, @NOLOTE = NOLOTE, @IDBODEGA = IDBODEGA
		,@IDARTICULO_SEL = IDARTICULO_SEL
		FROM OPENJSON (@PARAMETROS)
		WITH(
			CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
			,CNSIZSOLD				VARCHAR(20)			'$.CNSIZSOLD'
			,NOLOTEPEDIDO			VARCHAR(50)			'$.NOLOTEPEDIDO'
			,NOLOTE					VARCHAR(50)			'$.NOLOTE'
			,CANTIDAD				INT					'$.CANTIDAD'
			,COMPLETA				BIT					'$.COMPLETA'
			,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
			,IDARTICULO_SEL			VARCHAR(20)			'$.IDARTICULO_SEL'
		)
		
		SELECT @IDSEDE = IDSEDE FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL
		SELECT @IDARTICULO = IDARTICULO, @CANTIDADSOL = CANTIDADSOL FROM IZSOLD WHERE CNSIZSOLD = @CNSIZSOLD
		SET @ES_MANUALCE = 0
		SELECT @ES_MANUALCE = CASE
			WHEN IZSOL.CLASE = 'TRANS_CE' THEN 1
			WHEN IZSOL.CLASE = 'CE' AND COALESCE(AUT.MANUALCE, 0) = 1 THEN 1
			ELSE 0
		END
		FROM IZSOL WITH (NOLOCK)
		LEFT JOIN AUT WITH (NOLOCK) ON AUT.IDAUT = IZSOL.NOADMISION
		WHERE IZSOL.CNSIZSOL = @CNSIZSOL

		IF @ES_MANUALCE = 1
		BEGIN
			IF COALESCE(@IDBODEGA,'') = ''
				SELECT TOP 1 @IDBODEGA = IDBODEGA FROM IMOV WHERE NODOCUMENTO = @CNSIZSOL AND ESTADO = 0 ORDER BY FECHAMOV ASC
			IF COALESCE(@IDBODEGA,'') = ''
				SELECT @IDBODEGA = IDBODEGAATIENDE FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL

			SELECT TOP 1 @IDARTICULO_REAL = IEXI.IDARTICULO
			FROM IEXI WITH (NOLOCK)
			WHERE IEXI.IDBODEGA = @IDBODEGA
			  AND IEXI.NOLOTE = @NOLOTE
			  AND COALESCE(IEXI.NOLOTEPEDIDO,'') = COALESCE(@NOLOTEPEDIDO,'')
			  AND IEXI.IDARTICULO = @IDARTICULO_SEL

			IF COALESCE(@IDARTICULO_REAL,'') = ''
				SELECT TOP 1 @IDARTICULO_REAL = IEXI.IDARTICULO
				FROM IEXI WITH (NOLOCK)
				WHERE IEXI.IDBODEGA = @IDBODEGA
				  AND IEXI.NOLOTE = @NOLOTE
				  AND IEXI.IDARTICULO = @IDARTICULO_SEL

			IF COALESCE(@IDARTICULO_REAL,'') = ''
			BEGIN
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'El lote interno no existe en la bodega para el art�culo indicado.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END

			SELECT TOP 1 @CNSMOV = CNSMOV
			FROM IMOV
			WHERE NODOCUMENTO = @CNSIZSOL AND ESTADO = 0 AND IDBODEGA = @IDBODEGA
			ORDER BY FECHAMOV ASC

			IF COALESCE(@CNSMOV,'') = ''
			BEGIN
				SELECT TOP 1 @CNSMOV_GENERADO = CNSMOV
				FROM IMOV
				WHERE NODOCUMENTO = @CNSIZSOL AND ESTADO = 0
				  AND COALESCE(PROCEDENCIA,'') <> 'DEVOLUCION'
				ORDER BY FECHAMOV ASC

				IF COALESCE(@CNSMOV_GENERADO,'') = ''
				BEGIN
					INSERT INTO @TBLERRORES(ERROR) SELECT 'No cuenta con CNSMOV'
					SELECT 'KO' OK
					SELECT ERROR FROM @TBLERRORES
					RETURN
				END

				EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE, @PREFIJO='@MOV', @NVOCONSEC=@NVOCONSEC OUTPUT
				INSERT INTO IMOV (
					CNSMOV, IDBODEGA, IDTIPOMOV, NODOCUMENTO, FECHAMOV, CCOSTO,
					IDSOLICITA, IDFUNCIONARIO, ESTADO, OBSERVACION, SUBIOCOMPRA, IDAREA,
					CONTABILIZADA, PROCEDENCIA, USUARIO, PARCIAL, SYS_ComputerName,
					TIENECAMBIO, IDITAR, ESTRANSITO, IDBODEGAEXTERNA, IDTERCERO, IDPLAN,
					GENFACTURA, FACTURADA, IDSERVICIO
				)
				SELECT
					@NVOCONSEC, @IDBODEGA, M.IDTIPOMOV, M.NODOCUMENTO, DBO.FNK_FECHA_SIN_MLS(GETDATE()), M.CCOSTO,
					M.IDSOLICITA, M.IDFUNCIONARIO, 0, M.OBSERVACION, M.SUBIOCOMPRA, M.IDAREA,
					0, M.PROCEDENCIA, @USUARIO, M.PARCIAL, @SYS_COMPUTERNAME,
					M.TIENECAMBIO, M.IDITAR, M.ESTRANSITO, M.IDBODEGAEXTERNA, M.IDTERCERO, M.IDPLAN,
					M.GENFACTURA, M.FACTURADA, M.IDSERVICIO
				FROM IMOV M
				WHERE M.CNSMOV = @CNSMOV_GENERADO

				SET @CNSMOV = @NVOCONSEC
			END
		END
		ELSE
		BEGIN
			SELECT TOP 1 @CNSMOV = CNSMOV FROM IMOV WHERE NODOCUMENTO = @CNSIZSOL AND ESTADO = 0
			SELECT TOP 1 @IDARTICULO_REAL = IDARTICULO
			FROM IEXI
			WHERE IEXI.IDBODEGA = @IDBODEGA AND NOLOTE = @NOLOTE
			  AND COALESCE(NOLOTEPEDIDO,'') = COALESCE(@NOLOTEPEDIDO,'')
			  AND IEXI.IDARTICULO = @IDARTICULO_SEL
		END

		/* TRANS_CE: SKU Activo + ESP vigente (plan mapeado + tercero). No-op en otras clases.
		   EXEC no admite expresiones (COALESCE) como argumento posicional. */
		SET @ERR_TRANSCE = NULL
		SET @SKU_TRANSCE = COALESCE(NULLIF(@IDARTICULO_REAL, ''), @IDARTICULO_SEL)
		IF OBJECT_ID('DBO.SPQ_CEFM_VALIDA_DISP_TRANSCE', 'P') IS NOT NULL
			EXEC DBO.SPQ_CEFM_VALIDA_DISP_TRANSCE @CNSIZSOL, @SKU_TRANSCE, @ERR_TRANSCE OUTPUT
		ELSE IF EXISTS (
			SELECT 1 FROM IZSOL WITH (NOLOCK)
			WHERE CNSIZSOL = @CNSIZSOL AND CLASE = 'TRANS_CE'
		)
			SET @ERR_TRANSCE = 'Falta SPQ_CEFM_VALIDA_DISP_TRANSCE. No se puede dispensar TRANS_CE.'
		IF COALESCE(@ERR_TRANSCE, '') <> ''
			INSERT INTO @TBLERRORES(ERROR) SELECT @ERR_TRANSCE

		-- PROA por art�culo: solo IART.MAUTORIZACION=1 exige autorizaci�n PROA.
		-- Antibi�ticos sin MAUTORIZACION pueden dispensarse; el UI muestra aviso.
		SET @IDARTICULO_PROA = @IDARTICULO
		SET @MAUTORIZACION_ART = 0
		SELECT @MAUTORIZACION_ART = CAST(COALESCE(A.MAUTORIZACION, 0) AS BIT)
		FROM IZSOLD D WITH(NOLOCK)
		INNER JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
		WHERE D.CNSIZSOLD = @CNSIZSOLD
		IF COALESCE(@MAUTORIZACION_ART, 0) = 0
			SELECT @MAUTORIZACION_ART = CAST(COALESCE(MAUTORIZACION, 0) AS BIT)
			FROM IART WITH(NOLOCK)
			WHERE IDARTICULO = @IDARTICULO_PROA OR IDSERVICIO = @IDARTICULO_PROA
		SELECT @CONSECUTIVOHCA = CONSECUTIVOHCA, @NOADMISION = NOADMISION, @FECHA_IZSOL = FECHASOL
		FROM IZSOL WITH(NOLOCK) WHERE CNSIZSOL = @CNSIZSOL
		IF COALESCE(@MAUTORIZACION_ART, 0) = 1 AND OBJECT_ID('DBO.HCATD_PROA', 'U') IS NOT NULL
		BEGIN
			SET @PROA_ESTADO_ART = NULL
			SET @PROA_INF = NULL
			SET @PROA_EPI = NULL
			SET @PROA_IDSERV = NULL
			SET @PROA_DIAS_SOL = NULL
			SET @PROA_DIAS_AUT = NULL
			SET @PROA_OBS = NULL
			SET @PROA_CNS_INICIAR = NULL
			SELECT TOP 1 @PROA_IDSERV = COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), S.IDSERVICIO, A.IDSERVICIO)
			FROM IZSOLD D WITH(NOLOCK)
			LEFT JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
			LEFT JOIN SER S WITH(NOLOCK) ON S.IDSERVICIO = A.IDSERVICIO OR S.IDARTICULO = D.IDARTICULO
			WHERE D.CNSIZSOLD = @CNSIZSOLD

			-- Anclar la solicitud PROA vigente:
			-- 1) Si el propio pedido que se est� entregando (IZSOL.CONSECUTIVOHCA) ya ES un Iniciar
			--    (HCATD.CLASE='I') de este servicio, se usa directo: es la orden actual, cubre el caso
			--    de reformulaci�n (ajuste de dosis), donde cada ajuste crea un nuevo Iniciar con su
			--    propia solicitud PROA y el anterior (rechazado/con otra dosis) queda superado.
			-- 2) Si no (p.ej. IZSOL.CLASE='24HORAS', cuyo CONSECUTIVOHCA es el pedido del d�a y no un
			--    Iniciar propio), se busca el Iniciar M�S RECIENTE de la admisi�n para ese servicio.
			--    NO se debe tomar el m�s antiguo: una reformulaci�n posterior invalida a la solicitud
			--    original (bug real: un Meropenem reformulado 2 veces y aprobado en la �ltima quedaba
			--    bloqueado porque el gate segu�a anclado a la primera solicitud, ya rechazada).
			IF EXISTS (
				SELECT 1 FROM DBO.HCATD H WITH(NOLOCK)
				WHERE H.CONSECUTIVO = @CONSECUTIVOHCA AND H.IDSERVICIO = @PROA_IDSERV AND H.CLASE = 'I'
			)
				SET @PROA_CNS_INICIAR = @CONSECUTIVOHCA
			ELSE
				SELECT TOP 1 @PROA_CNS_INICIAR = H.CONSECUTIVO
				FROM DBO.HCATD H WITH(NOLOCK)
				INNER JOIN DBO.HCA C WITH(NOLOCK) ON C.CONSECUTIVO = H.CONSECUTIVO
				WHERE C.NOADMISION = @NOADMISION
				  AND H.IDSERVICIO = @PROA_IDSERV
				  AND H.CLASE = 'I'
				  AND COALESCE(C.ANULADA, 0) <> 1
				ORDER BY C.FECHA DESC, H.CONSECUTIVO DESC

			IF @PROA_CNS_INICIAR IS NULL
			BEGIN
				SELECT TOP 1 @PROA_CNS_INICIAR = H.CONSECUTIVO
				FROM DBO.HCATD H WITH(NOLOCK)
				INNER JOIN DBO.HCA C WITH(NOLOCK) ON C.CONSECUTIVO = H.CONSECUTIVO
				WHERE C.NOADMISION = @NOADMISION
				  AND H.IDSERVICIO = @PROA_IDSERV
				  AND H.CLASE IN ('I', 'B', 'C')
				  AND COALESCE(C.ANULADA, 0) <> 1
				ORDER BY C.FECHA DESC, H.CONSECUTIVO DESC
			END

			SELECT TOP 1
				@PROA_ESTADO_ART = P.ESTADO,
				@PROA_INF = P.AUT_INFECTOLOGIA,
				@PROA_EPI = P.AUT_EPIDEMIOLOGIA,
				@PROA_DIAS_SOL = P.DIAS_TRATAMIENTO,
				@PROA_DIAS_AUT = COALESCE(P.DIAS_AUTORIZADOS, P.DIAS_TRATAMIENTO),
				@PROA_OBS = P.OBSERVACION
			FROM DBO.HCATD_PROA P WITH(NOLOCK)
			WHERE P.ESTADO_REG = 'A'
			  AND P.NOADMISION = @NOADMISION
			  AND P.IDSERVICIO = @PROA_IDSERV
			ORDER BY
				CASE WHEN @PROA_CNS_INICIAR IS NOT NULL AND P.CONSECUTIVO = @PROA_CNS_INICIAR THEN 0 ELSE 1 END,
				P.FECHA_SOL ASC

			IF @PROA_ESTADO_ART IS NULL
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'Este art�culo requiere autorizaci�n PROA (IART.MAUTORIZACION) y no hay solicitud PROA registrada. No se puede dispensar.'
			ELSE IF @PROA_ESTADO_ART = 'Vencido'
				INSERT INTO @TBLERRORES(ERROR) SELECT 'Este medicamento PROA est� VENCIDO. No se puede dispensar; debe reformularse.'
			ELSE IF @PROA_ESTADO_ART = 'NoAprobado' OR COALESCE(@PROA_INF, '') = 'No' OR COALESCE(@PROA_EPI, 'No') = 'No'
				INSERT INTO @TBLERRORES(ERROR)
				SELECT CONCAT(
					'Este medicamento no fue autorizado por el equipo PROA (Infectolog�a/Epidemiolog�a).',
					CASE WHEN NULLIF(LTRIM(RTRIM(@PROA_OBS)), '') IS NOT NULL THEN CONCAT(' Motivo: ', @PROA_OBS) ELSE '' END
				)
			ELSE IF @PROA_ESTADO_ART = 'Solicitado'
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'Este art�culo requiere autorizaci�n PROA y a�n est� pendiente de respuesta en Seguimiento Epidemiol�gico.'
		END
		-- Fallback legacy RPROAEPI solo si no existe HCATD_PROA y el art�culo exige autorizaci�n
		ELSE IF COALESCE(@MAUTORIZACION_ART, 0) = 1 AND COALESCE(@CONSECUTIVOHCA, '') <> '' AND OBJECT_ID('DBO.HCATD_PROA', 'U') IS NULL
		BEGIN
			SET @CLASEPLANTILLA_HCA = NULL
			SET @ESTADO = NULL
			SELECT @CLASEPLANTILLA_HCA = HCA.CLASEPLANTILLA,
				   @FECHA_PREPRO       = COALESCE(HCA.FECHA, @FECHA_IZSOL)
			FROM HCA WITH(NOLOCK) WHERE HCA.CONSECUTIVO = @CONSECUTIVOHCA
			IF @CLASEPLANTILLA_HCA = 'PRE_PRO'
			BEGIN
				SELECT TOP 1 @ESTADO = HD.ALFANUMERICO
				FROM HCA H WITH(NOLOCK)
				INNER JOIN HCAD HD WITH(NOLOCK) ON HD.CONSECUTIVO = H.CONSECUTIVO
					AND HD.CAMPO = '200' AND COALESCE(HD.ALFANUMERICO, '') <> ''
				WHERE H.CLASEPLANTILLA = 'RPROAEPI'
				  AND H.NOADMISION = @NOADMISION
				  AND (@FECHA_PREPRO IS NULL OR H.FECHA >= @FECHA_PREPRO)
				ORDER BY H.FECHA DESC, H.CONSECUTIVO DESC
				IF COALESCE(@ESTADO, '') = ''
					INSERT INTO @TBLERRORES(ERROR) SELECT 'Este art�culo requiere autorizaci�n PROA y a�n est� pendiente de respuesta.'
				ELSE IF UPPER(LTRIM(RTRIM(@ESTADO))) = 'DENEGADO'
					INSERT INTO @TBLERRORES(ERROR) SELECT 'Este medicamento no fue autorizado por el equipo PROA Epidemiolog�a.'
			END
		END

		-- Medicamento suspendido vigente (FAR_OM_EVENTO CLASE='S', SER.MEDICAMENTOS=1): no dispensar.
		-- Solo solicitudes de admisi�n (HADM). No f�rmulas FORMED* ni CE/TRANS_CE/etc.
		-- Si IZSOLD.CODOM tiene valor, ancla tambi�n a FOE.CODOM; si vac�o, match por admisi�n+servicio.
		IF OBJECT_ID('DBO.FAR_OM_EVENTO', 'U') IS NOT NULL
		   AND EXISTS (
			SELECT 1
			FROM IZSOLD D WITH(NOLOCK)
			INNER JOIN IZSOL Z WITH(NOLOCK) ON Z.CNSIZSOL = D.CNSIZSOL
			INNER JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
			INNER JOIN FAR_OM_EVENTO FOE WITH(NOLOCK)
				ON FOE.NOADMISION = @NOADMISION
			   AND FOE.IDSERVICIO = COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), A.IDSERVICIO)
			   AND FOE.VIGENTE = 1
			   AND FOE.CLASE = 'S'
			   AND (
					NULLIF(LTRIM(RTRIM(D.CODOM)), '') IS NULL
					OR FOE.CODOM = D.CODOM
			   )
			INNER JOIN SER SER_FOE WITH(NOLOCK)
				ON SER_FOE.IDSERVICIO = FOE.IDSERVICIO AND SER_FOE.MEDICAMENTOS = 1
			WHERE D.CNSIZSOLD = @CNSIZSOLD
			  AND Z.CLASE IN ('24HORAS','OMEDICA','SENFER','HPRE')
		)
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'Este medicamento est� suspendido en la orden m�dica. No se puede dispensar.'

		SELECT @CANTIDAD_ENTREGA =  SUM (IZSOLDT.CANTIDADSOL) 
		FROM IZSOLDT  INNER JOIN IZSOLD ON IZSOLDT.CNSIZSOLD = IZSOLD.CNSIZSOLD 
		WHERE IZSOLDT.CNSIZSOLD = @CNSIZSOLD
		
		SELECT @CANTIDAD_ENTREGA=ISNULL(@CANTIDAD_ENTREGA,0)
		
		IF @COMPLETA = 1
		BEGIN
			SELECT @CANTIDAD = @CANTIDADSOL- ISNULL(@CANTIDAD_ENTREGA,0)
		END

		IF COALESCE(@CNSMOV,'') = ''
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No cuenta con CNSMOV'

		-- Guard cr�tico: @CANTIDAD NULL corromper�a EXISLOTE silenciosamente (EXISLOTE - NULL = NULL)
		IF @CANTIDAD IS NULL OR @CANTIDAD <= 0
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La cantidad a entregar debe ser mayor a cero.'
		
		IF @CANTIDAD_ENTREGA>= @CANTIDADSOL
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Este Art�culo ya tiene La Cantidad Cumplida'
		
		IF (@CANTIDAD_ENTREGA + @CANTIDAD)>@CANTIDADSOL
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Cantidad Supera el L�mite.'
		
		IF @CANTIDAD>(SELECT TOP 1 EXISLOTE FROM IEXI WHERE IEXI.IDBODEGA = @IDBODEGA AND IEXI.IDARTICULO=@IDARTICULO_SEL AND NOLOTE = @NOLOTE AND COALESCE(NOLOTEPEDIDO,'') = COALESCE(@NOLOTEPEDIDO,''))
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Se tiene menos articulos en Stock.'
		
		IF (SELECT COUNT(1) FROM @TBLERRORES)>0
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		
		BEGIN TRY 
			EXEC SPK_IZSOLDT_PROCESOS @IDARTICULO, @CNSIZSOLD, 'AGREGAR', @IDSEDE, @IDARTICULO_REAL, @NOLOTE,@CANTIDAD, @CANTIDADSOL,  @CNSMOV, ''
			IF @CANTIDADSOL = (SELECT SUM(COALESCE(CANTIDADSOL,0)) FROM IZSOLDT WHERE CNSIZSOLD= @CNSIZSOLD)
			BEGIN
				UPDATE IZSOLD SET ESTADO = 0 WHERE  CNSIZSOLD = @CNSIZSOLD
			END			
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		--SELECT @IDARTICULO, @IDBODEGA
		IF EXISTS (SELECT 1 FROM IBOD WHERE IDBODEGA = @IDBODEGA AND COALESCE(VALIDASTOCK,0)=1)
		BEGIN
			SELECT DBO.FNK_VALIDA_STOCKS(@IDARTICULO, @IDBODEGA, 1) VALIDASTOCK
		END
		ELSE
		BEGIN
			SELECT NULL VALIDASTOCK
		END
	
		RETURN
	END	
	IF @METODO = 'DEVOLVER'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @CNSMOV = CNSMOV, @CNSIZSOLDT = CNSIZSOLDT
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,CNSIZSOLDT				VARCHAR(20)			'$.CNSIZSOLDT'
		,CNSMOV					VARCHAR(20)			'$.CNSMOV'
		)

		SELECT @CANTIDAD= CANTIDADSOL,@CNSIZSOLD= CNSIZSOLD, @NOLOTE = NOLOTE  FROM IZSOLDT WHERE CNSIZSOLDT = @CNSIZSOLDT

		SELECT @IDARTICULO = IDARTICULO, @CANTIDADSOL = CANTIDADSOL FROM IZSOLD WHERE CNSIZSOLD = @CNSIZSOLD
		SELECT @IDSEDE =  IDSEDE FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL
		SELECT TOP 1 @IDARTICULO_REAL =  IDARTICULO FROM IEXI WHERE NOLOTE = @NOLOTE


		BEGIN TRY 
	
			EXEC SPK_IZSOLDT_PROCESOS @IDARTICULO, @CNSIZSOLD, 'QUITAR', @IDSEDE, @IDARTICULO_REAL, @NOLOTE,@CANTIDAD, @CANTIDADSOL,  @CNSMOV, @CNSIZSOLDT
			UPDATE IZSOLD SET ESTADO=1 WHERE CNSIZSOLD =  @CNSIZSOLD AND IDARTICULO = @IDARTICULO

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END	
	IF @METODO = 'PROCESAR'
	BEGIN
	SELECT @CNSIZSOL = CNSIZSOL, @CNSMOV = CNSMOV, @IDSERVICIO_CIR = IDSERVICIO
	FROM OPENJSON (@PARAMETROS)
	WITH (
	  CNSIZSOL   VARCHAR(20) '$.CNSIZSOL',
	  CNSMOV     VARCHAR(20) '$.CNSMOV',
	  IDSERVICIO VARCHAR(20) '$.IDSERVICIO'
	)
		SELECT @IDSEDE =  IDSEDE FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL
		SET @ES_MANUALCE = 0
		SELECT @ES_MANUALCE = CASE
			WHEN IZSOL.CLASE = 'TRANS_CE' THEN 1
			WHEN IZSOL.CLASE = 'CE' AND COALESCE(AUT.MANUALCE, 0) = 1 THEN 1
			ELSE 0
		END
		FROM IZSOL WITH (NOLOCK)
		LEFT JOIN AUT WITH (NOLOCK) ON AUT.IDAUT = IZSOL.NOADMISION
		WHERE IZSOL.CNSIZSOL = @CNSIZSOL

		-- Carrera: lote ya en IZSOLDT (ESTADO=0) pero la OM se suspendi� antes de Procesar.
		-- Solo solicitudes de admisi�n (HADM). No f�rmulas FORMED* ni CE/TRANS_CE/etc.
		SELECT @NOADMISION = NOADMISION, @CLASE = CLASE FROM IZSOL WITH(NOLOCK) WHERE CNSIZSOL = @CNSIZSOL
		IF OBJECT_ID('DBO.FAR_OM_EVENTO', 'U') IS NOT NULL
		   AND @CLASE IN ('24HORAS','OMEDICA','SENFER','HPRE')
		   AND EXISTS (
			SELECT 1
			FROM IZSOLDT DT WITH(NOLOCK)
			INNER JOIN IZSOLD D WITH(NOLOCK) ON D.CNSIZSOLD = DT.CNSIZSOLD
			INNER JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
			INNER JOIN FAR_OM_EVENTO FOE WITH(NOLOCK)
				ON FOE.NOADMISION = @NOADMISION
			   AND FOE.IDSERVICIO = COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), A.IDSERVICIO)
			   AND FOE.VIGENTE = 1
			   AND FOE.CLASE = 'S'
			   AND (
					NULLIF(LTRIM(RTRIM(D.CODOM)), '') IS NULL
					OR FOE.CODOM = D.CODOM
			   )
			INNER JOIN SER SER_FOE WITH(NOLOCK)
				ON SER_FOE.IDSERVICIO = FOE.IDSERVICIO AND SER_FOE.MEDICAMENTOS = 1
			WHERE D.CNSIZSOL = @CNSIZSOL
			  AND DT.ESTADO = 0
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'Hay art�culos pendientes con medicamento suspendido en la orden m�dica. No se puede procesar la dispensaci�n.'
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY
			IF @ES_MANUALCE = 1
			BEGIN
				DECLARE @MOVS_PROC TABLE (CNSMOV VARCHAR(20) PRIMARY KEY)
				INSERT INTO @MOVS_PROC (CNSMOV)
				SELECT IMOV.CNSMOV
				FROM IMOV
				WHERE IMOV.NODOCUMENTO = @CNSIZSOL
				  AND IMOV.ESTADO = 0
				  AND COALESCE(IMOV.PROCEDENCIA,'') <> 'DEVOLUCION'
				IF COALESCE(@CNSMOV,'') <> '' AND NOT EXISTS (SELECT 1 FROM @MOVS_PROC WHERE CNSMOV = @CNSMOV)
					INSERT INTO @MOVS_PROC (CNSMOV) VALUES (@CNSMOV)
				DECLARE @CNSMOV_PROC VARCHAR(20)
				DECLARE CUR_PROC CURSOR LOCAL FAST_FORWARD FOR SELECT CNSMOV FROM @MOVS_PROC
				OPEN CUR_PROC
				FETCH NEXT FROM CUR_PROC INTO @CNSMOV_PROC
				WHILE @@FETCH_STATUS = 0
				BEGIN
					EXEC SPK_PROCESA_IZSOLDT @CNSIZSOL, @CNSMOV_PROC, '01', @IDSEDE, @USUARIO
					IF COALESCE(@IDSERVICIO_CIR,'') <> ''
						UPDATE IMOV SET IDSERVICIO = @IDSERVICIO_CIR WHERE CNSMOV = @CNSMOV_PROC
					FETCH NEXT FROM CUR_PROC INTO @CNSMOV_PROC
				END
				CLOSE CUR_PROC
				DEALLOCATE CUR_PROC
			END
			ELSE
			BEGIN
				EXEC SPK_PROCESA_IZSOLDT @CNSIZSOL, @CNSMOV, '01', @IDSEDE, @USUARIO
				UPDATE IMOV SET IDSERVICIO = @IDSERVICIO_CIR WHERE CNSMOV = @CNSMOV
			END
			UPDATE IZSOL SET SYS_ENTREGA = '', SYS_COMPUTER = '' WHERE CNSIZSOL = @CNSIZSOL
		END TRY
		BEGIN CATCH
			IF CURSOR_STATUS('local', 'CUR_PROC') >= 0
			BEGIN
				CLOSE CUR_PROC
				DEALLOCATE CUR_PROC
			END
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END	
	IF @METODO = 'AGREGAR_TOMAR'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		)
		UPDATE IZSOL SET SYS_ENTREGA = @SYS_COMPUTERNAME WHERE CNSIZSOL = @CNSIZSOL
		SELECT 'OK' OK
	END
	IF @METODO = 'AGREGAR'
	BEGIN
	

		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		)

	
		SELECT @CLASE =  IZSOL.CLASE,@NOADMISION = IZSOL.NOADMISION, @CONSECUTIVOHCA = IZSOL.CONSECUTIVOHCA, @FECHA_IZSOL = IZSOL.FECHASOL, @SYS_ENTREGA = COALESCE(IZSOL.SYS_ENTREGA,''), @IDSEDE = COALESCE(IZSOL.IDSEDE,@SEDE)  
		, @GRUPOABO = (SELECT GRUPOABO FROM DBO.FNK_GRUPOSANG_AFI(AFI.IDAFILIADO)), @GRUPORH = (SELECT GRUPORH FROM DBO.FNK_GRUPOSANG_AFI(AFI.IDAFILIADO))  
		FROM  IZSOL
		LEFT JOIN HADM ON IZSOL.NOADMISION = HADM.NOADMISION
		LEFT JOIN AFI ON HADM.IDAFILIADO = AFI.IDAFILIADO
		WHERE  CNSIZSOL = @CNSIZSOL

		/* Transcripciones CE (TRANS_CE / MANUALCE): flujo externo a HADM/caja */
		SET @ES_MANUALCE = 0
		SELECT @ES_MANUALCE = CASE
			WHEN IZSOL.CLASE = 'TRANS_CE' THEN 1
			WHEN IZSOL.CLASE = 'FORMEDCE' THEN 1
			WHEN IZSOL.CLASE = 'CE' AND COALESCE(AUT.MANUALCE, 0) = 1 THEN 1
			ELSE 0
		END
		FROM IZSOL WITH (NOLOCK)
		LEFT JOIN AUT WITH (NOLOCK) ON AUT.IDAUT = IZSOL.NOADMISION
		WHERE IZSOL.CNSIZSOL = @CNSIZSOL
		
		IF @SYS_ENTREGA <> '' AND @SYS_ENTREGA <> @SYS_COMPUTERNAME
		BEGIN
			SELECT 'TOMAR' DATO  ,  'Este Pedido esta siendo Atendido por otro Equipo. ' + @SYS_ENTREGA +' y el equipo de usted es  '+@SYS_COMPUTERNAME TEXTO
			RETURN
		END

		-- Validaci�n PROA: el gate es por l�nea en ENTREGAR/VALIDA_TOTAL (solo IART.MAUTORIZACION=1).
		-- AGREGAR siempre permite abrir la solicitud para dispensar el resto de medicamentos.

		IF @ES_MANUALCE = 0
		   AND @CLASE NOT IN ('PROD','Consumo', 'CE','TRANS_CE','FORMEDCE','QXPGCX','HPRE')
		   AND EXISTS (SELECT 1 FROM HADM WHERE  NOADMISION = @NOADMISION AND CERRADA IN (SELECT VALUE FROM STRING_SPLIT(dbo.FNK_VALORVARIABLE('ALTAS_QUE_VALIDA_INV'),','))) 
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La Admision se encuentra cerrada. No se puede generar movimientos'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		
		IF @ES_MANUALCE = 0
		   AND @CLASE NOT IN ('PROD','Consumo', 'CE','TRANS_CE','FORMEDCE','QXPGCX','HPRE')
		   AND  DBO.FNK_VALORVARIABLE ('MVIGENCIAIZSOL') = 'SI'
		BEGIN
			IF (SELECT DATEDIFF(HH,FECHASOL, GETDATE()) FROM IZSOL WHERE  CNSIZSOL = @CNSIZSOL) > DBO.FNK_VALORVARIABLE ('HVIGENCIAIZSOL')
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'La Solicitud se encuentra Vencida.... Ya no es posible su Entrega'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
		END
		/* CE: NOADMISION es la orden. TRANS_CE y FORMEDCE guardan el afiliado.
		   Ese n�mero puede ser AUT.IDAUT de otra orden ya anulada (consolidado
		   sep 2026). En transcripci�n la orden de ESTA solicitud es AUT.CNSMOV
		   o AUTE.IDAUT, no el afiliado. */
		IF (
			@CLASE = 'CE'
			AND EXISTS (SELECT 1 FROM AUT WHERE IDAUT = @NOADMISION AND ESTADO = 'Anulada')
		) OR (
			@CLASE IN ('TRANS_CE', 'FORMEDCE')
			AND EXISTS (
				SELECT 1
				FROM AUT A WITH (NOLOCK)
				WHERE A.ESTADO = 'Anulada'
				  AND (
					NULLIF(RTRIM(A.CNSMOV), '') = @CNSIZSOL
					OR EXISTS (
						SELECT 1
						FROM AUTE E WITH (NOLOCK)
						WHERE E.CNSIZSOL = @CNSIZSOL
						  AND NULLIF(RTRIM(E.IDAUT), '') = A.IDAUT
					)
				  )
			)
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT '�La Orden esta Anulada!, No se Pueden Generar Movimientos'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		
		SELECT @GENEROCAJA=GENEROCAJA FROM AUT WHERE IDAUT = @NOADMISION

		/* Copago en caja: solo Autorizador CE cl�sico (no Transcripciones MANUALCE/TRANS_CE) */
		IF @ES_MANUALCE = 0
			AND @CLASE = 'CE' AND @GENEROCAJA=1
			AND NOT EXISTS (SELECT 1 FROM FCJ WHERE PROCEDENCIA='CE'
			AND @NOADMISION IN(NOADMISION,NOPRESTACION)
			AND CERRADA = 1 AND ESTADO = 'P' )
			AND (SELECT DBO.FNK_VALORVARIABLE('IXCOUNTRY')) <> 'PERU'
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR='No se ha recaudado el Copago en Caja... por favor verifique.'
			RETURN
		END

		BEGIN TRY 
		-- no me hace sentido miller suarez
			--IF @IDBODEGA <> DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')
			--BEGIN
			--	IF NOT EXISTS (SELECT 1 FROM IZSOLD WHERE IZSOLD.CNSIZSOL = @CNSIZSOL AND IZSOLD.ESTADO = 1)
			--	BEGIN
			--		SELECT 'OK' OK, 'NO' ABRE
			--		RETURN
			--	END
			--END
			IF EXISTS (SELECT 1 FROM IZSOL WHERE  CNSIZSOL = @CNSIZSOL AND COALESCE(IDSEDE,'') = '' )
				UPDATE IZSOL SET IDSEDE = @SEDE WHERE CNSIZSOL = @CNSIZSOL

			IF NOT EXISTS (SELECT 1 CNSMOV FROM IMOV WHERE IMOV.NODOCUMENTO = @CNSIZSOL AND IMOV.ESTADO = 0 )
			BEGIN
				BEGIN TRY 
					
					IF @CLASE <> 'Consumo'
					BEGIN
						SELECT @CLASE = 'ENTREGALOG'
					END

					EXEC SPK_CM_GENIMOV_SOL @CNSIZSOL, @IDSEDE, @USUARIO, @CLASE
					--EXEC SPQ_CM_GENIMOV_SOL 
					--	 @CNSIZSOL = @CNSIZSOL
					--	,@SEDE = @IDSEDE
					--	,@SYS_COMPUTERNAME = @SYS_COMPUTERNAME
					--	,@USUARIO = @USUARIO
					--	,@PROCESO = 'ENTREGALOG'
					--	,@IDBODEGA = @IDBODEGA
					 SELECT TOP 1 @CNSMOV= CNSMOV, @IDBODEGA = IMOV.IDBODEGA, @IDBODEGA_DESC = IBOD.DESCRIPCION  FROM IMOV
					 INNER JOIN IBOD ON IMOV.IDBODEGA = IBOD.IDBODEGA
					 WHERE IMOV.NODOCUMENTO = @CNSIZSOL AND IMOV.ESTADO = 0 ORDER BY IMOV.FECHAMOV ASC

					

				END TRY
				BEGIN CATCH
					INSERT INTO @TBLERRORES(ERROR)
					SELECT ERROR_MESSAGE()
				END CATCH
				IF EXISTS(SELECT 1 FROM @TBLERRORES)
				BEGIN
					SELECT 'KO' AS OK
					SELECT ERROR FROM @TBLERRORES
					RETURN
				END
			END
			ELSE
			BEGIN
				SELECT TOP 1 @CNSMOV= CNSMOV, @IDBODEGA = IMOV.IDBODEGA, @IDBODEGA_DESC = IBOD.DESCRIPCION  FROM IMOV
				INNER JOIN IBOD ON IMOV.IDBODEGA = IBOD.IDBODEGA
				WHERE IMOV.NODOCUMENTO = @CNSIZSOL AND IMOV.ESTADO = 0 ORDER BY IMOV.FECHAMOV ASC
			END
			IF EXISTS (SELECT 1 FROM IMOV WHERE NODOCUMENTO = @CNSIZSOL AND COALESCE(IMOV.IDTERCERO,'') = '')  AND COALESCE(@NOADMISION,'')<> ''
			BEGIN
				UPDATE IMOV SET IMOV.IDTERCERO =  HADM.IDTERCERO FROM IMOV, HADM WHERE IMOV.NODOCUMENTO = @CNSIZSOL AND HADM.NOADMISION = @NOADMISION AND COALESCE(IMOV.IDTERCERO,'') = ''
			END
			UPDATE IZSOL SET SYS_ENTREGA = @SYS_COMPUTERNAME WHERE CNSIZSOL = @CNSIZSOL
			SELECT 'OK' OK , @CNSMOV CNSMOV, @IDBODEGA IDBODEGA, @IDBODEGA_DESC IDBODEGA_DESC, @GRUPOABO GRUPOABO ,@GRUPORH GRUPORH

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END	
	IF @METODO = 'VALIDA_CERRAR_IZSOL'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA, @ACCION = ACCION
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
			CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
			,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
			,ACCION					VARCHAR(20)			'$.ACCION'
		)
	
		SELECT @CLASE =  CLASE,@NOADMISION = NOADMISION, @SYS_ENTREGA = COALESCE(SYS_ENTREGA,''), @IDSEDE = (COALESCE (IZSOL.IDSEDE,@SEDE)), @SECTOR = SECTOR  FROM  IZSOL WHERE  CNSIZSOL = @CNSIZSOL

		IF  NOT EXISTS (SELECT 1 FROM IBODS WHERE VALOR = @USUARIO AND UPPER(ACCESO) = 'SI' AND IDBODEGA = @IDBODEGA)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'El Usuario No Tiene Privilegios para continuar'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF @ACCION = 'ABRIR' AND (DBO.FNK_VALORVARIABLE('MVIGENCIAIZSOL')) = 'SI' 
		BEGIN
			IF  (SELECT DATEDIFF(HH, IZSOL.FECHASOL,GETDATE()) FROM IZSOL WITH(NOLOCK) WHERE CNSIZSOL = @CNSIZSOL) > (DBO.FNK_VALORVARIABLE('HVIGENCIAIZSOL'))
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'La Solicitud se encuentra Vencida.... Ya no es posible su Entrega'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
		END
		IF @ACCION = 'CERRAR' AND 
			EXISTS (SELECT 1 FROM IZSOL WITH(NOLOCK)
				INNER JOIN IMOV WITH(NOLOCK) ON IZSOL.CNSIZSOL = IMOV.NODOCUMENTO AND COALESCE(IMOV.ESTADO,0) = 0
				INNER JOIN IMOVH WITH(NOLOCK) ON IMOV.CNSMOV = IMOVH.CNSMOV
				AND IZSOL.CNSIZSOL = @CNSIZSOL)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La Solicitud tiene movimientos con detalle sin Confirmar.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			IF @ACCION = 'CERRAR' AND EXISTS (SELECT 1 FROM IMOV WHERE ESTADO=0 AND PROCEDENCIA='CM_SOL' AND NODOCUMENTO= @CNSIZSOL)
			BEGIN
				SELECT @CNSMOV = CNSMOV FROM IMOV WHERE ESTADO=0 AND PROCEDENCIA='CM_SOL' AND NODOCUMENTO= @CNSIZSOL
				EXEC SPK_PROCESA_IZSOLDT @CNSIZSOL, @CNSMOV, '01', @IDSEDE, @USUARIO
			END
			SELECT 'OK' OK

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'ABRIR_IZSOL'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA, @ACCION = ACCION
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		,ACCION					VARCHAR(20)			'$.ACCION'
		)
	
		SELECT @CLASE =  CLASE,@NOADMISION = NOADMISION, @SYS_ENTREGA = COALESCE(SYS_ENTREGA,''), @IDSEDE = (COALESCE (IZSOL.IDSEDE,@SEDE)), @SECTOR = SECTOR  FROM  IZSOL WHERE  CNSIZSOL = @CNSIZSOL

		IF  (SELECT COUNT(1) FROM IZSOLD WHERE  CNSIZSOL = @CNSIZSOL  AND IZSOLD.ESTADO = 1 ) = 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Esta Solicitud no tiene Item�s Pendientes Por Confirmar'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			UPDATE IZSOL SET ESTADO = 1,
				USUARIOCIERRA = @USUARIO,
				F_CANCEL = NULL,
				SYS_COMPUTER = @SYS_COMPUTERNAME,
				PAUTO = 0
			WHERE IZSOL.CNSIZSOL = @CNSIZSOL

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'CERRAR_IZSOL'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA, @MOTIVO = MOTIVO, @OBSERVACION = OBSERVACION
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		,MOTIVO					VARCHAR(20)			'$.MOTIVO'
		,OBSERVACION			VARCHAR(200)		'$.OBSERVACION'
		)
	
		BEGIN TRY 
			UPDATE IMOV SET ESTADO=2 WHERE PROCEDENCIA='CM_SOL' AND ESTADO=0 AND NODOCUMENTO= @CNSIZSOL
			AND NOT EXISTS (SELECT 1 FROM IMOVH WHERE IMOVH.CNSMOV=IMOV.CNSMOV)

			UPDATE IZSOL SET ESTADO = '2'
			, USUARIOCIERRA= @USUARIO
			, F_CANCEL = DBO.FNK_FECHA_SIN_MLS(GETDATE())
			,SYS_COMPUTER= @SYS_COMPUTERNAME, CODIGOCERRAR = @MOTIVO, DESCRIPCERRAR = @OBSERVACION
			WHERE CNSIZSOL = @CNSIZSOL

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	
	IF @METODO = 'CONF_MOVIMIENTO'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA, @CNSMOV = CNSMOV
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (	CNSIZSOL	VARCHAR(20)		'$.CNSIZSOL'
					,IDBODEGA	VARCHAR(20)		'$.IDBODEGA'
					,CNSMOV		VARCHAR(20)		'$.CNSMOV' )
	
		SELECT @CLASE =  CLASE,@NOADMISION = NOADMISION, @SYS_ENTREGA = COALESCE(SYS_ENTREGA,''), @IDSEDE = (COALESCE (IZSOL.IDSEDE,@SEDE)), @SECTOR = SECTOR  FROM  IZSOL WHERE  CNSIZSOL = @CNSIZSOL

		SET @ES_MANUALCE = 0
		SELECT @ES_MANUALCE = CASE
			WHEN IZSOL.CLASE = 'TRANS_CE' THEN 1
			WHEN IZSOL.CLASE = 'FORMEDCE' THEN 1
			WHEN IZSOL.CLASE = 'CE' AND COALESCE(AUT.MANUALCE, 0) = 1 THEN 1
			ELSE 0
		END
		FROM IZSOL WITH (NOLOCK)
		LEFT JOIN AUT WITH (NOLOCK) ON AUT.IDAUT = IZSOL.NOADMISION
		WHERE IZSOL.CNSIZSOL = @CNSIZSOL

		IF  (SELECT ESTADO FROM IMOV WHERE CNSMOV = @CNSMOV) = 1
		BEGIN
			SELECT 'OK' OK
			--INSERT INTO @TBLERRORES(ERROR) SELECT 'El movimiento se encuentra Confirmado'
			--SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF @ES_MANUALCE = 0
		   AND @CLASE NOT IN ('PROD','Consumo', 'CE', 'TRANS_CE', 'FORMEDCE')
		   AND @SECTOR <> 'FORMULA'
		   AND EXISTS (SELECT 1 FROM HADM WHERE  NOADMISION = @NOADMISION AND CERRADA = 1 AND FACTURABLE = 1) --STORRES 
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La Admision se encuentra cerrada. No se puede generar movimientos'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF DBO.FNK_VALORVARIABLE('IXCOUNTRY') = 'PERU' AND EXISTS (SELECT 1 FROM HPREP WHERE CNSIZSOL = @CNSIZSOL AND ESTADO <> 2)
      BEGIN
         SELECT @NOPRESUPUESTO = NOPRESUPUESTO FROM HPREP WHERE CNSIZSOL = @CNSIZSOL AND ESTADO <> 2
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Esta asociado a un Presupuesto, el cual aun no esta aprobado.' + ' '+  ISNULL(@NOPRESUPUESTO, '')
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF  (SELECT COUNT(1) FROM IMOVH WHERE CNSMOV = @CNSMOV)=0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No  Hay Ning�n Articulo Para Confirmar'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			IF @CLASE IN ('OMEDICA','24HORAS') 
			BEGIN
				SELECT @IDTERCERO = IDTERCERO FROM HADM WHERE  NOADMISION = @NOADMISION
				SELECT @IDAREA = IDAREA,@CCOSTO = CCOSTO FROM HHAB WHERE NOADMISION = @NOADMISION
			END
			IF @CLASE IN ('CE', 'TRANS_CE') 
			BEGIN
				SELECT @IDTERCERO = IDTERCEROCA, @IDAREA = IDAREA,@CCOSTO = CCOSTO FROM AUT WHERE IDAUT = @NOADMISION
			END

			IF COALESCE(@IDTERCERO,'') <> ''
			BEGIN
				UPDATE IMOV SET IDTERCERO = @IDTERCERO WHERE CNSMOV = @CNSMOV
			END
			IF COALESCE(@IDAREA,'') <> ''
			BEGIN
				UPDATE IMOV SET IDAREA = @IDAREA WHERE CNSMOV = @CNSMOV AND COALESCE(IDAREA, '') = ''
				UPDATE IMOV SET CCOSTO = @CCOSTO WHERE CNSMOV = @CNSMOV AND COALESCE(CCOSTO, '') = ''

			END
			
			PRINT 'ENTRA  SPK_CONFIRMASAL_CM '
			EXEC SPK_CONFIRMASAL_CM @CNSMOV , @USUARIO, @IDSEDE, 'LOG_PROD'
			PRINT 'SALEEE  SPK_CONFIRMASAL_CM '
			SELECT @ESTADO_IMOV = ESTADO FROM IMOV WHERE CNSMOV = @CNSMOV

			/* IZSOLD.ESTADO=1 = a�n hay faltante. Si una l�nea se insert� en 0
			   o PROCESAR la dej� en 0 con cantidad pendiente, al confirmar se
			   reabre esa l�nea para que el IZSOL no se cierre. */
			UPDATE D
			SET D.ESTADO = CASE
				WHEN COALESCE(D.CANTIDADSOL, 0) > COALESCE(X.ENTREGADO, 0) THEN 1
				ELSE 0
			END
			FROM IZSOLD D
			LEFT JOIN (
				SELECT T.CNSIZSOLD, SUM(COALESCE(T.CANTIDADSOL, 0)) ENTREGADO
				FROM IZSOLDT T WITH (NOLOCK)
				GROUP BY T.CNSIZSOLD
			) X ON X.CNSIZSOLD = D.CNSIZSOLD
			WHERE D.CNSIZSOL = @CNSIZSOL

			IF @ESTADO_IMOV = '1'
			BEGIN
				/* GENCOBRO inserta HPRE y esa tabla exige una admisi�n real (FK a HADM).
				   FORMEDCE y TRANS_CE guardan el afiliado en NOADMISION: el INSERT falla
				   y el movimiento ya qued� confirmado. Solo se cobra si la admisi�n existe. */
				IF @CLASE NOT IN ('PROD','Consumo')
				   --AND EXISTS (SELECT 1 FROM HADM WITH (NOLOCK) WHERE NOADMISION = @NOADMISION)
				BEGIN
					EXEC SPK_GENCOBRO_INSCENTRAL @CNSMOV, @NOADMISION, @SECTOR, @USUARIO, @IDSEDE
				END
				-- Insumos no pasan por A_RECIBIR: cerrar RENFER sin IENF (cobro ya ocurri� en GENCOBRO / SENFER)
				IF COALESCE(DBO.FNK_VALORVARIABLE('IENF_RECIBE_INSUMOS'), 'NO') <> 'SI'
				BEGIN
					UPDATE H
					SET H.RENFER = 1,
						H.CANTREP = CASE
							WHEN ISNULL(H.CANTREP, 0) >= ISNULL(H.CANTIDAD, 0) THEN H.CANTREP
							ELSE H.CANTIDAD
						END,
						H.USUARIOR = @USUARIO
					FROM IMOVH H
					INNER JOIN SER ON SER.IDSERVICIO = H.IDSERVICIO
					WHERE H.CNSMOV = @CNSMOV
					  AND ISNULL(SER.MEDICAMENTOS, 0) = 0
					  AND ISNULL(H.RENFER, 0) IN (0, 2)
				END
			END

			IF (SELECT COUNT(1) FROM IZSOLD WHERE CNSIZSOL= @CNSIZSOL AND ESTADO = 1)=0
			BEGIN
				UPDATE IZSOL
				SET ESTADO = 2,
					USUARIOCIERRA = COALESCE(USUARIOCIERRA, @USUARIO),
					F_CANCEL = COALESCE(F_CANCEL, DBO.FNK_FECHA_SIN_MLS(GETDATE()))
				WHERE CNSIZSOL = @CNSIZSOL
			END

			/* CUM del art�culo realmente dispensado (IMOVH) ? AUTD.CODCUM_DISP. No usar IDAUT anterior en recreaci�n Per� CE (se llena en el INSERT de AUTD). */
			IF @ESTADO_IMOV = '1'
				AND NOT (DBO.FNK_VALORVARIABLE('IXCOUNTRY') = 'PERU' AND @CLASE IN ('CE', 'TRANS_CE'))
			BEGIN
				UPDATE AD
				SET AD.CODCUM_DISP = SRC.CODCUM
				FROM AUTD AD
				INNER JOIN (
					SELECT IMOVH.IDSERVICIO, MAX(IMOVH.CODCUM) AS CODCUM
					FROM IMOVH
					WHERE IMOVH.CNSMOV = @CNSMOV
						AND COALESCE(IMOVH.IDSERVICIO, '') <> ''
					GROUP BY IMOVH.IDSERVICIO
				) SRC ON AD.IDSERVICIO = SRC.IDSERVICIO
				WHERE AD.IDAUT = @NOADMISION;
			END

			IF DBO.FNK_VALORVARIABLE('IXCOUNTRY') = 'PERU' AND @CLASE IN ('CE', 'TRANS_CE')
			BEGIN
				UPDATE AUT SET AUT.ESTADO = 'AnuladaPE' WHERE AUT.IDAUT = @NOADMISION

				PRINT 'Genero consecutivo IDAUT'
				EXEC SPK_GENCONSECUTIVO '01',@SEDE,'@AUT',@IDAUT OUTPUT
				SELECT @IDAUT = @SEDE + RIGHT('00000000'+CONVERT(VARCHAR(8),@IDAUT),8)
				PRINT @IDAUT

				PRINT 'Genero consecutivo NOAUT'
				EXEC SPK_GENCONSECUTIVO '01',@SEDE,'@AUTF',@NOAUT OUTPUT
				SELECT @NOAUT = @SEDE + RIGHT('00000000'+CONVERT(VARCHAR(8),@NOAUT),8)
				PRINT @NOAUT 
				--CNSMOV
				INSERT INTO AUT (IDAUT, NOAUT, FECHA, FECHAVENCE, IDAFILIADO, NUMCARNET, IDPLAN, PREFIJO, IDSEDE, TIPOAUTORIZACION, 
					ALTOCOSTO, ATENCION, IMPUTABLE_A, IDSOLICITANTE, IDPROVEEDOR, ESTADO, AUTORIZADOPOR, FECHAAUTORIZA, IDPESPECIAL, AUTORIZADO, 
					USUARIO, IDCAUSAEXT, AMBITO, FINALIDAD, PERSONAL_AT, DXPPAL, TIPOURGENCIA, SPD, IDCONTRATANTE, TIPOCOPAGO, 
					CLASECONT, FECHAGEN, PROCEDENCIA, IDAREAH, IDAREA, CCOSTO, NIVELATENCION, FACTURADA, FACTURABLE, IDIPS, 
					CLASECONTRATO, ENPAQUETE, SOAT, COBRARA, IDTERCEROCA, CONSECUTIVOHCA, SYS_COMPUTERNAME, TIPOUSUARIO, IDPLAN_AFI, IDTERCERO_AFI, 
					CLASEORDEN, URGENCIA, VALORBENEFICIO, VALOREXEDENTE, VALORTOTALCOSTO, VALORCOPAGOCOSTO, IMPRESO, CXPGEN, CXCGEN, PEDIDOINV,
					ESCONTINUACION, SEMANASCOT, LIQUIDAPC, ESDEINV, VFACTURAS, DESCUENTO, MARCAFAC, PERIODICIDAD, CONTINUACION, MARCAENV,
					COPAGOPROPIO, ESDELAB, ENLAB, PIDECCOSTO, RIESGO, NUMAUTORIZA, TIPOAFILIADO, MENTREGA, CNSMOV)
				SELECT @IDAUT, @NOAUT, DBO.FNK_GETDATE(), DBO.FNK_GETDATE(), IDAFILIADO, NUMCARNET, IDPLAN, PREFIJO, IDSEDE, TIPOAUTORIZACION, 
					ALTOCOSTO, ATENCION, IMPUTABLE_A, IDSOLICITANTE, IDPROVEEDOR, ESTADO, AUTORIZADOPOR, FECHAAUTORIZA, IDPESPECIAL, AUTORIZADO, 
					USUARIO, IDCAUSAEXT, AMBITO, FINALIDAD, PERSONAL_AT, DXPPAL, TIPOURGENCIA, SPD, IDCONTRATANTE, TIPOCOPAGO, 
					CLASECONT, FECHAGEN, PROCEDENCIA, IDAREAH, IDAREA, CCOSTO, NIVELATENCION, FACTURADA, FACTURABLE, IDIPS, 
					CLASECONTRATO, ENPAQUETE, SOAT, COBRARA, IDTERCEROCA, CONSECUTIVOHCA, SYS_COMPUTERNAME, TIPOUSUARIO, IDPLAN_AFI, IDTERCERO_AFI, 
					CLASEORDEN, URGENCIA, VALORBENEFICIO, VALOREXEDENTE, VALORTOTALCOSTO, VALORCOPAGOCOSTO, IMPRESO, CXPGEN, CXCGEN, PEDIDOINV,
					ESCONTINUACION, SEMANASCOT, LIQUIDAPC, ESDEINV, VFACTURAS, DESCUENTO, MARCAFAC, PERIODICIDAD, CONTINUACION, MARCAENV,
					COPAGOPROPIO, ESDELAB, ENLAB, PIDECCOSTO, RIESGO, NUMAUTORIZA, TIPOAFILIADO, MENTREGA, @CNSMOV
				FROM AUT WHERE AUT.IDAUT = @NOADMISION

				INSERT INTO AUTD ( IDAUT, NO_ITEM, IDSERVICIO, CANTIDAD, VALOR, VALORCOPAGO, VALORCOPAGOCOSTO, VALOREXCEDENTE, VALORTOTALCOSTO, IDPLAN, 
					IMPRESO, AUTORIZADO, COMENTARIOS, PCOBERTURA, OBS, NORDEN, CCOSTO, CODIGOCPCJ, MARCAPAGO, NOAUTORIZEXT, 
					ESDELAB, ENLAB, IDTERCEROCA, IDCONTRATO, FACTURADA, N_FACTURA, CNSFCT, AQUIENCOBRO, MARCACOPAGOORDEN, VALORPROV, 
					PCOSTO, ITFC, CNSITFC, SYS_COMPUTERNAME, NOCOBRABLE, MDOSIFICACION, CANTIDIA, DIAS, FRECUENCIA, CODCUPS, 
					POSOLOGIA, SINCRONIZADO, APOYODG_AMBITO, CITAAUTORIZADA, CLASEPOSOLOGIA, MARCA, USUARIOMARCA, 
					NUM_ORDEN, PROCESADA, PRIORIDAD, CODCUM_DISP)
				SELECT @IDAUT, ROW_NUMBER() OVER (ORDER BY IMOVH.IDARTICULO), IMOVH.IDARTICULO, IMOVH.CANTIDAD, IMOVH.PCOSTO, 0, 0, 0, IMOVH.PCOSTO*IMOVH.CANTIDAD, AUT.IDPLAN,
					0, 0, '', 100, '', '', AUT.CCOSTO, '', 0, @NOAUT, 
					0, 0, AUT.IDTERCEROCA, 'SIN_DEFINIR', 0, '', '', 'N', 0, NULL, 
					0, 0, NULL, @SYS_COMPUTERNAME, 0, 0, 0, 0, 0, SER.CODCUPS, 
					'', 0, SER.AMBITO, 0, 'Tomar', 0, '', 0, 0, 0, IART.CODCUM
				FROM IMOVH 
				INNER JOIN AUT ON AUT.IDAUT = @IDAUT
				INNER JOIN SER ON IMOVH.IDARTICULO = SER.IDSERVICIO
				LEFT JOIN IART ON IART.IDARTICULO = IMOVH.IDARTICULO
				WHERE IMOVH.CNSMOV = @CNSMOV AND AUT.IDAUT = @IDAUT

				UPDATE IMOV SET NOCONSECUTIVO = @IDAUT WHERE  CNSMOV = @CNSMOV
				UPDATE AUT SET NO_ITEMES = (SELECT COUNT(*) FROM AUTD WHERE AUTD.IDAUT = @IDAUT ) WHERE AUT.IDAUT = @IDAUT

				SELECT  TOP 1 @PREFIJO =   SER.PREFIJO FROM IMOVH 
					INNER JOIN SER ON IMOVH.IDARTICULO = SER.IDSERVICIO
				WHERE CNSMOV = @CNSMOV
				GROUP BY SER.PREFIJO

				UPDATE AUT SET AUT.PREFIJO = @PREFIJO, AUT.CNSMOV = @CNSMOV  WHERE AUT.IDAUT = @IDAUT

			END

         SELECT @IDTERCERO = COALESCE(IDTERCERO,@IDTERCERO), @IDPLAN = COALESCE(IDPLAN,@IDPLAN), @IDSEDE = COALESCE(HADM.IDSEDE,@IDSEDE) FROM HADM WHERE  NOADMISION = @NOADMISION
			IF DBO.FNK_VALORVARIABLE('IXCOUNTRY') = 'PERU' AND EXISTS (SELECT 1 FROM PPT WHERE IDTERCERO = @IDTERCERO AND IDPLAN = @IDPLAN AND PPT_TIPOADM = DBO.FNK_VALORVARIABLE('HTAD_HOSPITA') )
         BEGIN
            EXEC SPK_GENCONSECUTIVO @COMPANIA, @IDSEDE,'@HPRE', @NOPRESTACION OUTPUT  
            SELECT @NOPRESTACION = @IDSEDE + REPLACE(SPACE(8 - LEN(@NOPRESTACION))+LTRIM(RTRIM(@NOPRESTACION)),SPACE(1),0)

            SELECT @CONSECUTIVOHCA = CONSECUTIVOHCA FROM HPREP WHERE NOPRESUPUESTO = @NOPRESUPUESTO
            SELECT  @IDAREA = IDAREA, @CCOSTO = CCOSTO FROM HCA WHERE CONSECUTIVO = @CONSECUTIVOHCA
            IF COALESCE(@IDAREA,'')= ''
            BEGIN
               SELECT TOP 1 @IDAREA = IDAREA FROM HPRE
               WHERE NOADMISION = @NOADMISION ORDER BY  FECHA  DESC
            END
            IF COALESCE(@CCOSTO,'')= ''
            BEGIN
               SELECT TOP 1 @CCOSTO = HPRE.CCOSTO FROM HPRE
               INNER JOIN CEN ON HPRE.CCOSTO = CEN.CCOSTO AND CEN.ESTADO = 'Activo'
               WHERE NOADMISION = @NOADMISION ORDER BY  FECHA  DESC
            END

            INSERT INTO HPRE (NOPRESTACION, NOADMISION, FECHA, IDPLAN, IDAREAH, IDAREA, IDSEDE, ALTOCOSTO, USUARIO, CERRADA,PCUBRIMIENTO,
					            ESDEINV, PEDIDOINV, INDDEVOLUCION, PREFIJO,CCOSTO, FINALIDAD, AMBITO, PERSONAL_AT, IDAREAEQUIPO,IDMEDICO, 
					            COBRARA, IDTERCEROCA, SYS_COMPUTERNAME, IDAREAAUX, ENLAB, ANULADO, PROCEDENCIA, NOPRESUPUESTO)
            SELECT @NOPRESTACION, @NOADMISION, DBO.FNK_GETDATE(), @IDPLAN , '01', @IDAREA, @IDSEDE, 'No',@USUARIO, 0, 100.00
               ,0,0, 0, SER.PREFIJO, @CCOSTO, 1,NULL, NULL, NULL, NULL,'C', @IDTERCERO, 'CAJERO_MANUAL', NULL, 0, 0, 'IMOV',@CNSMOV
            FROM IMOVH
                  INNER JOIN SER ON IMOVH.IDARTICULO = SER.IDSERVICIO
                  INNER JOIN SER SER_PAPA ON IMOVH.IDSERVICIO = SER_PAPA.IDSERVICIO
               WHERE IMOVH.CNSMOV = @CNSMOV 
                  AND SER.PREFIJO = DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS')
                  AND COALESCE(SER_PAPA.PHD,0)=0 
               GROUP BY  SER.PREFIJO

            INSERT INTO HPRED (NOPRESTACION, NOITEM, IDSERVICIO, CANTIDAD, IDPLAN, COMENTARIOS, IDCONCEPTORIPS, USUARIO,TIPOSERCIRUGIA,FECHA,
				            VIA,IDAREA,COBRARA, IDTERCEROCA, PCUBRIMIENTO, TIPODTO,DESCUENTO,CCOSTO,AQUIENCOBRO,CODCUPS,VALOR, NOAUTORIZACION,IDPROVEEDOR, PAQUETE)
            SELECT @NOPRESTACION, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS NOITEM, SER.IDSERVICIO,IMOVH.CANTIDAD,@IDPLAN, '', '01',@USUARIO,NULL,dbo.FNK_FECHA_SIN_MLS(GETDATE()),
		            'NA', @IDAREA, 'C', @IDTERCERO, 100, 'N', 0, @CCOSTO,NULL,NULL, NULL , NULL, NULL, 0
            FROM IMOVH
                  INNER JOIN SER ON IMOVH.IDARTICULO = SER.IDSERVICIO
                  INNER JOIN SER SER_PAPA ON IMOVH.IDSERVICIO = SER_PAPA.IDSERVICIO
               WHERE IMOVH.CNSMOV = @CNSMOV 
                  AND SER.PREFIJO = DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS')
                  AND COALESCE(SER_PAPA.PHD,0)=0 

            SELECT @SQL='{"MODELO":"HPRE","METODO":"RELIQUIDAR","PARAMETROS":{"NOADMISION":"'+@NOADMISION+'", "NOPRESTACION":"'+@NOPRESTACION+'"},"USUARIO":"'+@USUARIO+'"}'
            EXEC SPQ_JSON @SQL
         END

			/* CE / TRANS_CE: re-enlazar AUT con la solicitud/movimiento confirmado.
			   Cubre primera dispensaci�n y redispensa tras PROCESAR_DEVOLUCION (clon IZSOL).
			   Colombia: AUT.CNSMOV = CNSIZSOL (comprobante VER_REPORTE_REM_SERV).
			   Per�: AUT.CNSMOV = CNSMOV del IMOV.
			   TRANS_CE: NOADMISION puede ser a�n IDAFILIADO - no tocar AUT fantasma
			   con IDAUT = ese afiliado (colisi�n). Solo Autorizador (CE) o MANUALCE. */
			IF @ESTADO_IMOV = '1' AND @CLASE IN ('CE', 'TRANS_CE') AND COALESCE(@NOADMISION, '') <> ''
				AND EXISTS (SELECT 1 FROM AUT WHERE IDAUT = @NOADMISION)
				AND @CNSIZSOL NOT LIKE '%-D'
				AND (
					@CLASE = 'CE'
					OR COALESCE((SELECT TOP 1 MANUALCE FROM AUT WITH (NOLOCK) WHERE IDAUT = @NOADMISION), 0) = 1
				)
				AND NOT (
					@CLASE = 'TRANS_CE'
					AND EXISTS (SELECT 1 FROM AFI WITH (NOLOCK) WHERE IDAFILIADO = @NOADMISION)
				)
			BEGIN
				IF DBO.FNK_VALORVARIABLE('IXCOUNTRY') = 'PERU'
				BEGIN
					UPDATE AUT
					SET CNSMOV = @CNSMOV,
						ENTREGADO = 1,
						FENTREGA = DBO.FNK_GETDATE(),
						UENTREGA = @USUARIO
					WHERE IDAUT = @NOADMISION
				END
				ELSE
				BEGIN
					UPDATE AUT
					SET CNSMOV = @CNSIZSOL,
						ENTREGADO = 1,
						FENTREGA = DBO.FNK_GETDATE(),
						UENTREGA = @USUARIO
					WHERE IDAUT = @NOADMISION
				END
			END

			IF @ESTADO_IMOV = '1' AND @CLASE = 'APLIM'
			BEGIN
				PRINT 'APLIM: marcar medicamentos dispensados al confirmar salida'
				-- Enlaza por IZSOLD.IDAPLIMF + IZSOLDT del movimiento confirmado (@CNSMOV).
				-- Aplica para custodia (RESERVADO) y farmacia (SOLICITADO A FARMACIA), sin depender de APLIM_GESTIONA_FAR.
				UPDATE APLIMF SET
					APLIMF.IDARTICULO   = COALESCE(
						NULLIF(LTRIM(RTRIM(IZSOLDT.IDARTICULOREAL)), ''),
						NULLIF(LTRIM(RTRIM(IZSOLDT.IDARTICULO)), ''),
						APLIMF.IDARTICULO
					),
					APLIMF.CNSMOV       = @CNSMOV,
					APLIMF.DISPENSADO   = 1,
					APLIMF.FDISPENSADO  = IMOV.FECHACONF,
					APLIMF.ESTADO       = 'DISPENSADO'
				FROM APLIMF
				INNER JOIN IZSOLD  ON IZSOLD.IDAPLIMF = APLIMF.ID
				                AND IZSOLD.CNSIZSOL   = @CNSIZSOL
				INNER JOIN IZSOLDT ON IZSOLDT.CNSIZSOLD = IZSOLD.CNSIZSOLD
				                AND IZSOLDT.CNSMOV    = @CNSMOV
				INNER JOIN IMOV    ON IMOV.CNSMOV = @CNSMOV
				WHERE APLIMF.ESTADO IN ('RESERVADO', 'SOLICITADO A FARMACIA')
				  AND COALESCE(APLIMF.ESTADO, '') <> 'DISPENSADO';

			END
         IF DBO.FNK_VALORVARIABLE('IXCOUNTRY')='PERU'
         BEGIN
	         IF DBO.FNK_VALORVARIABLE('INTERFAZ_INV')='INTER_SAP'
	         BEGIN
		         PRINT 'INICIO EL ENVIO A SAP'
		         EXEC SPK_XML_MOVIN @CNSMOV
		         PRINT 'REGRESO DE ENVIO A SAP'
	         END 
         END


		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END

	IF @METODO = 'VALIDA_CODIGO_BARRA'
	BEGIN
		SELECT @IDARTICULO = JSON_VALUE(@PARAMETROS, '$.IDARTICULO')
		
		BEGIN TRY 
			SELECT 'OK' OK
			SELECT TABLA, CAMPO, CODIGO, DATO1 FROM TGEN WHERE  TABLA ='IART' AND CAMPO = 'CODEBAR' AND DATO1 = @IDARTICULO
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END

	IF @METODO = 'VALIDA_CODIGO_CANASTA'
	BEGIN
		DECLARE
			@CODIGO_VC         VARCHAR(100),
			@CNSMOV_VC         VARCHAR(20),
			@CNSIZSOL_VC       VARCHAR(20),
			@IDBODEGA_VC       VARCHAR(20),
			@CONTINUAR_FEFO_VC INT,
			@IDARTICULO_VC     VARCHAR(20),
			@NOLOTE_VC         VARCHAR(20),
			@FECHAVENCE_VC     DATETIME,
			@EXISLOTE_VC       DECIMAL(14,2),
			@NOLOTE_FEFO_VC    VARCHAR(20),
			@FECHA_FEFO_VC     DATETIME,
			@EXIS_FEFO_VC      DECIMAL(14,2);

		SELECT
			@CODIGO_VC         = P.CODIGO,
			@CNSMOV_VC         = P.CNSMOV,
			@CNSIZSOL_VC       = P.CNSIZSOL,
			@IDBODEGA_VC       = P.IDBODEGA,
			@CONTINUAR_FEFO_VC = ISNULL(P.CONTINUAR_FEFO, 0)
		FROM OPENJSON(@PARAMETROS)
		WITH (
			CODIGO          VARCHAR(100) '$.CODIGO',
			CNSMOV          VARCHAR(20)  '$.CNSMOV',
			CNSIZSOL        VARCHAR(20)  '$.CNSIZSOL',
			IDBODEGA        VARCHAR(20)  '$.IDBODEGA',
			CONTINUAR_FEFO  INT          '$.CONTINUAR_FEFO'
		) P;

		SET @CODIGO_VC   = LTRIM(RTRIM(ISNULL(@CODIGO_VC,'')));
		SET @IDBODEGA_VC = LTRIM(RTRIM(ISNULL(@IDBODEGA_VC,'')));

		IF @CODIGO_VC = ''
		BEGIN
			SELECT 'ERROR' AS OK, 'Debe enviar CODIGO' AS ERROR;
			RETURN;
		END;

		/* Buscar por NOLOTE directo en IEXI */
		SELECT TOP 1
			@IDARTICULO_VC = LTRIM(RTRIM(X.IDARTICULO)),
			@NOLOTE_VC     = X.NOLOTE,
			@FECHAVENCE_VC = X.FECHAVENCE,
			@EXISLOTE_VC   = X.EXISLOTE
		FROM IEXI X
		WHERE X.NOLOTE = @CODIGO_VC
		  AND X.IDBODEGA = @IDBODEGA_VC
		  AND ISNULL(X.EXISLOTE, 0) > 0
		ORDER BY X.FECHAVENCE ASC;

		/* Si no encontr� por lote, buscar c�digo de empaque en TGEN */
		IF @IDARTICULO_VC IS NULL
		BEGIN
			SELECT TOP 1 @IDARTICULO_VC = LTRIM(RTRIM(T.DATO1))
			FROM TGEN T
			WHERE T.TABLA = 'IART'
			  AND T.CAMPO = 'CODEBAR'
			  AND T.CODIGO = @CODIGO_VC;

			IF @IDARTICULO_VC IS NOT NULL
			BEGIN
				SELECT TOP 1
					@NOLOTE_VC     = X.NOLOTE,
					@FECHAVENCE_VC = X.FECHAVENCE,
					@EXISLOTE_VC   = X.EXISLOTE
				FROM IEXI X
				WHERE LTRIM(RTRIM(X.IDARTICULO)) = @IDARTICULO_VC
				  AND X.IDBODEGA = @IDBODEGA_VC
				  AND ISNULL(X.EXISLOTE, 0) > 0
				ORDER BY X.FECHAVENCE ASC;
			END
		END;

		IF @IDARTICULO_VC IS NULL OR @NOLOTE_VC IS NULL
		BEGIN
			SELECT 'ERROR' AS OK,
				   'No se encontr� lote/c�digo en inventario para la bodega actual' AS ERROR;
			RETURN;
		END;

		/* Validaci�n FEFO */
		SELECT TOP 1
			@NOLOTE_FEFO_VC = X.NOLOTE,
			@FECHA_FEFO_VC  = X.FECHAVENCE,
			@EXIS_FEFO_VC   = X.EXISLOTE
		FROM IEXI X
		WHERE LTRIM(RTRIM(X.IDARTICULO)) = @IDARTICULO_VC
		  AND X.IDBODEGA = @IDBODEGA_VC
		  AND ISNULL(X.EXISLOTE, 0) > 0
		ORDER BY X.FECHAVENCE ASC;

		IF ISNULL(@CONTINUAR_FEFO_VC, 0) = 0
		   AND @NOLOTE_FEFO_VC IS NOT NULL
		   AND ISNULL(@NOLOTE_FEFO_VC,'') <> ISNULL(@NOLOTE_VC,'')
		BEGIN
			SELECT
				'ADVERTENCIA_FEFO'      AS OK,
				1                       AS REQUIERE_CONFIRMACION,
				CONCAT(
					'El lote escaneado vence el ',
					CONVERT(VARCHAR(10), @FECHAVENCE_VC, 103),
					', pero existe un lote que vence antes.'
				)                       AS MENSAJE,
				@IDARTICULO_VC          AS IDARTICULO,
				@NOLOTE_VC              AS NOLOTE_LECTURA,
				@FECHAVENCE_VC          AS FECHAVENCE_LECTURA,
				@EXISLOTE_VC            AS EXISLOTE_LECTURA,
				@NOLOTE_FEFO_VC         AS NOLOTE_SUGERIDO,
				@FECHA_FEFO_VC          AS FECHAVENCE_SUGERIDO,
				@EXIS_FEFO_VC           AS EXISLOTE_SUGERIDO;
			RETURN;
		END;

		SELECT
			'OK'            AS OK,
			@IDARTICULO_VC  AS IDARTICULO,
			@NOLOTE_VC      AS NOLOTE,
			@FECHAVENCE_VC  AS FECHAVENCE,
			@EXISLOTE_VC    AS EXISLOTE;
	END

	IF @METODO = 'VALIDA_TOTAL_CANASTA'
	BEGIN
		DECLARE
			@CODIGO_VT           VARCHAR(100),
			@CANTIDAD_VT         DECIMAL(14,2),
			@CNSIZSOL_VT         VARCHAR(20),
			@CNSMOV_VT           VARCHAR(20),
			@IDBODEGA_VT         VARCHAR(20),
			@CONTINUAR_FEFO_VT   INT,
			@IDARTICULO_VT       VARCHAR(20),
			@NOLOTE_VT           VARCHAR(20),
			@FECHAVENCE_VT       DATETIME,
			@EXISLOTE_VT         DECIMAL(14,2),
			@NOLOTE_FEFO_VT      VARCHAR(20),
			@FECHA_FEFO_VT       DATETIME,
			@EXIS_FEFO_VT        DECIMAL(14,2),
			@CNSIZSOLD_VT        VARCHAR(20),
			@IDSEDE_VT           VARCHAR(20),
			@CANTIDADSOL_VT      DECIMAL(14,2);

		SELECT
			@CODIGO_VT         = P.CODIGO,
			@CANTIDAD_VT       = P.CANTIDAD,
			@CNSIZSOL_VT       = P.CNSIZSOL,
			@CNSMOV_VT         = P.CNSMOV,
			@IDBODEGA_VT       = P.IDBODEGA,
			@CONTINUAR_FEFO_VT = ISNULL(P.CONTINUAR_FEFO, 0)
		FROM OPENJSON(@PARAMETROS)
		WITH (
			CODIGO         VARCHAR(100)  '$.CODIGO',
			CANTIDAD       DECIMAL(14,2) '$.CANTIDAD',
			CNSIZSOL       VARCHAR(20)   '$.CNSIZSOL',
			CNSMOV         VARCHAR(20)   '$.CNSMOV',
			IDBODEGA       VARCHAR(20)   '$.IDBODEGA',
			CONTINUAR_FEFO INT           '$.CONTINUAR_FEFO'
		) P;

		SET @CODIGO_VT   = LTRIM(RTRIM(ISNULL(@CODIGO_VT,'')));
		SET @IDBODEGA_VT = LTRIM(RTRIM(ISNULL(@IDBODEGA_VT,'')));
		SET @CNSIZSOL_VT = LTRIM(RTRIM(ISNULL(@CNSIZSOL_VT,'')));

		IF @CODIGO_VT = '' OR ISNULL(@CANTIDAD_VT,0) <= 0
		BEGIN
			SELECT 'ERROR' AS OK, 'Debe enviar CODIGO y CANTIDAD mayor a 0' AS ERROR;
			RETURN;
		END;

		IF @IDBODEGA_VT = '' OR @CNSIZSOL_VT = ''
		BEGIN
			SELECT 'ERROR' AS OK, 'Faltan datos del movimiento (IDBODEGA/CNSIZSOL)' AS ERROR;
			RETURN;
		END;

		SELECT TOP 1
			@IDARTICULO_VT = LTRIM(RTRIM(X.IDARTICULO)),
			@NOLOTE_VT     = X.NOLOTE,
			@FECHAVENCE_VT = X.FECHAVENCE,
			@EXISLOTE_VT   = X.EXISLOTE
		FROM IEXI X
		WHERE X.NOLOTE = @CODIGO_VT
		  AND X.IDBODEGA = @IDBODEGA_VT
		  AND ISNULL(X.EXISLOTE, 0) > 0
		ORDER BY X.FECHAVENCE ASC;

		IF @IDARTICULO_VT IS NULL
		BEGIN
			SELECT TOP 1 @IDARTICULO_VT = LTRIM(RTRIM(T.DATO1))
			FROM TGEN T
			WHERE T.TABLA = 'IART' AND T.CAMPO = 'CODEBAR' AND T.CODIGO = @CODIGO_VT;

			IF @IDARTICULO_VT IS NOT NULL
			BEGIN
				SELECT TOP 1
					@NOLOTE_VT     = X.NOLOTE,
					@FECHAVENCE_VT = X.FECHAVENCE,
					@EXISLOTE_VT   = X.EXISLOTE
				FROM IEXI X
				WHERE LTRIM(RTRIM(X.IDARTICULO)) = @IDARTICULO_VT
				  AND X.IDBODEGA = @IDBODEGA_VT
				  AND ISNULL(X.EXISLOTE, 0) > 0
				ORDER BY X.FECHAVENCE ASC;
			END
		END;

		IF @IDARTICULO_VT IS NULL OR @NOLOTE_VT IS NULL
		BEGIN
			SELECT 'ERROR' AS OK, 'No se encontr� lote/c�digo en inventario para la bodega actual' AS ERROR;
			RETURN;
		END;

		-- Disponibilidad real = EXISLOTE - reservado en otras canastas pendientes
		DECLARE @TIP_MOV_CN_VT  VARCHAR(20)
		DECLARE @RESERVADO_VT   DECIMAL(14,2) = 0
		DECLARE @EXIS_DISP_VT   DECIMAL(14,2)

		SELECT TOP 1 @TIP_MOV_CN_VT = DATO FROM USVGS WHERE IDVARIABLE = 'INVE_CIRU_TIPO_MOV'

		SELECT @RESERVADO_VT = ISNULL(SUM(H.CANTIDAD), 0)
		FROM IMOVH H
		INNER JOIN IMOV M ON M.CNSMOV = H.CNSMOV
		WHERE LTRIM(RTRIM(H.IDARTICULO)) = @IDARTICULO_VT
		  AND H.NOLOTE    = @NOLOTE_VT
		  AND M.IDBODEGA  = @IDBODEGA_VT
		  AND M.ESTADO    = 0                   -- solo canastas pendientes
		  AND M.IDTIPOMOV = @TIP_MOV_CN_VT
		  AND M.CNSMOV   <> @CNSMOV_VT          -- excluir la canasta que est� pistoliando

		SET @EXIS_DISP_VT = ISNULL(@EXISLOTE_VT, 0) - @RESERVADO_VT

		IF ISNULL(@CANTIDAD_VT, 0) > @EXIS_DISP_VT
		BEGIN
			SELECT 'ERROR' AS OK,
				   CONCAT('Cantidad supera disponibilidad real del lote. ',
						  'EXISLOTE: ', CAST(ISNULL(@EXISLOTE_VT,0) AS VARCHAR(20)),
						  ' | Reservado otras canastas: ', CAST(@RESERVADO_VT AS VARCHAR(20)),
						  ' | Disponible: ', CAST(@EXIS_DISP_VT AS VARCHAR(20))) AS ERROR;
			RETURN;
		END;

		SELECT TOP 1
			@NOLOTE_FEFO_VT = X.NOLOTE,
			@FECHA_FEFO_VT  = X.FECHAVENCE,
			@EXIS_FEFO_VT   = X.EXISLOTE
		FROM IEXI X
		WHERE LTRIM(RTRIM(X.IDARTICULO)) = @IDARTICULO_VT
		  AND X.IDBODEGA = @IDBODEGA_VT
		  AND ISNULL(X.EXISLOTE, 0) > 0
		ORDER BY X.FECHAVENCE ASC;

		IF ISNULL(@CONTINUAR_FEFO_VT, 0) = 0
		   AND @NOLOTE_FEFO_VT IS NOT NULL
		   AND ISNULL(@NOLOTE_FEFO_VT,'') <> ISNULL(@NOLOTE_VT,'')
		BEGIN
			SELECT
				'ADVERTENCIA_FEFO' AS OK, 1 AS REQUIERE_CONFIRMACION,
				CONCAT('El lote que estas leyendo tiene fecha de vencimiento ',
					   CONVERT(VARCHAR(10), @FECHAVENCE_VT, 103),
					   ', pero existe un lote que vence antes.') AS MENSAJE,
				@IDARTICULO_VT AS IDARTICULO,
				@NOLOTE_VT AS NOLOTE_LECTURA,      @FECHAVENCE_VT AS FECHAVENCE_LECTURA,
				@EXISLOTE_VT AS EXISLOTE_LECTURA,  @NOLOTE_FEFO_VT AS NOLOTE_SUGERIDO,
				@FECHA_FEFO_VT AS FECHAVENCE_SUGERIDO, @EXIS_FEFO_VT AS EXISLOTE_SUGERIDO;
			RETURN;
		END;

		SELECT @IDSEDE_VT = IDSEDE FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL_VT;

		BEGIN TRY
			BEGIN TRAN;

			SELECT TOP 1 @CNSIZSOLD_VT = D.CNSIZSOLD
			FROM IZSOLD D WITH (UPDLOCK, HOLDLOCK)
			WHERE D.CNSIZSOL = @CNSIZSOL_VT
			  AND LTRIM(RTRIM(D.IDARTICULO)) = @IDARTICULO_VT;

			IF @CNSIZSOLD_VT IS NULL
			BEGIN
				INSERT INTO IZSOLD (CNSIZSOL, IDARTICULO, CANTIDADSOL, ESTADO, CANTIDAD_DISPENSADA, NEWCNSIZOLD)
				VALUES (@CNSIZSOL_VT, @IDARTICULO_VT, 0, 1, 0, '');

				SELECT TOP 1 @CNSIZSOLD_VT = D.CNSIZSOLD
				FROM IZSOLD D
				WHERE D.CNSIZSOL = @CNSIZSOL_VT
				  AND LTRIM(RTRIM(D.IDARTICULO)) = @IDARTICULO_VT
				ORDER BY D.ID DESC;
			END;

			IF ISNULL(@CNSIZSOLD_VT,'') = ''
			   OR NOT EXISTS (SELECT 1 FROM IZSOLD WHERE CNSIZSOLD = @CNSIZSOLD_VT)
			BEGIN
				SELECT 'ERROR' AS OK,
					   CONCAT('No se pudo resolver CNSIZSOLD padre. CNSIZSOL=', @CNSIZSOL_VT,
							  ' IDARTICULO=', @IDARTICULO_VT) AS ERROR;
				ROLLBACK;
				RETURN;
			END;

			COMMIT;

			UPDATE IZSOLD
			   SET CANTIDADSOL = ISNULL(CANTIDADSOL, 0) + @CANTIDAD_VT
			WHERE CNSIZSOLD = @CNSIZSOLD_VT;

			SELECT @CANTIDADSOL_VT = CANTIDADSOL
			FROM IZSOLD
			WHERE CNSIZSOLD = @CNSIZSOLD_VT;

			EXEC SPK_IZSOLDT_PROCESOS
				@IDARTICULO_VT,
				@CNSIZSOLD_VT,
				'AGREGAR',
				@IDSEDE_VT,
				@IDARTICULO_VT,
				@NOLOTE_VT,
				@CANTIDAD_VT,
				@CANTIDADSOL_VT,  
				@CNSMOV_VT,
				'';

			UPDATE IZSOLD
			   SET CANTIDAD_DISPENSADA = ISNULL(CANTIDAD_DISPENSADA, 0) + @CANTIDAD_VT
			WHERE CNSIZSOLD = @CNSIZSOLD_VT;

			IF @CANTIDADSOL_VT = (SELECT SUM(COALESCE(CANTIDADSOL,0)) FROM IZSOLDT WHERE CNSIZSOLD = @CNSIZSOLD_VT)
			BEGIN
				UPDATE IZSOLD SET ESTADO = 0 WHERE CNSIZSOLD = @CNSIZSOLD_VT;
			END;

			SELECT 'OK' AS OK, @IDARTICULO_VT AS IDARTICULO,
				   @NOLOTE_VT AS NOLOTE, @FECHAVENCE_VT AS FECHAVENCE, @CANTIDAD_VT AS CANTIDAD;
			RETURN;
		END TRY
		BEGIN CATCH
			IF @@TRANCOUNT > 0 ROLLBACK;
			SELECT 'ERROR' AS OK, ERROR_MESSAGE() AS ERROR;
			RETURN;
		END CATCH
	END

	IF @METODO = 'ELIMINAR_IZSOLD'
	BEGIN
		SELECT @CNSIZSOLD = CNSIZSOLD
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSIZSOLD VARCHAR(20) '$.CNSIZSOLD'
		)

		BEGIN TRY 
			-- Verificar que existe el IZSOLD
			IF NOT EXISTS (SELECT 1 FROM IZSOLD WHERE CNSIZSOLD = @CNSIZSOLD)
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) 
				SELECT 'El registro no existe.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END

			-- Obtener datos del IZSOLD
			SELECT 
				@CNSIZSOL = CNSIZSOL,
				@IDARTICULO = IDARTICULO,
				@CANTIDADSOL = CANTIDADSOL
			FROM IZSOLD 
			WHERE CNSIZSOLD = @CNSIZSOLD

			-- Obtener CNSMOV y IDSEDE del IZSOL
			SELECT 
				@CNSMOV = CNSMOV,
				@IDSEDE = IDSEDE
			FROM IZSOL 
			WHERE CNSIZSOL = @CNSIZSOL

			-- Verificar si hay entregas confirmadas (en IMOV con ESTADO = 1)
			IF EXISTS (
				SELECT 1 
				FROM IZSOLDT 
				INNER JOIN IMOV ON IZSOLDT.CNSMOV = IMOV.CNSMOV
				WHERE IZSOLDT.CNSIZSOLD = @CNSIZSOLD 
				AND IMOV.ESTADO = 1
			)
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) 
				SELECT 'No se puede eliminar. Existen entregas ya confirmadas para este art�culo.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END

			-- Si hay entregas pendientes (IZSOLDT), revertirlas
			IF EXISTS (SELECT 1 FROM IZSOLDT WHERE CNSIZSOLD = @CNSIZSOLD)
			BEGIN
				DECLARE CURSOR_IZSOLDT CURSOR FOR
				SELECT 
					CNSIZSOLDT,
					IDARTICULOREAL,
					NOLOTE,
					CANTIDADSOL
				FROM IZSOLDT 
				WHERE CNSIZSOLD = @CNSIZSOLD

				OPEN CURSOR_IZSOLDT

				FETCH NEXT FROM CURSOR_IZSOLDT 
				INTO @CNSIZSOLDT, @IDARTICULO_REAL, @NOLOTE, @CANTIDAD

				WHILE @@FETCH_STATUS = 0
				BEGIN
					PRINT 'Revirtiendo entrega: ' + @CNSIZSOLDT

					-- Revertir el movimiento usando el mismo procedimiento que DEVOLVER
					EXEC SPK_IZSOLDT_PROCESOS 
						@IDARTICULO,           -- IDARTICULO (servicio)
						@CNSIZSOLD,            -- CNSIZSOLD
						'QUITAR',              -- ACCION
						@IDSEDE,               -- IDSEDE
						@IDARTICULO_REAL,      -- IDARTICULO REAL
						@NOLOTE,               -- NOLOTE
						@CANTIDAD,             -- CANTIDAD
						@CANTIDADSOL,          -- CANTIDADSOL
						@CNSMOV,               -- CNSMOV
						@CNSIZSOLDT            -- CNSIZSOLDT

					FETCH NEXT FROM CURSOR_IZSOLDT 
					INTO @CNSIZSOLDT, @IDARTICULO_REAL, @NOLOTE, @CANTIDAD
				END

				CLOSE CURSOR_IZSOLDT
				DEALLOCATE CURSOR_IZSOLDT

				PRINT 'Todas las entregas revertidas'
			END

			-- Ahora eliminar los registros de IZSOLDT
			DELETE FROM IZSOLDT WHERE CNSIZSOLD = @CNSIZSOLD
			PRINT 'IZSOLDT eliminados'

			-- Finalmente eliminar el IZSOLD
			DELETE FROM IZSOLD WHERE CNSIZSOLD = @CNSIZSOLD
			PRINT 'IZSOLD eliminado: ' + @CNSIZSOLD

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 'OK' AS OK
		RETURN
	END

	IF @METODO = 'AGREGA_CODIGO_BARRA'
	BEGIN
		SELECT @IDARTICULO = IDARTICULO, @CODIGO = CODIGO
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		IDARTICULO				VARCHAR(20)			'$.IDARTICULO'
		,CODIGO					VARCHAR(20)			'$.CODIGO'
		)
		IF  EXISTS (SELECT 1 FROM TGEN WHERE  CODIGO =@CODIGO AND TABLA ='IART' AND CAMPO = 'CODEBAR')
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT '�ste codigo de barras ya lo tiene asignado el art�culo.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			INSERT INTO TGEN (TABLA, CAMPO, CODIGO, DATO1)
			SELECT 'IART', 'CODEBAR', @CODIGO, @IDARTICULO
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'BORRA_CODIGO_BARRA'
	BEGIN
		SELECT @IDARTICULO = IDARTICULO, @CODIGO = CODIGO
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		IDARTICULO				VARCHAR(20)			'$.IDARTICULO'
		,CODIGO					VARCHAR(20)			'$.CODIGO'
		)

		BEGIN TRY 
			DELETE FROM TGEN WHERE TABLA ='IART' AND CAMPO = 'CODEBAR' AND CODIGO = @CODIGO
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'PRESCRIPCION_LINEA'
	BEGIN
		DECLARE @PRESCRIPCION_TXT VARCHAR(1000)
			,@IDSERVICIO_LINEA VARCHAR(20)
			,@CODOM_LINEA VARCHAR(10)
			,@PRESCRIPCION_IZSOLD VARCHAR(1000)
			,@NOADMISION_LINEA VARCHAR(20)
			,@CONSECUTIVOHCA_LINEA VARCHAR(20)
			,@FECHASOL_LINEA DATETIME
			,@CLASE_IZSOL_LINEA VARCHAR(50)

		SELECT @CNSIZSOLD = CNSIZSOLD
		FROM OPENJSON(@PARAMETROS)
		WITH (CNSIZSOLD VARCHAR(20) '$.CNSIZSOLD')

		IF COALESCE(@CNSIZSOLD, '') = ''
		BEGIN
			SELECT 'KO' AS OK
			SELECT 'CNSIZSOLD es requerido' AS ERROR
			RETURN
		END

		SELECT
			@NOADMISION_LINEA = IZSOL.NOADMISION
			,@CONSECUTIVOHCA_LINEA = IZSOL.CONSECUTIVOHCA
			,@FECHASOL_LINEA = IZSOL.FECHASOL
			,@CLASE_IZSOL_LINEA = IZSOL.CLASE
			,@IDSERVICIO_LINEA = COALESCE(NULLIF(LTRIM(RTRIM(IZSOLD.IDSERVICIO)), ''), IART.IDSERVICIO)
			,@CODOM_LINEA = NULLIF(LTRIM(RTRIM(IZSOLD.CODOM)), '')
			,@PRESCRIPCION_IZSOLD = IZSOLD.PRESCRIPCION
		FROM IZSOLD WITH (NOLOCK)
		INNER JOIN IZSOL WITH (NOLOCK) ON IZSOL.CNSIZSOL = IZSOLD.CNSIZSOL
		LEFT JOIN IART WITH (NOLOCK) ON IART.IDARTICULO = IZSOLD.IDARTICULO
		WHERE IZSOLD.CNSIZSOLD = @CNSIZSOLD

		IF @@ROWCOUNT = 0
		BEGIN
			SELECT 'KO' AS OK
			SELECT 'No se encontr� el detalle de solicitud' AS ERROR
			RETURN
		END

		SET @PRESCRIPCION_TXT = NULL

		IF @CLASE_IZSOL_LINEA = '24HORAS'
		BEGIN
			SELECT TOP 1 @PRESCRIPCION_TXT = HCATD.PRESCRIPCION
			FROM HCATD WITH (NOLOCK)
			INNER JOIN HCA WITH (NOLOCK) ON HCA.CONSECUTIVO = HCATD.CONSECUTIVO
			WHERE HCA.NOADMISION = @NOADMISION_LINEA
			  AND HCATD.IDSERVICIO = @IDSERVICIO_LINEA
			  AND HCATD.CLASE IN ('I', 'B')
			  AND (
					@CODOM_LINEA IS NULL
				 OR HCATD.CODOM = @CODOM_LINEA
			  )
			  AND (
					@FECHASOL_LINEA IS NULL
				 OR HCA.FECHA <= @FECHASOL_LINEA
			  )
			ORDER BY HCA.FECHA DESC
		END
		ELSE
		BEGIN
			SELECT TOP 1 @PRESCRIPCION_TXT = HCATD.PRESCRIPCION
			FROM HCATD WITH (NOLOCK)
			WHERE HCATD.CONSECUTIVO = @CONSECUTIVOHCA_LINEA
			  AND HCATD.IDSERVICIO = @IDSERVICIO_LINEA
			  AND (
					@CODOM_LINEA IS NULL
				 OR HCATD.CODOM = @CODOM_LINEA
			  )
		END

		SET @PRESCRIPCION_TXT = COALESCE(@PRESCRIPCION_TXT, @PRESCRIPCION_IZSOLD, '')

		IF CHARINDEX('Equivale', @PRESCRIPCION_TXT) > 0
			SET @PRESCRIPCION_TXT = RTRIM(SUBSTRING(
				@PRESCRIPCION_TXT,
				1,
				CHARINDEX('Equivale', @PRESCRIPCION_TXT) - 1
			))

		SELECT 'OK' AS OK, @PRESCRIPCION_TXT AS PRESCRIPCION
		RETURN
	END
	IF @METODO = 'IMPRE_MOVIMIENTO'
  BEGIN
    SELECT @CNSMOV = CNSMOV
    FROM OPENJSON (@PARAMETROS)
    WITH (
      CNSMOV VARCHAR(20) '$.CNSMOV'
    )
    
    BEGIN TRY
      /* FIRMA DEL PACIENTE.
         Las firmas se suben a la base de documentos de USVGS NAME_DOCU_DB, pero
         MODELO DOCS / METODO IMAGEN solo lee la tabla DOCS local, asi que devuelve
         NULL y el PDF sale sin firma. Aqui se lee de la base configurada y, si no
         esta o no hay permiso, se cae a la DOCS local. */
      DECLARE @DOC_FIRMA UNIQUEIDENTIFIER, @DOCU_DB SYSNAME, @FIRMA_BIN VARBINARY(MAX);
      DECLARE @FIRMA_B64 VARCHAR(MAX), @SQL_FIRMA NVARCHAR(MAX);

      /* DOCS.DocumentoID es UNIQUEIDENTIFIER: se compara tal cual para que
         la busqueda sea un seek y no un recorrido de la tabla de documentos. */
      SELECT @DOC_FIRMA = TRY_CONVERT(UNIQUEIDENTIFIER, CONVERT(VARCHAR(50), FIRMA_PACIENTE))
      FROM IMOV WITH (NOLOCK)
      WHERE CNSMOV = @CNSMOV;

      IF @DOC_FIRMA IS NOT NULL
      BEGIN
        SET @DOCU_DB = NULLIF(LTRIM(RTRIM(DBO.FNK_VALORVARIABLE('NAME_DOCU_DB'))), '');

        IF @DOCU_DB IS NOT NULL AND DB_ID(@DOCU_DB) IS NOT NULL AND HAS_DBACCESS(@DOCU_DB) = 1
        BEGIN
          BEGIN TRY
            SET @SQL_FIRMA = N'SELECT TOP 1 @BIN = D.DocFS'
              + N' FROM ' + QUOTENAME(@DOCU_DB) + N'.dbo.DOCS D WITH (NOLOCK)'
              + N' WHERE D.DocumentoID = @DOC';
            EXEC sp_executesql @SQL_FIRMA,
              N'@DOC UNIQUEIDENTIFIER, @BIN VARBINARY(MAX) OUTPUT',
              @DOC = @DOC_FIRMA, @BIN = @FIRMA_BIN OUTPUT;
          END TRY
          BEGIN CATCH
            SET @FIRMA_BIN = NULL;
          END CATCH
        END

        IF @FIRMA_BIN IS NULL
          SELECT TOP 1 @FIRMA_BIN = DocFS
          FROM DOCS WITH (NOLOCK)
          WHERE DocumentoID = @DOC_FIRMA;

        IF DATALENGTH(@FIRMA_BIN) > 0
          SET @FIRMA_B64 = CAST(N'' AS XML).value(
            'xs:base64Binary(sql:variable("@FIRMA_BIN"))', 'VARCHAR(MAX)');
      END

      /* HUELLA DEL PACIENTE, solo formulas ambulatorias de consulta externa.
         Se resuelve el afiliado aparte para que la busqueda en HUELLA sea un seek
         por TABLA + CONSECUTIVO (su PK) y no un recorrido de toda la tabla, que
         guarda las plantillas biometricas y es pesada. */
      DECLARE @HU_CLASE VARCHAR(50), @HU_NOADM VARCHAR(20);
      DECLARE @HU_AFI VARCHAR(20), @HU_DOC VARCHAR(20), @HUELLA_B64 NVARCHAR(MAX);

      SELECT @HU_CLASE = IZSOL.CLASE, @HU_NOADM = IZSOL.NOADMISION
      FROM IMOV WITH (NOLOCK)
      INNER JOIN IZSOL WITH (NOLOCK) ON IMOV.NODOCUMENTO = IZSOL.CNSIZSOL
      WHERE IMOV.CNSMOV = @CNSMOV;

      IF @HU_CLASE = 'FORMEDCE'
      BEGIN
        /* En FORMEDCE, IZSOL.NOADMISION guarda el IDAFILIADO, no una admision. */
        SELECT @HU_AFI = IDAFILIADO, @HU_DOC = DOCIDAFILIADO
        FROM AFI WITH (NOLOCK)
        WHERE IDAFILIADO = @HU_NOADM;

        IF @HU_AFI IS NULL
          SELECT TOP 1 @HU_AFI = IDAFILIADO, @HU_DOC = DOCIDAFILIADO
          FROM AFI WITH (NOLOCK)
          WHERE DOCIDAFILIADO = @HU_NOADM;

        SELECT TOP 1 @HUELLA_B64 = H.TEMPLATE_BASE64
        FROM HUELLA H WITH (NOLOCK)
        WHERE H.TABLA = 'AFI'
          AND H.ACTIVA = 1
          AND H.CONSECUTIVO IN (@HU_AFI, @HU_DOC, @HU_NOADM)
          AND DATALENGTH(H.TEMPLATE_BASE64) > 0
        ORDER BY
          CASE WHEN H.CONSECUTIVO = @HU_AFI THEN 0 ELSE 1 END,
          H.FECHA_CAPTURA DESC;
      END

      /* CABECERA */
      SELECT 'OK'OK,CASE WHEN DBO.FNK_VALORVARIABLE('IZSOL_MED_SOLI') = 'SI' THEN MED.IDMEDICO ELSE IZSOL.USUARIOSOL END [USUARIOSOL]
      , CASE WHEN DBO.FNK_VALORVARIABLE('IZSOL_MED_SOLI') = 'SI' THEN MED.NOMBRE ELSE� USUSU.NOMBRE END [NOMBRE], IZSOL.CNSIZSOL, IMOV.CNSMOV, IMOV.FECHAMOV, IMOV.CCOSTO, IMOV.IDAREA, IMOV.IDBODEGA, IBOD.DESCRIPCION [IDBODEGA_DESC], IMOV.IDTIPOMOV, ITMO.DESCRIPCION [IDTIPOMOV_DESC]
      , CASE WHEN IZSOL.CLASE IN ('FORMEDCE','HPRE','TRANS_CE') THEN IZSOL.NOADMISION ELSE COALESCE(AUT.IDAUT, HADM.NOADMISION) END NOADMISION
      , IMOV.IDFUNCIONARIO, USU_FUN.NOMBRE AS NOMBRE_FUNCIONARIO
      , AFI.DOCIDAFILIADO, AFI.NOMBREAFI, AFI.TELEFONORES
      , CASE
          WHEN IZSOL.CLASE = 'CE' THEN COALESCE(AE.PERIODO, AUT.PERIODO_DISPENSA)
          WHEN IZSOL.CLASE = 'TRANS_CE' THEN COALESCE(AE_TR.PERIODO, AUT_MOV.PERIODO_DISPENSA)
        END PERIODO
      , COALESCE(HCA.FECHA, CASE
          WHEN IZSOL.CLASE = 'CE' THEN AUT.FECHA_FORMULA
          WHEN IZSOL.CLASE = 'TRANS_CE' THEN COALESCE(
            (SELECT TOP 1 C.FECHA_FORMULA
             FROM AUTE E WITH (NOLOCK)
             INNER JOIN CEFM C WITH (NOLOCK) ON C.CNSCEFM = E.CNSCEFM
             WHERE E.CNSIZSOL = IZSOL.CNSIZSOL
               AND COALESCE(C.ESTADO, '') <> 'ANULADO'
             ORDER BY E.FECHA),
            AUT_MOV.FECHA_FORMULA)
        END) FECHA_FORMULA
      , AFI.TIPO_DOC, AFI.IDAFILIADO, AFI.DIRECCION
      , CASE IZSOL.CLASE
        WHEN 'APLIM' THEN APTER.IDTERCERO
        WHEN 'CE' THEN AU.IDTERCERO
        WHEN 'TRANS_CE' THEN COALESCE(TER.IDTERCERO, AU.IDTERCERO)
        WHEN 'ONCO' THEN CI.IDTERCERO
        WHEN 'FORMEDCE' THEN TER.IDTERCERO
        WHEN 'HPRE' THEN TER.IDTERCERO
        ELSE COALESCE(HADM.IDTERCERO, TER.IDTERCERO)
      � END IDTERCERO
      , CASE IZSOL.CLASE
        WHEN 'APLIM' THEN APTER.RAZONSOCIAL
        WHEN 'CE' THEN AU.RAZONSOCIAL
        WHEN 'TRANS_CE' THEN COALESCE(TER.RAZONSOCIAL, AU.RAZONSOCIAL)
        WHEN 'ONCO' THEN CI.RAZONSOCIAL
        WHEN 'FORMEDCE' THEN TER.RAZONSOCIAL
        WHEN 'HPRE' THEN TER.RAZONSOCIAL
        ELSE TER.RAZONSOCIAL
      � END RAZONSOCIAL
      , CASE IZSOL.CLASE
        WHEN 'APLIM' THEN APLI.IDPLAN
        WHEN 'CE' THEN AUT.IDPLAN
        WHEN 'TRANS_CE' THEN COALESCE(NULLIF(IZSOL.IDPLAN, ''), AUT_MOV.IDPLAN)
        WHEN 'ONCO' THEN CIT.IDPLAN
        WHEN 'FORMEDCE' THEN IZSOL.IDPLAN
        WHEN 'HPRE' THEN IZSOL.IDPLAN
        ELSE HADM.IDPLAN
      � END IDPLAN
      , CASE IZSOL.CLASE
        WHEN 'APLIM' THEN PAPLI.DESCPLAN
        WHEN 'CE' THEN PAUT.DESCPLAN
        WHEN 'TRANS_CE' THEN COALESCE(PLN.DESCPLAN, PAUT_MOV.DESCPLAN)
        WHEN 'ONCO' THEN PCIT.DESCPLAN
        WHEN 'FORMEDCE' THEN PLN.DESCPLAN
        WHEN 'HPRE' THEN PLN.DESCPLAN
        ELSE PLN.DESCPLAN
      � END DESCPLAN
      , IMOV.IDITAR, ITAR.DESCRIPCION [IDITAR_DESC], CEN.DESCRIPCION [CCOSTO_DESC], AFU.DESCRIPCION [IDAREA_DESC]
      , IMOV.ESTADO, CASE WHEN IMOV.ESTADO = 0 THEN 'NO CONFIRMADO' WHEN IMOV.ESTADO = 1 THEN 'CONFIRMADO' END [ESTADO_DESC]
      , IMOV.FIRMA_PACIENTE
      , @FIRMA_B64 AS FIRMA_PACIENTE_IMAGEN
      , IMOV.USUFIRMARECIBIDO
      , IZSOL.CLASE
      , @HUELLA_B64 AS HUELLA_IMAGEN
      , CASE IZSOL.CLASE WHEN 'QXPGCX' THEN
          CASE WHEN LEN(IZSOL.CNSIZSOLM)<10 THEN� (SELECT IDAFILIADO FROM CXPS WHERE CXPS.NOPROGRAMACION = IZSOL.NOADMISION )
              ELSE (SELECT H.IDAFILIADO FROM QXPCX INNER JOIN HADM H ON QXPCX.NOADMISION = H.NOADMISION WHERE QXPCX.CONSECUTIVO = IZSOL.CNSIZSOLM)
              END
        WHEN 'FORMEDCE' THEN IZSOL.NOADMISION
        WHEN 'HPRE' THEN IZSOL.NOADMISION
        ELSE (SELECT IDAFILIADO FROM HADM WHERE HADM.NOADMISION = IZSOL.NOADMISION) END
      , COALESCE(HHAB_IZSOL.CAMA, '') [CAMA]
      , COALESCE(HHAB_IZSOL.DESCRIPCION, '') [CAMA_DESC]
      FROM IMOV
      INNER JOIN IZSOL ON IMOV.NODOCUMENTO = IZSOL.CNSIZSOL
      LEFT JOIN HCA ON IZSOL.CONSECUTIVOHCA = HCA.CONSECUTIVO
      LEFT JOIN MED ON HCA.IDMEDICO = MED.IDMEDICO
      LEFT JOIN USUSU ON IZSOL.USUARIOSOL = USUSU.USUARIO
      LEFT JOIN USUSU USU_FUN ON IMOV.IDFUNCIONARIO = USU_FUN.USUARIO
      LEFT JOIN ITMO ON IMOV.IDTIPOMOV = ITMO.IDTIPOMOV
      LEFT JOIN IBOD ON IMOV.IDBODEGA = IBOD.IDBODEGA
      LEFT JOIN HADM ON IZSOL.NOADMISION = HADM.NOADMISION AND IZSOL.CLASE NOT IN ('FORMEDCE','HPRE','CE','TRANS_CE')
      LEFT JOIN QXPCX ON QXPCX.CONSECUTIVO = IZSOL.CNSIZSOLM� AND IZSOL.CLASE = 'QXPGCX'
      LEFT JOIN HADM H ON QXPCX.NOADMISION = H.NOADMISION�� AND IZSOL.CLASE = 'QXPGCX'
      LEFT JOIN CXPS ON� CXPS.NOPROGRAMACION� = CASE WHEN IZSOL.CLASE = 'QXPGCX'� AND�� LEN(IZSOL.NOADMISION)<10 THEN IZSOL.NOADMISION ELSE� '9999'� END
      LEFT JOIN CIT ON IZSOL.NOADMISION = CIT.CONSECUTIVO AND IZSOL.CLASE='ONCO'
      /* CE: NOADMISION es AUT.IDAUT. TRANS_CE: NOADMISION es IDAFILIADO y puede
         coincidir con la AUT de otra persona. */
      LEFT JOIN AUT ON IZSOL.CLASE = 'CE' AND IZSOL.NOADMISION = AUT.IDAUT
      LEFT JOIN AUT AUT_MOV ON IZSOL.CLASE = 'TRANS_CE'
        AND AUT_MOV.CNSIMOV = IMOV.CNSMOV
        AND COALESCE(AUT_MOV.MANUALCE, 0) = 1
      LEFT JOIN APLIM ON IZSOL.NOADMISION = CAST(APLIM.ID AS VARCHAR) AND IZSOL.CLASE = 'APLIM'
      LEFT JOIN APLI ON APLIM.IDAPLI = APLI.ID AND IZSOL.CLASE = 'APLIM'
      LEFT JOIN AFI ON AFI.IDAFILIADO = CASE� WHEN IZSOL.CLASE = 'QXPGCX' AND LEN(IZSOL.CNSIZSOLM)<10 THEN� CXPS.IDAFILIADO
                    WHEN IZSOL.CLASE = 'QXPGCX' AND LEN(IZSOL.CNSIZSOLM)>=10 THEN� H.IDAFILIADO
                    WHEN IZSOL.CLASE = 'APLIM' THEN APLI.IDAFILIADO
                    WHEN IZSOL.CLASE = 'CE' THEN COALESCE(AUT.IDAFILIADO, IZSOL.NOADMISION)
                    WHEN IZSOL.CLASE = 'TRANS_CE' THEN COALESCE(
                      (SELECT TOP 1 C.IDAFILIADO
                       FROM AUTE E WITH (NOLOCK)
                       INNER JOIN CEFM C WITH (NOLOCK) ON C.CNSCEFM = E.CNSCEFM
                       WHERE E.CNSIZSOL = IZSOL.CNSIZSOL
                         AND COALESCE(C.ESTADO, '') <> 'ANULADO'
                         AND COALESCE(C.IDAFILIADO, '') <> ''
                       ORDER BY E.FECHA),
                      IZSOL.NOADMISION)
                    WHEN IZSOL.CLASE = 'ONCO'� THEN� CIT.IDAFILIADO
                    WHEN IZSOL.CLASE = 'FORMEDCE' THEN IZSOL.NOADMISION
                    WHEN IZSOL.CLASE = 'HPRE' THEN IZSOL.NOADMISION
                    ELSE HADM.IDAFILIADO END
      LEFT JOIN PLN ON PLN.IDPLAN = CASE
        WHEN IZSOL.CLASE = 'APLIM' THEN APLI.IDPLAN
        WHEN IZSOL.CLASE = 'CE' THEN COALESCE(AUT.IDPLAN, IZSOL.IDPLAN)
        WHEN IZSOL.CLASE = 'TRANS_CE' THEN COALESCE(NULLIF(IZSOL.IDPLAN, ''), AUT_MOV.IDPLAN)
        WHEN IZSOL.CLASE = 'ONCO' THEN CIT.IDPLAN
        WHEN IZSOL.CLASE IN ('FORMEDCE','HPRE') THEN IZSOL.IDPLAN
        ELSE HADM.IDPLAN
      END
      LEFT JOIN AUTE AE ON IZSOL.CLASE = 'CE' AND AE.IDAUT = AUT.IDAUT
      LEFT JOIN AUTE AE_TR ON IZSOL.CLASE = 'TRANS_CE' AND AE_TR.CNSIZSOL = IZSOL.CNSIZSOL
      LEFT JOIN PLN PAPLI ON PAPLI.IDPLAN = APLI.IDPLAN AND IZSOL.CLASE = 'APLIM'
      LEFT JOIN TER ON TER.IDTERCERO = CASE
        WHEN IZSOL.CLASE = 'APLIM' THEN APLI.IDTERCERO
        WHEN IZSOL.CLASE = 'CE' THEN COALESCE(AUT.IDCONTRATANTE, IZSOL.IDTERCEROC)
        WHEN IZSOL.CLASE = 'TRANS_CE' THEN COALESCE(NULLIF(IZSOL.IDTERCEROC, ''), AUT_MOV.IDCONTRATANTE)
        WHEN IZSOL.CLASE = 'ONCO' THEN CIT.IDCONTRATANTE
        WHEN IZSOL.CLASE IN ('FORMEDCE','HPRE') THEN IZSOL.IDTERCEROC
        ELSE HADM.IDTERCERO
      END
      LEFT JOIN TER CI ON CI.IDTERCERO = CIT.IDTERCEROCA AND IZSOL.CLASE = 'ONCO'
      LEFT JOIN TER AU ON AU.IDTERCERO = AUT.IDCONTRATANTE AND IZSOL.CLASE = 'CE'
      LEFT JOIN TER APTER ON APTER.IDTERCERO = APLI.IDTERCERO AND IZSOL.CLASE = 'APLIM'
      LEFT JOIN PLN PAUT ON PAUT.IDPLAN = AUT.IDPLAN AND IZSOL.CLASE = 'CE'
      LEFT JOIN PLN PAUT_MOV ON PAUT_MOV.IDPLAN = AUT_MOV.IDPLAN AND IZSOL.CLASE = 'TRANS_CE'
      LEFT JOIN PLN PCIT ON PCIT.IDPLAN = CIT.IDPLAN AND IZSOL.CLASE = 'ONCO'
      LEFT JOIN ITAR ON IMOV.IDITAR = ITAR.IDITAR
      LEFT JOIN CEN ON IMOV.CCOSTO = CEN.CCOSTO
      LEFT JOIN AFU ON IMOV.IDAREA = AFU.IDAREA
      LEFT JOIN HHAB HHAB_IZSOL ON HADM.HABCAMA = HHAB_IZSOL.HABCAMA
      WHERE IMOV.CNSMOV = @CNSMOV

      /* IMOVH - SOLO DISPENSADOS: 1 fila por IMOVH (art�culo+lote) con CANTPEDIDA real.
         DetSol (RN=1) toma una sola IZSOLDT/IZSOLD por art�culo+lote; evita multiplicar
         CANTPEDIDA cuando hay N l�neas IZSOLD del mismo lote (alineado con SPQ_IMOV_PDF). */
      SELECT IMOVH.CNSMOV, IMOVH.IDARTICULO, IART.DESCRIPCION, COALESCE(IART.IDUNIDAD,'')IDUNIDAD, COALESCE(IMOVH.CANTPEDIDA,0) CANTPEDIDA
      , COALESCE(IMOVH.PCOSTOANTES,0) PCOSTOANTES, IMOVH.PCOSTOANTES*IMOVH.CANTPEDIDA [PCOSTO], IMOVH.PVENTA
      , IMOVH.NOLOTE, IMOVH.NOLOTEPEDIDO, IMOVH.FECHAVENCE
      , COALESCE(IEXI.SELLOCALIDAD, IMOVH.SELLOCALIDAD, '') SELLOCALIDAD
      , COALESCE(VIA_TGEN.DESCRIPCION, DetSol.VIA_APLICACION, '') VIA_APLICACION
      , COALESCE(IFFA.DESCRIPCION, '') FORMA_FARMACEUTICA
      , COALESCE(DetSol.FRECUENCIA, 0) FRECUENCIA
      , COALESCE(DetSol.DURACION, 0) DURACION
      /* �ltima HCATD I/B que afect� la dosis; strip desde 'Equivale' (sin recalcular) */
      , PRESCRIPCION = IIF(
          CHARINDEX('Equivale', COALESCE(UltOmDosis.PRESCRIPCION, DetSol.PRESCRIPCION, '')) > 0,
          RTRIM(SUBSTRING(
            COALESCE(UltOmDosis.PRESCRIPCION, DetSol.PRESCRIPCION, ''),
            1,
            CHARINDEX('Equivale', COALESCE(UltOmDosis.PRESCRIPCION, DetSol.PRESCRIPCION, '')) - 1
          )),
          COALESCE(UltOmDosis.PRESCRIPCION, DetSol.PRESCRIPCION, '')
        )
      FROM IMOVH
      INNER JOIN IART ON IMOVH.IDARTICULO = IART.IDARTICULO
      INNER JOIN IMOV ON IMOV.CNSMOV = IMOVH.CNSMOV
      INNER JOIN (
        SELECT
          IZSOLDT.CNSMOV,
          IZSOLDT.IDARTICULOREAL,
          IZSOLDT.NOLOTE,
          IZSOLD.VIA_APLICACION,
          IZSOLD.PRESCRIPCION,
          IZSOLD.IDSERVICIO,
          IZSOLD.CODOM,
          IZSOLD.FRECUENCIA,
          IZSOLD.DURACION,
          IZSOL.NOADMISION,
          IZSOL.FECHASOL,
          ROW_NUMBER() OVER (
            PARTITION BY IZSOLDT.CNSMOV, IZSOLDT.IDARTICULOREAL, IZSOLDT.NOLOTE
            ORDER BY IZSOLDT.CNSIZSOLDT DESC
          ) AS RN
        FROM IZSOLDT
          INNER JOIN IZSOLD ON IZSOLD.CNSIZSOLD = IZSOLDT.CNSIZSOLD
          LEFT JOIN IZSOL ON IZSOL.CNSIZSOL = IZSOLD.CNSIZSOL
        WHERE IZSOLDT.CNSMOV = @CNSMOV
      ) DetSol ON DetSol.CNSMOV = IMOVH.CNSMOV
        AND DetSol.IDARTICULOREAL = IMOVH.IDARTICULO
        AND DetSol.NOLOTE = IMOVH.NOLOTE
        AND DetSol.RN = 1
      LEFT JOIN IEXI ON IEXI.IDBODEGA = IMOV.IDBODEGA
        AND IEXI.IDARTICULO = IMOVH.IDARTICULO
        AND IEXI.NOLOTE = IMOVH.NOLOTE
      LEFT JOIN IFFA WITH (NOLOCK) ON IFFA.IDFORFARM = IART.IDFORFARM
      LEFT JOIN TGEN VIA_TGEN WITH (NOLOCK) ON VIA_TGEN.TABLA = 'General'
        AND VIA_TGEN.CAMPO = 'VIAAPLICACION'
        AND LTRIM(RTRIM(VIA_TGEN.CODIGO)) = LTRIM(RTRIM(DetSol.VIA_APLICACION))
      OUTER APPLY (
        SELECT TOP 1 HCATD.PRESCRIPCION
        FROM HCATD WITH (NOLOCK)
        INNER JOIN HCA WITH (NOLOCK) ON HCA.CONSECUTIVO = HCATD.CONSECUTIVO
        WHERE HCA.NOADMISION = DetSol.NOADMISION
          AND HCATD.IDSERVICIO = COALESCE(DetSol.IDSERVICIO, IART.IDSERVICIO)
          AND HCATD.CLASE IN ('I', 'B')
          AND (
            DetSol.CODOM IS NULL
            OR LTRIM(RTRIM(DetSol.CODOM)) = ''
            OR HCATD.CODOM = DetSol.CODOM
          )
          AND (
            DetSol.FECHASOL IS NULL
            OR HCA.FECHA <= DetSol.FECHASOL
          )
        ORDER BY HCA.FECHA DESC
      ) UltOmDosis
      WHERE IMOVH.CNSMOV = @CNSMOV
      AND COALESCE(IMOVH.CANTPEDIDA, 0) > 0



      /* TOTALES (solo sobre l�neas dispensadas con lote/fecha) */
      SELECT SUM(IMOVH.CANTPEDIDA) TOTAL_CANTPEDIDA, SUM(IMOVH.PCOSTOANTES) TOTAL_PCOSTOANTES, SUM(IMOVH.PCOSTOANTES*IMOVH.CANTPEDIDA) TOTAL_PCOSTO
      FROM IMOVH
      WHERE IMOVH.CNSMOV = @CNSMOV
      AND COALESCE(IMOVH.CANTPEDIDA, 0) > 0
      AND (
        (IMOVH.NOLOTE IS NOT NULL AND LTRIM(RTRIM(IMOVH.NOLOTE)) <> '')
        OR (IMOVH.NOLOTEPEDIDO IS NOT NULL AND LTRIM(RTRIM(IMOVH.NOLOTEPEDIDO)) <> '')
        OR (IMOVH.FECHAVENCE IS NOT NULL)
      )

      /* IMOVH - NO DISPENSADOS (FALTANTES) */
      SELECT IMOVH.CNSMOV, IMOVH.IDARTICULO, IART.DESCRIPCION, COALESCE(IART.IDUNIDAD,'')IDUNIDAD, COALESCE(IMOVH.CANTPEDIDA,0) CANTPEDIDA
      , COALESCE(IMOVH.PCOSTOANTES,0) PCOSTOANTES,IMOVH.PCOSTOANTES*IMOVH.CANTPEDIDA [PCOSTO]� ,IMOVH.PVENTA
      ,IMOVH.NOLOTE, IMOVH.NOLOTEPEDIDO, IMOVH.FECHAVENCE
      , COALESCE(IEXI.SELLOCALIDAD, IMOVH.SELLOCALIDAD, '') SELLOCALIDAD
      FROM IMOVH
      INNER JOIN IART ON IMOVH.IDARTICULO = IART.IDARTICULO
      INNER JOIN IMOV ON IMOV.CNSMOV = IMOVH.CNSMOV
      LEFT JOIN IEXI ON IEXI.IDBODEGA = IMOV.IDBODEGA
        AND IEXI.IDARTICULO = IMOVH.IDARTICULO
        AND IEXI.NOLOTE = IMOVH.NOLOTE
      WHERE IMOVH.CNSMOV = @CNSMOV
      AND COALESCE(IMOVH.CANTPEDIDA, 0) = 0� -- SOLO LOS QUE NO SE DISPENSARON

    END TRY
    BEGIN CATCH
      INSERT INTO @TBLERRORES(ERROR)
      SELECT ERROR_MESSAGE()
    END CATCH

    IF EXISTS(SELECT 1 FROM @TBLERRORES)
    BEGIN
      SELECT 'KO' AS OK
      SELECT ERROR FROM @TBLERRORES
      RETURN
    END
    SELECT 'OK' AS OK
    RETURN
  END
	IF @METODO = 'VALIDA_CODIGO'
	BEGIN
		SELECT @CODIGO = CODIGO, @CNSMOV = CNSMOV,  @IDARTICULO = IDARTICULO, @IDBODEGA = IDBODEGA, @CNSIZSOL = CNSIZSOL
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
			CODIGO					VARCHAR(20)			'$.CODIGO'
			,CNSMOV					VARCHAR(20)			'$.CNSMOV'
			,IDARTICULO				VARCHAR(20)			'$.IDARTICULO'
			,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
			,CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		)
		BEGIN TRY 

			SELECT 
				@ERROR = A.ERROR
				,@IDARTICULO = LTRIM(RTRIM(A.IDARTICULO))
				,@IART_DESCRIPCION = LTRIM(RTRIM(IART.DESCRIPCION))
				,@NOLOTE = LTRIM(RTRIM(A.NOLOTE))
				,@FVENCE = A.FECHAVENCE 
				,@IDARTICULO_REAL = LTRIM(RTRIM(A.IDARTICULO_IMOVH))
			FROM FNK_VLIDABARCODE_IZSOL (@CODIGO, @CNSMOV) A
			 LEFT JOIN IART ON IART.IDARTICULO = A.IDARTICULO

			 PRINT '@ERROR:				' + CAST(@ERROR AS VARCHAR)
			 PRINT '@IDARTICULO:		' + COALESCE(@IDARTICULO, '')
			 PRINT '@IART_DESCRIPCION:	' + COALESCE(@IART_DESCRIPCION, '')
			 PRINT '@NOLOTE:			' + COALESCE(@NOLOTE, '')
			 PRINT '@FVENCE:			' + CONVERT(VARCHAR,@FVENCE)
			 PRINT '@IDARTICULO_REAL:	' + COALESCE(@IDARTICULO_REAL, '')

			 IF @ERROR = 0
			 BEGIN
				  SELECT @RAZONSOCIAL = LTRIM(RTRIM(TER.RAZONSOCIAL))
					,@CODCUM = LTRIM(RTRIM(IART.CODCUM))
					,@REGINVIMA = LTRIM(RTRIM(IART.REGINVIMA))
					,@IDUNIDAD  = LTRIM(RTRIM(IDUNIDAD))
					,@IDSERVICIO = LTRIM(RTRIM(IART.IDSERVICIO))
				  FROM IART LEFT JOIN TER ON TER.IDTERCERO = IART.IDFABRICANTE 
				  WHERE IDARTICULO = @IDARTICULO

				  SELECT @CANTIDADSOL = CANTIDADSOL
					, @CANTIDAD_ENTREGA = (SELECT COALESCE(SUM(CANTIDADSOL),0) FROM IZSOLDT WHERE IZSOLDT.CNSIZSOLD = IZSOLD.CNSIZSOLD)
                    , @CANTIDAD_PENDIENTE = IZSOLD.CANTIDADSOL - (SELECT COALESCE(SUM(CANTIDADSOL),0) FROM IZSOLDT WHERE IZSOLDT.CNSIZSOLD = IZSOLD.CNSIZSOLD)
					, @CNSIZSOLD = IZSOLD.CNSIZSOLD
				  FROM IZSOLD WHERE IZSOLD.CNSIZSOL = @CNSIZSOL AND IZSOLD.IDARTICULO = @IDARTICULO_REAL

				  -- VALIDA_CODIGO solo identifica el lote y calcula disponibilidad.
				  -- La validaci�n PROA por art�culo se ejecuta al intentar dispensar:
				  -- ENTREGAR (bot�n/cantidad manual) o VALIDA_TOTAL (c�digo de barras).

				  SELECT OK = 'OK'
					,@ERROR AS CODMENSAJE
					,@IDARTICULO AS IDARTICULO
					,@IART_DESCRIPCION AS DESCRIPCION
					,@NOLOTE AS NOLOTE
					,@FVENCE AS FECHAVENCE 
					,@IDARTICULO_REAL AS IDARTICULO_IMOVH 
					,@RAZONSOCIAL AS RAZONSOCIAL
					,@CODCUM AS CODCUM
					,@REGINVIMA AS REGINVIMA
					,@IDUNIDAD  AS IDUNIDAD 
					,SUM(IEXI.EXISLOTE) EXISLOTE
					,@CANTIDADSOL AS CANTIDADSOL
					,@CANTIDAD_ENTREGA AS CANTIDAD_ENTREGA
					,@CANTIDAD_PENDIENTE AS CANTIDAD_PENDIENTE
					,CASE WHEN @CANTIDAD_PENDIENTE<= SUM(IEXI.EXISLOTE) THEN  @CANTIDAD_PENDIENTE
						WHEN @CANTIDAD_PENDIENTE > SUM(IEXI.EXISLOTE) THEN @CANTIDAD_PENDIENTE-SUM(IEXI.EXISLOTE) END
						 AS CANTIDAD_VALIDA
				FROM IEXI, IZSOLD 
				WHERE IEXI.NOLOTE = @NOLOTE AND IEXI.IDARTICULO = @IDARTICULO AND IZSOLD.CNSIZSOL = @CNSIZSOL AND IZSOLD.IDARTICULO = @IDARTICULO_REAL


				SELECT TOP 1  IEXI.IDARTICULO,IEXI.NOLOTE
					,IEXI.FECHAVENCE
					,FECHAVENCE_DESCRITA=CONCAT(DATENAME(dw, IEXI.FECHAVENCE),' ',DATEPART(DAY,IEXI.FECHAVENCE),' de ', DATENAME(m,IEXI.FECHAVENCE), ' de ', YEAR(IEXI.FECHAVENCE))
					,TER.RAZONSOCIAL,IART.CODCUM
					,IART.REGINVIMA,IART.IDUNIDAD
					,CONVERT(INT,IEXI.EXISLOTE) AS EXISLOTE
					,IART.DESCRIPCION
					,NOLOTEPEDIDO = LTRIM(RTRIM(IEXI.NOLOTEPEDIDO))
				 FROM IEXI 
				 INNER JOIN IART ON IART.IDARTICULO = IEXI.IDARTICULO
				 INNER JOIN SER  ON SER.IDSERVICIO = IART.IDSERVICIO
				 LEFT JOIN TER  ON  TER.IDTERCERO = IART.IDFABRICANTE
				 WHERE IDBODEGA = @IDBODEGA
				 AND EXISLOTE > 0 
				 AND IEXI.NOLOTE <> @NOLOTE
				 AND IART.IDSERVICIO = @IDSERVICIO
				 AND CONVERT(DATE,FECHAVENCE) < CONVERT(DATE, @FVENCE)
				 AND CONVERT(DATE,FECHAVENCE) >= CONVERT(DATE,GETDATE())
				 ORDER BY FECHAVENCE

				RETURN
			 END
				
			SELECT 'OK' AS OK, @ERROR AS CODMENSAJE
		 
			 IF @ERROR = 1 -- ERROR EN FORMATO DE CODIGO DE BARRAS
				PRINT '1'
			 IF @ERROR = 2 -- NO HAY EXISTENCIA SUFICIENTE
				PRINT '2'
			 IF @ERROR = 3 -- ESTE ARTICULO NO FUE SOLICITADO
				PRINT '3'
			 IF @ERROR = 4 -- EL ARTICULO YA FUE SELECCIONADO PREVIAMENTE
				PRINT '4'
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		RETURN
	END	
	IF @METODO = 'VALIDA_TOTAL'
	BEGIN
		SELECT @CODIGO = CODIGO, @CNSMOV = CNSMOV,   @IDBODEGA = IDBODEGA, @CANTIDAD = CANTIDAD, @CNSIZSOL = CNSIZSOL
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CODIGO					VARCHAR(20)			'$.CODIGO'
		,CNSMOV					VARCHAR(20)			'$.CNSMOV'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		,CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,CANTIDAD				INT					'$.CANTIDAD'
		)

		SELECT 
				@ERROR = A.ERROR
				,@IDARTICULO = LTRIM(RTRIM(A.IDARTICULO))
				,@IART_DESCRIPCION = LTRIM(RTRIM(IART.DESCRIPCION))
				,@NOLOTE = LTRIM(RTRIM(A.NOLOTE))
				,@FVENCE = A.FECHAVENCE 
				,@IDARTICULO_REAL = LTRIM(RTRIM(A.IDARTICULO_IMOVH))
			FROM FNK_VLIDABARCODE_IZSOL (@CODIGO, @CNSMOV) A
			 LEFT JOIN IART ON IART.IDARTICULO = A.IDARTICULO

			 PRINT '@ERROR:				' + CAST(@ERROR AS VARCHAR)
			 PRINT '@IDARTICULO:		' + COALESCE(@IDARTICULO, '')
			 PRINT '@IART_DESCRIPCION:	' + COALESCE(@IART_DESCRIPCION, '')
			 PRINT '@NOLOTE:			' + COALESCE(@NOLOTE, '')
			 PRINT '@FVENCE:			' + CONVERT(VARCHAR,@FVENCE)
			 PRINT '@IDARTICULO_REAL:	' + COALESCE(@IDARTICULO_REAL, '')

			 SELECT @CANTIDADSOL = CANTIDADSOL, @IDSEDE  = IZSOL.IDSEDE, @CNSIZSOLD = IZSOLD.CNSIZSOLD
			, @CANTIDAD_ENTREGA = (SELECT COALESCE(SUM(CANTIDADSOL),0) FROM IZSOLDT WHERE IZSOLDT.CNSIZSOLD = IZSOLD.CNSIZSOLD)
            , @CANTIDAD_PENDIENTE = IZSOLD.CANTIDADSOL - (SELECT COALESCE(SUM(CANTIDADSOL),0) FROM IZSOLDT WHERE IZSOLDT.CNSIZSOLD = IZSOLD.CNSIZSOLD)
			FROM IZSOLD 
			INNER JOIN IZSOL ON IZSOL.CNSIZSOL = IZSOLD.CNSIZSOL
			WHERE IZSOLD.CNSIZSOL = @CNSIZSOL AND IZSOLD.IDARTICULO = @IDARTICULO_REAL

		/* TRANS_CE: SKU Activo + ESP vigente (plan mapeado + tercero). No-op en otras clases.
		   EXEC no admite expresiones (COALESCE) como argumento posicional. */
		SET @ERR_TRANSCE = NULL
		SET @SKU_TRANSCE = COALESCE(NULLIF(@IDARTICULO_REAL, ''), @IDARTICULO)
		IF OBJECT_ID('DBO.SPQ_CEFM_VALIDA_DISP_TRANSCE', 'P') IS NOT NULL
			EXEC DBO.SPQ_CEFM_VALIDA_DISP_TRANSCE @CNSIZSOL, @SKU_TRANSCE, @ERR_TRANSCE OUTPUT
		ELSE IF EXISTS (
			SELECT 1 FROM IZSOL WITH (NOLOCK)
			WHERE CNSIZSOL = @CNSIZSOL AND CLASE = 'TRANS_CE'
		)
			SET @ERR_TRANSCE = 'Falta SPQ_CEFM_VALIDA_DISP_TRANSCE. No se puede dispensar TRANS_CE.'
		IF COALESCE(@ERR_TRANSCE, '') <> ''
			INSERT INTO @TBLERRORES(ERROR) SELECT @ERR_TRANSCE

		-- PROA por art�culo: solo IART.MAUTORIZACION=1 exige autorizaci�n PROA.
		SET @IDARTICULO_PROA = COALESCE(@IDARTICULO_REAL, @IDARTICULO)
		SET @MAUTORIZACION_ART = 0
		SELECT @MAUTORIZACION_ART = CAST(COALESCE(A.MAUTORIZACION, 0) AS BIT)
		FROM IZSOLD D WITH(NOLOCK)
		INNER JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
		WHERE D.CNSIZSOL = @CNSIZSOL AND D.IDARTICULO = @IDARTICULO_REAL
		IF COALESCE(@MAUTORIZACION_ART, 0) = 0 AND COALESCE(@CNSIZSOLD, '') <> ''
			SELECT @MAUTORIZACION_ART = CAST(COALESCE(A.MAUTORIZACION, 0) AS BIT)
			FROM IZSOLD D WITH(NOLOCK)
			INNER JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
			WHERE D.CNSIZSOLD = @CNSIZSOLD
		IF COALESCE(@MAUTORIZACION_ART, 0) = 0
			SELECT @MAUTORIZACION_ART = CAST(COALESCE(MAUTORIZACION, 0) AS BIT)
			FROM IART WITH(NOLOCK)
			WHERE IDARTICULO = @IDARTICULO_PROA OR IDSERVICIO = @IDARTICULO_PROA OR IDSERVICIO = @IDARTICULO
		SELECT @CONSECUTIVOHCA = IZSOL.CONSECUTIVOHCA, @NOADMISION = IZSOL.NOADMISION, @FECHA_IZSOL = IZSOL.FECHASOL
		FROM IZSOL WITH(NOLOCK) WHERE IZSOL.CNSIZSOL = @CNSIZSOL
		IF COALESCE(@MAUTORIZACION_ART, 0) = 1 AND OBJECT_ID('DBO.HCATD_PROA', 'U') IS NOT NULL
		BEGIN
			SET @PROA_ESTADO_ART = NULL
			SET @PROA_INF = NULL
			SET @PROA_EPI = NULL
			SET @PROA_IDSERV = NULL
			SET @PROA_DIAS_SOL = NULL
			SET @PROA_DIAS_AUT = NULL
			SET @PROA_OBS = NULL
			SET @PROA_CNS_INICIAR = NULL
			SELECT TOP 1 @PROA_IDSERV = COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), A.IDSERVICIO, @IDARTICULO, @IDARTICULO_PROA)
			FROM IZSOLD D WITH(NOLOCK)
			LEFT JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
			WHERE D.CNSIZSOLD = @CNSIZSOLD OR (D.CNSIZSOL = @CNSIZSOL AND D.IDARTICULO = @IDARTICULO_REAL)

			SELECT TOP 1 @PROA_CNS_INICIAR = H.CONSECUTIVO
			FROM DBO.HCATD H WITH(NOLOCK)
			INNER JOIN DBO.HCA C WITH(NOLOCK) ON C.CONSECUTIVO = H.CONSECUTIVO
			WHERE C.NOADMISION = @NOADMISION
			  AND H.IDSERVICIO = @PROA_IDSERV
			  AND H.CLASE = 'I'
			  AND COALESCE(C.ANULADA, 0) <> 1
			ORDER BY C.FECHA ASC, H.CONSECUTIVO ASC

			IF @PROA_CNS_INICIAR IS NULL
			BEGIN
				SELECT TOP 1 @PROA_CNS_INICIAR = H.CONSECUTIVO
				FROM DBO.HCATD H WITH(NOLOCK)
				INNER JOIN DBO.HCA C WITH(NOLOCK) ON C.CONSECUTIVO = H.CONSECUTIVO
				WHERE C.NOADMISION = @NOADMISION
				  AND H.IDSERVICIO = @PROA_IDSERV
				  AND H.CLASE IN ('I', 'B', 'C')
				  AND COALESCE(C.ANULADA, 0) <> 1
				ORDER BY C.FECHA DESC, H.CONSECUTIVO DESC
			END

			SELECT TOP 1
				@PROA_ESTADO_ART = P.ESTADO,
				@PROA_INF = P.AUT_INFECTOLOGIA,
				@PROA_EPI = P.AUT_EPIDEMIOLOGIA,
				@PROA_DIAS_SOL = P.DIAS_TRATAMIENTO,
				@PROA_DIAS_AUT = COALESCE(P.DIAS_AUTORIZADOS, P.DIAS_TRATAMIENTO),
				@PROA_OBS = P.OBSERVACION
			FROM DBO.HCATD_PROA P WITH(NOLOCK)
			WHERE P.ESTADO_REG = 'A'
			  AND P.NOADMISION = @NOADMISION
			  AND P.IDSERVICIO = @PROA_IDSERV
			ORDER BY
				CASE WHEN @PROA_CNS_INICIAR IS NOT NULL AND P.CONSECUTIVO = @PROA_CNS_INICIAR THEN 0 ELSE 1 END,
				P.FECHA_SOL ASC
			IF @PROA_ESTADO_ART IS NULL
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'Este art�culo requiere autorizaci�n PROA (IART.MAUTORIZACION) y no hay solicitud PROA registrada. No se puede dispensar.'
			ELSE IF @PROA_ESTADO_ART = 'Vencido'
				INSERT INTO @TBLERRORES(ERROR) SELECT 'Este medicamento PROA est� VENCIDO. No se puede dispensar; debe reformularse.'
			ELSE IF @PROA_ESTADO_ART = 'NoAprobado' OR COALESCE(@PROA_INF, '') = 'No' OR COALESCE(@PROA_EPI, 'No') = 'No'
				INSERT INTO @TBLERRORES(ERROR)
				SELECT CONCAT(
					'Este medicamento no fue autorizado por el equipo PROA (Infectolog�a/Epidemiolog�a).',
					CASE WHEN NULLIF(LTRIM(RTRIM(@PROA_OBS)), '') IS NOT NULL THEN CONCAT(' Motivo: ', @PROA_OBS) ELSE '' END
				)
			ELSE IF @PROA_ESTADO_ART = 'Solicitado'
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'Este art�culo requiere autorizaci�n PROA y a�n est� pendiente de respuesta en Seguimiento Epidemiol�gico.'
		END
		ELSE IF COALESCE(@MAUTORIZACION_ART, 0) = 1 AND COALESCE(@CONSECUTIVOHCA, '') <> '' AND OBJECT_ID('DBO.HCATD_PROA', 'U') IS NULL
		BEGIN
			SET @CLASEPLANTILLA_HCA = NULL
			SET @ESTADO = NULL
			SELECT @CLASEPLANTILLA_HCA = HCA.CLASEPLANTILLA,
				   @FECHA_PREPRO       = COALESCE(HCA.FECHA, @FECHA_IZSOL)
			FROM HCA WITH(NOLOCK) WHERE HCA.CONSECUTIVO = @CONSECUTIVOHCA
			IF @CLASEPLANTILLA_HCA = 'PRE_PRO'
			BEGIN
				SELECT TOP 1 @ESTADO = HD.ALFANUMERICO
				FROM HCA H WITH(NOLOCK)
				INNER JOIN HCAD HD WITH(NOLOCK) ON HD.CONSECUTIVO = H.CONSECUTIVO
					AND HD.CAMPO = '200' AND COALESCE(HD.ALFANUMERICO, '') <> ''
				WHERE H.CLASEPLANTILLA = 'RPROAEPI'
				  AND H.NOADMISION = @NOADMISION
				  AND (@FECHA_PREPRO IS NULL OR H.FECHA >= @FECHA_PREPRO)
				ORDER BY H.FECHA DESC, H.CONSECUTIVO DESC
				IF COALESCE(@ESTADO, '') = ''
					INSERT INTO @TBLERRORES(ERROR) SELECT 'Este art�culo requiere autorizaci�n PROA y a�n est� pendiente de respuesta.'
				ELSE IF UPPER(LTRIM(RTRIM(@ESTADO))) = 'DENEGADO'
					INSERT INTO @TBLERRORES(ERROR) SELECT 'Este medicamento no fue autorizado por el equipo PROA Epidemiolog�a.'
			END
		END

		-- Medicamento suspendido vigente (FAR_OM_EVENTO CLASE='S', SER.MEDICAMENTOS=1): no dispensar por c�digo de barras.
		-- Solo solicitudes de admisi�n (HADM). No f�rmulas FORMED* ni CE/TRANS_CE/etc.
		IF OBJECT_ID('DBO.FAR_OM_EVENTO', 'U') IS NOT NULL
		   AND EXISTS (
			SELECT 1
			FROM IZSOLD D WITH(NOLOCK)
			INNER JOIN IZSOL Z WITH(NOLOCK) ON Z.CNSIZSOL = D.CNSIZSOL
			INNER JOIN IART A WITH(NOLOCK) ON A.IDARTICULO = D.IDARTICULO
			INNER JOIN FAR_OM_EVENTO FOE WITH(NOLOCK)
				ON FOE.NOADMISION = @NOADMISION
			   AND FOE.IDSERVICIO = COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), A.IDSERVICIO)
			   AND FOE.VIGENTE = 1
			   AND FOE.CLASE = 'S'
			   AND (
					NULLIF(LTRIM(RTRIM(D.CODOM)), '') IS NULL
					OR FOE.CODOM = D.CODOM
			   )
			INNER JOIN SER SER_FOE WITH(NOLOCK)
				ON SER_FOE.IDSERVICIO = FOE.IDSERVICIO AND SER_FOE.MEDICAMENTOS = 1
			WHERE D.CNSIZSOLD = @CNSIZSOLD
			  AND Z.CLASE IN ('24HORAS','OMEDICA','SENFER','HPRE')
		)
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'Este medicamento est� suspendido en la orden m�dica. No se puede dispensar.'

		IF EXISTS (SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
	
		IF  (SELECT DBO.FNK_VALORVARIABLE('RECETARIO_MC_DIGITAL')) = 'SI' AND (SELECT COUNT(1) FROM IZSOLD
                                INNER JOIN IZSOL ON IZSOL.CNSIZSOL=IZSOLD.CNSIZSOL INNER JOIN IART ON IART.IDARTICULO=IZSOLD.IDARTICULO
                                WHERE IZSOLD.CNSIZSOLD= @CNSIZSOLD AND IART.CONT_ESPECIAL=1 
                                AND NOT EXISTS (SELECT 1 FROM HCATDMC A INNER JOIN HCATDMCD B ON A.ID=B.HCATDMC_ID
                                               WHERE A.NOADMISION=IZSOL.NOADMISION AND B.IDARTICULO=IZSOLD.IDARTICULO AND A.PROCEDENCIA='H'
                                                       AND A.ESTADO='ACTIVO' AND CAST(A.FECHA AS DATE)=CAST(IZSOL.FECHASOL AS DATE) )) > 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Este medicamento aun no presenta recetario de mediamentos de control'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF  @CANTIDADSOL  = @CANTIDAD_ENTREGA
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Este Art�culo ya tiene La Cantidad Cumplida.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF  @CANTIDADSOL < (COALESCE(@CANTIDAD_ENTREGA,0)+@CANTIDAD)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Cantidad es mayor a los solicitado.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT TOP 1  @NOLOTE = NOLOTE, @NOLOTEPEDIDO = NOLOTEPEDIDO  , @EXISLOTE = EXISLOTE, @IDARTICULO_REAL = IEXI.IDARTICULO
		FROM IEXI  
			INNER JOIN IART ON IEXI.IDARTICULO = IART.IDARTICULO 
		WHERE IEXI.EXISLOTE>0  AND IART.IDSERVICIO =  @IDARTICULO AND CONVERT(DATE,IEXI.FECHAVENCE) >= CONVERT(DATE,GETDATE())
		ORDER BY  IEXI.FECHAVENCE ASC 

		IF  @EXISLOTE < @CANTIDAD
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Cantidad Supera el L�mite de existencias.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		
		BEGIN TRY 
			EXEC SPK_IZSOLDT_PROCESOS @IDARTICULO_REAL, @CNSIZSOLD, 'AGREGAR', @IDSEDE, @IDARTICULO, @NOLOTE, @CANTIDAD, @CANTIDADSOL, @CNSMOV, ''

			IF @CANTIDADSOL = (SELECT SUM(COALESCE(CANTIDADSOL,0)) FROM IZSOLDT WHERE CNSIZSOLD= @CNSIZSOLD)
			BEGIN
				UPDATE IZSOLD SET ESTADO = 0 WHERE  CNSIZSOLD = @CNSIZSOLD
			END

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END	
	IF @METODO = 'ACTUALIZA_CARGO'
	BEGIN
		SELECT @CNSIZSOL = CNSIZSOL, @IDBODEGA = IDBODEGA, @CNSMOV = CNSMOV
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSIZSOL				VARCHAR(20)			'$.CNSIZSOL'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		,CNSMOV					VARCHAR(20)			'$.CNSMOV'
		)
	
		SELECT @CLASE =  CLASE,@NOADMISION = NOADMISION, @SYS_ENTREGA = COALESCE(SYS_ENTREGA,''), @IDSEDE = IDSEDE, @SECTOR = SECTOR  FROM  IZSOL WHERE  CNSIZSOL = @CNSIZSOL
		SELECT @ESTADO_IMOV = ESTADO FROM IMOV WHERE CNSMOV = @CNSMOV

		BEGIN TRY 
		
		IF @CLASE NOT IN ('PROD','Consumo') 
		BEGIN
			IF @CLASE IN ('SENFER','APOYODX') 
			BEGIN
				EXEC SPK_GENCOBRO_INSCENTRAL  @CNSMOV, @NOADMISION, @SECTOR, @USUARIO, @IDSEDE
			END
			ELSE
			BEGIN
				IF (SELECT DBO.FNK_VALORVARIABLE('MODOCOBROMEDHBALI')) <> 'HBALI'
					EXEC SPK_GENCOBRO_INSCENTRAL  @CNSMOV, @NOADMISION, @SECTOR, @USUARIO, @IDSEDE
			END
			IF COALESCE(DBO.FNK_VALORVARIABLE('IENF_RECIBE_INSUMOS'), 'NO') <> 'SI'
			BEGIN
				UPDATE H
				SET H.RENFER = 1,
					H.CANTREP = CASE
						WHEN ISNULL(H.CANTREP, 0) >= ISNULL(H.CANTIDAD, 0) THEN H.CANTREP
						ELSE H.CANTIDAD
					END,
					H.USUARIOR = @USUARIO
				FROM IMOVH H
				INNER JOIN SER ON SER.IDSERVICIO = H.IDSERVICIO
				WHERE H.CNSMOV = @CNSMOV
				  AND ISNULL(SER.MEDICAMENTOS, 0) = 0
				  AND ISNULL(H.RENFER, 0) IN (0, 2)
			END
		END

			

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'CORREGIR_IMOVH'
	BEGIN
		SELECT @IDARTICULO = IDARTICULO, @IDBODEGA = IDBODEGA, @CNSMOV = CNSMOV, @NOLOTE = NOLOTE, @NOLOTEPEDIDO = NOLOTEPEDIDO
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		IDARTICULO				VARCHAR(20)			'$.IDARTICULO'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		,CNSMOV					VARCHAR(20)			'$.CNSMOV'
		,NOLOTE					VARCHAR(20)			'$.NOLOTE'
		,NOLOTEPEDIDO			VARCHAR(20)			'$.NOLOTEPEDIDO'
		)

		SELECT  @CNSTRAN = IMOVH.CNSTRAN, @CNSIZSOL = IMOV.NODOCUMENTO FROM IMOVH
		INNER JOIN IMOV ON IMOVH.CNSMOV = IMOV.CNSMOV
		WHERE IMOVH.IDARTICULO = @IDARTICULO AND IMOVH.CNSMOV = @CNSMOV  AND IMOVH.NOLOTE = @NOLOTE

		IF (SELECT COALESCE(ESTADO,0) FROM IMOV WHERE  CNSMOV = @CNSMOV) = 1
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'El registro de movmiento, ya esta Confirmado'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF (SELECT IDITAR FROM IART WHERE IDARTICULO = @IDARTICULO) = (SELECT DBO.FnK_ValorVariable('IDITARHEMODERIVADOS'))
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Este Articulo es de Banso de Sangre y la Pruebas Cruzadas Fueron Existosas No Se Puede Quitar de la Entrega'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			UPDATE IEXI SET EXISLOTE=EXISLOTE+A.CANTIDAD 
            FROM IEXI INNER JOIN 
               (SELECT IDARTICULOREAL, NOLOTE, SUM(ISNULL(CANTIDADSOL,0)) CANTIDAD FROM IZSOLDT 
                WHERE CNSMOV= @CNSMOV AND IDARTICULOREAL = @IDARTICULO AND NOLOTE = @NOLOTE
                GROUP BY IDARTICULOREAL, NOLOTE 
                ) A ON A.IDARTICULOREAL=IEXI.IDARTICULO AND A.NOLOTE=IEXI.NOLOTE 
            WHERE IEXI.IDBODEGA = @IDBODEGA

			UPDATE ISAL SET CANTIDAD=ISAL.CANTIDAD-A.CANTIDAD 
            FROM ISAL INNER JOIN 
               (SELECT CNSMOV, IDARTICULOREAL, NOLOTE, SUM(ISNULL(CANTIDADSOL,0)) CANTIDAD FROM IZSOLDT 
                WHERE CNSMOV= @CNSMOV AND IDARTICULOREAL= @IDARTICULO AND NOLOTE= @NOLOTE
                GROUP BY CNSMOV, IDARTICULOREAL, NOLOTE 
                ) A ON A.IDARTICULOREAL=ISAL.IDARTICULO AND A.NOLOTE=ISAL.NOLOTE AND A.CNSMOV=ISAL.CNSMOV 

			DELETE ISAL WHERE CANTIDAD<=0 AND CNSMOV = @CNSMOV

			DELETE IZSOLDT WHERE CNSMOV = @CNSMOV AND IDARTICULOREAL = @IDARTICULO AND NOLOTE = @NOLOTE

			DELETE IMOVH WHERE CNSMOV= @CNSMOV AND IDARTICULO = @IDARTICULO AND NOLOTE = @NOLOTE AND CNSTRAN = @CNSTRAN

			UPDATE IZSOLD SET ESTADO=A.ESTADO, TIPOENT=IIF(A.ESTADO=1,NULL,TIPOENT) 
            FROM IZSOLD INNER JOIN 
               (SELECT A.CNSIZSOL, A.CNSIZSOLD, (CASE WHEN SUM(ISNULL(B.CANTIDADSOL,0)) < SUM(A.CANTIDADSOL) THEN 1 ELSE 0 END) ESTADO 
                FROM IZSOLD A LEFT JOIN IZSOLDT B ON A.CNSIZSOLD=B.CNSIZSOLD 
                WHERE A.CNSIZSOL= @CNSIZSOL GROUP BY A.CNSIZSOL, A.CNSIZSOLD) A 
                ON A.CNSIZSOL=IZSOLD.CNSIZSOL AND A.CNSIZSOLD=IZSOLD.CNSIZSOLD AND A.ESTADO<>IZSOLD.ESTADO


		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'CONF_ENTRADA'
	BEGIN
		SELECT @CNSMOV = CNSMOV, @IDBODEGA = IDBODEGA 
		FROM OPENJSON (@PARAMETROS) 
		WITH (
			CNSMOV VARCHAR(20) '$.CNSMOV',
			IDBODEGA VARCHAR(20) '$.IDBODEGA'
		)

		SELECT @NODOCUMENTO = NODOCUMENTO, @IDTERCERO = IDTERCERO, @CNSFCOM = CNSFCOM, 
			   @IDTIPOMOV = IDTIPOMOV, @CNSTRAN = CNSTRAN,@PROCEDENCIA = PROCEDENCIA,
			   @IDBODEGA = IDBODEGA, @CCOSTO = CCOSTO
		FROM IMOV 
		WHERE CNSMOV = @CNSMOV

      IF DBO.FNK_VALORVARIABLE('IXCOUNTRY') = 'PERU' AND NOT EXISTS (SELECT 1 FROM CEN WHERE CCOSTO = @CCOSTO AND ESTADO = 'Activo') AND @PROCEDENCIA = 'HBALI'
      BEGIN
         IF @PROCEDENCIA = 'HBALI'
         BEGIN
            SELECT  @CCOSTO = HCA.CCOSTO FROM HCA 
            INNER JOIN CEN ON HCA.CCOSTO = CEN.CCOSTO
            WHERE HCA.NOADMISION = @NODOCUMENTO AND CEN.ESTADO = 'Activo'
         END
         UPDATE IMOV SET CCOSTO = COALESCE(@CCOSTO,CCOSTO) FROM IMOV WHERE CNSMOV = @CNSMOV
      END
		-- Recuperar detalle marcado (ESTADO=9) en intento fallido de confirmaci�n
		-- cuando la cabecera sigue sin confirmar (p. ej. devoluciones QXPGCX).
		UPDATE IMOVH
		SET ESTADO = 0
		WHERE CNSMOV = @CNSMOV
		  AND COALESCE(ESTADO, 0) = 9
		  AND EXISTS (
				SELECT 1 FROM IMOV
				WHERE CNSMOV = @CNSMOV AND COALESCE(ESTADO, 0) = 0
		  )

		-- Validaciones previas
		IF EXISTS (SELECT 1 FROM IMOVH INNER JOIN ITAR ON ITAR.IDITAR = IMOVH.IDITAR 
				   WHERE IMOVH.CNSMOV = @CNSMOV AND COALESCE(FECHAVENCE,'') ='' 
				   AND ITAR.MFECHAVENCIMIENTO =1 )
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'Existen articulos sin Fecha de Vencimiento.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF NOT EXISTS (
			SELECT 1 FROM IMOVH
			WHERE CNSMOV = @CNSMOV
			  AND COALESCE(ESTADO, 0) = 0
			  AND COALESCE(CANTIDAD, 0) > 0
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT CASE
				WHEN EXISTS (
					SELECT 1 FROM IMOVH
					WHERE CNSMOV = @CNSMOV AND COALESCE(CANTIDAD, 0) > 0
				)
					THEN 'El detalle existe pero no est� en estado confirmable. Revise l�neas inactivas o reintente; si persiste contacte soporte.'
				ELSE 'El registro no cuenta con Detalle, para confirmar'
			END
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF DBO.FNK_VALORVARIABLE ('IDINVMOV_COMPRAS') = @IDTIPOMOV 
			OR DBO.FNK_VALORVARIABLE ('IDINVMOV_REMISION_EN') = @IDTIPOMOV
		BEGIN
			IF (SELECT COUNT(1) FROM IMOV WHERE IMOV.NODOCUMENTO= @NODOCUMENTO 
				AND IMOV.IDTERCERO= @IDTERCERO AND IMOV.CNSMOV <> @CNSMOV 
				AND COALESCE(IMOV.ESTADO,0) <> 2 ) >=1
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) 
				SELECT 'N�mero de Factura Duplicado.... revisar'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END

			IF EXISTS (SELECT 1 FROM IMOV WHERE CNSMOV = @CNSMOV 
					   AND ((TIPO_DOC_COMPRA = 'F' AND (COALESCE(F_FACTURA, '') = '' OR COALESCE(F_VENCE, '') = '')) 
					   OR (TIPO_DOC_COMPRA = 'R' AND COALESCE(F_FACTURA, '') = '')))
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) 
				SELECT 'La Fecha de Factura y/o Fecha Vence Factura esta En Blanco...'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
		END

		IF (SELECT COUNT(1) FROM IMOVH WHERE CNSMOV = @CNSMOV AND COALESCE(PCOSTO,0)<=0) > 0 
			AND @IDTIPOMOV NOT IN (DBO.FNK_VALORVARIABLE('IDINVTPROPIA'))
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'Uno o Varios Lotes Ingresados no tienen precio de costo registrado en la base de datos...'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF @IDTIPOMOV = DBO.FNK_VALORVARIABLE('IDINVTPROPIA') AND COALESCE(@CNSTRAN,'')=''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'Es obligatorio, para este tipo de movimiento el Paciente.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF (SELECT ESTADO FROM IMOV WHERE CNSMOV= @CNSMOV) <> 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'El Movimiento de Inventario No esta Preparado para Confirmar Revise'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF (SELECT COUNT(1) FROM IMOVH INNER JOIN IMOV ON IMOV.CNSMOV = IMOVH.CNSMOV 
			INNER JOIN IART ON IART.IDARTICULO=IMOVH.IDARTICULO 
			INNER JOIN ITAR ON ITAR.IDITAR=IART.IDITAR 
			WHERE IMOVH.CNSMOV= @CNSMOV AND ISNULL(ITAR.MPRINCIPAL,0)=1 
			AND IART.PRINCIPAL=1 AND IMOV.IDTIPOMOV NOT IN (@IDTE )) > 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'El movimiento no puede ser confirmado porque existen articulos los cuales no se puede lotear el principal. Debe escoger un articulo hijo.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		-- Validaci�n de contabilizaci�n por CCosto (CXP_COMPRAS):
		-- Se valida dentro de CONF_ENTRADA para que el frontend no tenga que llamar a KMCOM.
		IF DBO.FNK_VALORVARIABLE('VALID_CCOSTO_CXP') = 'SI'
		   AND @IDTIPOMOV = DBO.FNK_VALORVARIABLE('IDINVMOV_COMPRAS')
		BEGIN
			SELECT @CCOSTO = CCOSTO
			FROM IMOV
			WHERE CNSMOV = @CNSMOV

			;WITH ITAR_MOV AS (
				SELECT DISTINCT IART.IDITAR
				FROM IMOVH
				INNER JOIN IART ON IMOVH.IDARTICULO = IART.IDARTICULO
				WHERE IMOVH.CNSMOV = @CNSMOV
				  AND COALESCE(IART.IDITAR,'') <> ''
			),
			KM AS (
				SELECT
					PREFIJO = KMCOM.PREFIJO,
					TIENE_DB = SUM(CASE WHEN KMCOM.TIPO='DB' AND COALESCE(KMCOM.CUENTA,'')<>'' THEN 1 ELSE 0 END),
					TIENE_CR = SUM(CASE WHEN KMCOM.TIPO='CR' AND COALESCE(KMCOM.CUENTA,'')<>'' THEN 1 ELSE 0 END)
				FROM KMCOM
				WHERE KMCOM.IDTIPOCONT = 'CXP_COMPRAS'
				  AND KMCOM.CCOSTO = @CCOSTO
				  AND KMCOM.PREFIJO IN (SELECT IDITAR FROM ITAR_MOV)
				GROUP BY KMCOM.PREFIJO
			),
			FALT AS (
				SELECT
					ITAR.IDITAR,
					ITAR.DESCRIPCION AS ITAR_DESC,
					COALESCE(KM.TIENE_DB,0) AS TIENE_DB,
					COALESCE(KM.TIENE_CR,0) AS TIENE_CR
				FROM ITAR_MOV X
				INNER JOIN ITAR ON X.IDITAR = ITAR.IDITAR
				LEFT JOIN KM ON KM.PREFIJO = X.IDITAR
				WHERE COALESCE(KM.TIENE_DB,0) <= 0
				   OR COALESCE(KM.TIENE_CR,0) <= 0
			)
			SELECT IDITAR, ITAR_DESC, TIENE_DB, TIENE_CR
			INTO #FALT_CXP_COMPRAS
			FROM FALT

			IF EXISTS (SELECT 1 FROM #FALT_CXP_COMPRAS)
			BEGIN
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'El Centro de Costo no est� correctamente configurado en Contabilizaci�n por Ubicaci�n (CXP_COMPRAS).'

				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				SELECT IDITAR, ITAR_DESC, TIENE_DB, TIENE_CR FROM #FALT_CXP_COMPRAS ORDER BY IDITAR
				DROP TABLE #FALT_CXP_COMPRAS
				RETURN
			END

			DROP TABLE #FALT_CXP_COMPRAS
		END



		BEGIN TRY
			-- XACT_ABORT OFF: evita Msg 266/3903 si SPK_CONFIRMARENTRADAS falla dentro de la transacci�n de SPQ_JSON.
			SET XACT_ABORT OFF

			EXEC SPK_CONFIRMARENTRADAS @IDBODEGA, @CNSMOV, @USUARIO, @COMPANIA, @IDSEDE, @SYS_COMPUTERNAME

			IF (SELECT COALESCE(ESTADO, 0) FROM IMOV WHERE CNSMOV = @CNSMOV) <> 1
			BEGIN
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'La entrada no pudo ser confirmada. Revise el detalle del movimiento.'
				SELECT 'KO' AS OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END

			-- La factura RADIAN puede haber llegado antes que la entrada.
			-- La sincronizaci�n es no bloqueante y nunca sobrescribe IMOV.CUFE.
			IF @IDTIPOMOV = DBO.FNK_VALORVARIABLE('IDINVMOV_COMPRAS')
			   AND OBJECT_ID(N'DBO.SPK_SINCRONIZAR_CUFE_RADIAN', N'P') IS NOT NULL
			BEGIN
				BEGIN TRY
					DECLARE @CUFE_ACTUALIZADOS_ENTRADA INT
						,@CUFE_AMBIGUOS_ENTRADA INT
						,@CUFE_SIN_COINCIDENCIA_ENTRADA INT

					EXEC DBO.SPK_SINCRONIZAR_CUFE_RADIAN
						@CNSRADIAN = NULL,
						@CNSMOV = @CNSMOV,
						@ACTUALIZADOS = @CUFE_ACTUALIZADOS_ENTRADA OUTPUT,
						@AMBIGUOS = @CUFE_AMBIGUOS_ENTRADA OUTPUT,
						@SIN_COINCIDENCIA = @CUFE_SIN_COINCIDENCIA_ENTRADA OUTPUT
				END TRY
				BEGIN CATCH
					PRINT CONCAT('Sincronizaci�n CUFE de entrada pendiente: ', ERROR_MESSAGE())
				END CATCH
			END

			IF EXISTS (SELECT 1 FROM IMOV WHERE CNSMOV = @CNSMOV AND COALESCE(ESTRANSITO, 0) = 1)
			BEGIN
				PRINT 'MARCADO EN CAMPO ESTRANSITO'
			END

			-- Verificar si hay IEXIF para actualizar (l�gica original)
			IF EXISTS (SELECT 1 FROM IEXIF WHERE CNSFCOM = @CNSFCOM)
			BEGIN
				UPDATE APLIMF 
				SET APLIMF.ESTADO = 'RESERVADO'
				FROM APLIMF
				WHERE APLIMF.ID IN (
					SELECT IEXIF.IDAPLIMF 
					FROM IEXIF 
					WHERE IEXIF.CNSFCOM = @CNSFCOM 
					AND COALESCE(ESTADO,'') = 'EN RUTA'
				)

				UPDATE IEXIF 
				SET IEXIF.ESTADO = 'RECEPCIONADO'
				FROM IEXIF
				WHERE IEXIF.CNSFCOM = @CNSFCOM 
				AND COALESCE(ESTADO,'') = 'EN RUTA'

				UPDATE APLIMF 
				SET APLIMF.IDARTICULO = IEXI.IDARTICULO, 
					APLIMF.IDIEXI = IEXI.ID
				FROM APLIMF 
				INNER JOIN (
					SELECT I1.ID, I1.IDARTICULO, IART_1.IDSERVICIO, 
						   ROW_NUMBER() OVER (PARTITION BY IART_1.IDSERVICIO ORDER BY I1.ID) as rn
					FROM IEXI I1 
					INNER JOIN IART IART_1 ON I1.IDARTICULO = IART_1.IDARTICULO
					WHERE I1.CNSMOV = @CNSMOV
				) IEXI ON APLIMF.IDSERVICIO = IEXI.IDSERVICIO
				INNER JOIN (
					SELECT ID, ROW_NUMBER() OVER (PARTITION BY IDSERVICIO ORDER BY ID) as rn
					FROM APLIMF 
					WHERE ID IN (SELECT IEXIF.IDAPLIMF FROM IEXIF WHERE IEXIF.CNSFCOM = @CNSFCOM)
				) APLIMF_RN ON APLIMF.ID = APLIMF_RN.ID AND IEXI.rn = APLIMF_RN.rn
				WHERE APLIMF.ID IN (SELECT IEXIF.IDAPLIMF FROM IEXIF WHERE IEXIF.CNSFCOM = @CNSFCOM)
			END


			IF DBO.FNK_VALORVARIABLE('IDINVTPROPIA') = @IDTIPOMOV
			BEGIN
				PRINT 'ENTRANDO A L�GICA DE ENLACE AUTOM�TICO PARA CUSTODIA'

				-- Lotes f�sicos de esta entrada (IDSERVICIO v�a IART o SER por art�culo hijo ej. MD0503-1)
				;WITH LOTES_CUSTODIA AS (
					SELECT
						IEXI.ID         AS IDIEXI,
						IEXI.IDARTICULO,
						COALESCE(
							NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
							(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
						) AS IDSERVICIO,
						IMOV.CNSTRAN    AS IDAFILIADO,
						ROW_NUMBER() OVER (
							PARTITION BY IMOV.CNSTRAN,
								COALESCE(
									NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
									(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
								)
							ORDER BY IEXI.FECHAVENCE ASC, IEXI.ID ASC
						) AS RN
					FROM IMOVH
					INNER JOIN IMOV  ON IMOVH.CNSMOV = IMOV.CNSMOV
					INNER JOIN IART  ON IMOVH.IDARTICULO = IART.IDARTICULO
					INNER JOIN IEXI  ON IEXI.CNSMOV     = IMOVH.CNSMOV
					               AND IEXI.IDARTICULO = IMOVH.IDARTICULO
					               AND IEXI.NOLOTE     = IMOVH.NOLOTE
					               AND COALESCE(IEXI.NOLOTEPEDIDO, '') = COALESCE(IMOVH.NOLOTEPEDIDO, '')
					WHERE IMOVH.CNSMOV = @CNSMOV
					  AND COALESCE(IMOV.CNSTRAN, '') <> ''
					  AND COALESCE(IEXI.EXISLOTE, 0) > 0
					  AND IEXI.ID NOT IN (SELECT IDIEXI FROM APLIMF WHERE IDIEXI IS NOT NULL)
					  AND COALESCE(
							NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
							(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
					  ) IS NOT NULL
				),
				PENDIENTES_IEXIF AS (
					SELECT
						APLIMF.ID       AS IDAPLIMF,
						APLI.IDAFILIADO,
						APLIMF.IDSERVICIO,
						IEXIF.ID        AS IDIEXIF,
						ROW_NUMBER() OVER (
							PARTITION BY APLI.IDAFILIADO, APLIMF.IDSERVICIO
							ORDER BY COALESCE(APLIM.FECHA, '19000101') DESC, APLIMF.ID ASC
						) AS RN
					FROM APLIMF
					INNER JOIN IEXIF ON IEXIF.IDAPLIMF = APLIMF.ID
					              AND COALESCE(IEXIF.ESTADO, '') IN ('PENDIENTE GESTION', 'PENDIENTE COMPRA')
					INNER JOIN APLIM ON APLIMF.IDAPLIM = APLIM.ID
					INNER JOIN APLI  ON APLIM.IDAPLI = APLI.ID
					INNER JOIN IMOV  ON IMOV.CNSMOV = @CNSMOV
					              AND IMOV.CNSTRAN = APLI.IDAFILIADO
					WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
					  AND APLIMF.IDIEXI IS NULL
					  -- Solo aplicaciones vigentes (evitar residuales de APLIM ya APLICADO/CANCELADA)
					  AND COALESCE(APLIM.APLICADO, 0) = 0
					  AND COALESCE(APLIM.ESTADO, '') NOT IN ('APLICADO', 'CANCELADA')
					  AND COALESCE(APLI.ESTADO, 'Activo') = 'Activo'
				),
				PARES_IEXIF AS (
					SELECT L.IDIEXI, L.IDARTICULO, L.IDSERVICIO, P.IDAPLIMF, P.IDIEXIF
					FROM LOTES_CUSTODIA L
					INNER JOIN PENDIENTES_IEXIF P
						ON P.IDAFILIADO = L.IDAFILIADO
					   AND P.RN = L.RN
					   AND (
							L.IDSERVICIO = P.IDSERVICIO
						 OR EXISTS (
								SELECT 1 FROM SER S
								WHERE S.IDSERVICIO = P.IDSERVICIO
								  AND S.IDARTICULO = L.IDARTICULO
							)
					   )
				)
				UPDATE APLIMF
				SET
					APLIMF.ESTADO     = 'RESERVADO',
					-- Preferir art�culo f�sico del lote; SER suele traer 'NA' (NO APLICA) en custodia
					APLIMF.IDARTICULO = COALESCE(
						NULLIF(LTRIM(RTRIM(P.IDARTICULO)), ''),
						NULLIF(NULLIF(LTRIM(RTRIM((
							SELECT TOP 1 SER.IDARTICULO FROM SER WHERE SER.IDSERVICIO = APLIMF.IDSERVICIO
						))), ''), 'NA')
					),
					APLIMF.IDIEXI     = P.IDIEXI
				FROM APLIMF
				INNER JOIN PARES_IEXIF P ON P.IDAPLIMF = APLIMF.ID
				WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
				  AND APLIMF.IDIEXI IS NULL;

				UPDATE IEXIF
				SET IEXIF.ESTADO = 'RECEPCIONADO'
				FROM IEXIF
				INNER JOIN APLIMF ON IEXIF.IDAPLIMF = APLIMF.ID
				INNER JOIN APLIM  ON APLIMF.IDAPLIM = APLIM.ID
				INNER JOIN APLI   ON APLIM.IDAPLI = APLI.ID
				INNER JOIN IMOV   ON IMOV.CNSMOV = @CNSMOV AND IMOV.CNSTRAN = APLI.IDAFILIADO
				WHERE IEXIF.ESTADO IN ('PENDIENTE GESTION', 'PENDIENTE COMPRA')
				  AND APLIMF.ESTADO = 'RESERVADO'
				  AND APLIMF.IDIEXI IS NOT NULL;

				-- Ruta 2: fallback con cita agendada (sin IEXIF)
				;WITH LOTES_RESTANTES AS (
					SELECT
						IEXI.ID         AS IDIEXI,
						IEXI.IDARTICULO,
						COALESCE(
							NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
							(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
						) AS IDSERVICIO,
						IMOV.CNSTRAN    AS IDAFILIADO,
						ROW_NUMBER() OVER (
							PARTITION BY IMOV.CNSTRAN,
								COALESCE(
									NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
									(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
								)
							ORDER BY IEXI.FECHAVENCE ASC, IEXI.ID ASC
						) AS RN
					FROM IMOVH
					INNER JOIN IMOV ON IMOVH.CNSMOV = IMOV.CNSMOV
					INNER JOIN IART ON IMOVH.IDARTICULO = IART.IDARTICULO
					INNER JOIN IEXI ON IEXI.CNSMOV     = IMOVH.CNSMOV
					              AND IEXI.IDARTICULO = IMOVH.IDARTICULO
					              AND IEXI.NOLOTE     = IMOVH.NOLOTE
					              AND COALESCE(IEXI.NOLOTEPEDIDO, '') = COALESCE(IMOVH.NOLOTEPEDIDO, '')
					WHERE IMOVH.CNSMOV = @CNSMOV
					  AND COALESCE(IMOV.CNSTRAN, '') <> ''
					  AND COALESCE(IEXI.EXISLOTE, 0) > 0
					  AND IEXI.ID NOT IN (SELECT IDIEXI FROM APLIMF WHERE IDIEXI IS NOT NULL)
					  AND COALESCE(
							NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
							(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
					  ) IS NOT NULL
				),
				PENDIENTES_CIT AS (
					SELECT
						APLIMF.ID       AS IDAPLIMF,
						APLI.IDAFILIADO,
						APLIMF.IDSERVICIO,
						ROW_NUMBER() OVER (
							PARTITION BY APLI.IDAFILIADO, APLIMF.IDSERVICIO
							ORDER BY CIT.FECHA ASC, APLIMF.ID ASC
						) AS RN
					FROM APLIMF
					INNER JOIN APLIM ON APLIMF.IDAPLIM = APLIM.ID
					INNER JOIN APLI  ON APLIM.IDAPLI = APLI.ID
					INNER JOIN CIT   ON APLIM.CONSECUTIVOCIT = CIT.CONSECUTIVO
					INNER JOIN IMOV  ON IMOV.CNSMOV = @CNSMOV AND IMOV.CNSTRAN = APLI.IDAFILIADO
					WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
					  AND APLIMF.IDIEXI IS NULL
					  AND APLIM.CONSECUTIVOCIT IS NOT NULL
					  AND COALESCE(APLIM.APLICADO, 0) = 0
					  AND COALESCE(APLIM.ESTADO, '') NOT IN ('APLICADO', 'CANCELADA')
					  AND COALESCE(APLI.ESTADO, 'Activo') = 'Activo'
					  AND NOT EXISTS (
						  SELECT 1 FROM IEXIF
						  WHERE IEXIF.IDAPLIMF = APLIMF.ID
						    AND COALESCE(IEXIF.ESTADO, '') IN ('PENDIENTE GESTION', 'PENDIENTE COMPRA')
					  )
				),
				PARES_CIT AS (
					SELECT L.IDIEXI, L.IDARTICULO, L.IDSERVICIO, P.IDAPLIMF
					FROM LOTES_RESTANTES L
					INNER JOIN PENDIENTES_CIT P
						ON P.IDAFILIADO = L.IDAFILIADO
					   AND P.RN = L.RN
					   AND (
							L.IDSERVICIO = P.IDSERVICIO
						 OR EXISTS (
								SELECT 1 FROM SER S
								WHERE S.IDSERVICIO = P.IDSERVICIO
								  AND S.IDARTICULO = L.IDARTICULO
							)
					   )
				)
				UPDATE APLIMF
				SET
					APLIMF.ESTADO     = 'RESERVADO',
					APLIMF.IDARTICULO = COALESCE(
						NULLIF(LTRIM(RTRIM(P.IDARTICULO)), ''),
						NULLIF(NULLIF(LTRIM(RTRIM((
							SELECT TOP 1 SER.IDARTICULO FROM SER WHERE SER.IDSERVICIO = APLIMF.IDSERVICIO
						))), ''), 'NA')
					),
					APLIMF.IDIEXI     = P.IDIEXI
				FROM APLIMF
				INNER JOIN PARES_CIT P ON P.IDAPLIMF = APLIMF.ID
				WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
				  AND APLIMF.IDIEXI IS NULL;

				-- Ruta 3: paciente + servicio directo (sin IEXIF ni cita)
				;WITH LOTES_DIRECTO AS (
					SELECT
						IEXI.ID         AS IDIEXI,
						IEXI.IDARTICULO,
						COALESCE(
							NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
							(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
						) AS IDSERVICIO,
						IMOV.CNSTRAN    AS IDAFILIADO,
						ROW_NUMBER() OVER (
							PARTITION BY IMOV.CNSTRAN,
								COALESCE(
									NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
									(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
								)
							ORDER BY IEXI.FECHAVENCE ASC, IEXI.ID ASC
						) AS RN
					FROM IMOVH
					INNER JOIN IMOV ON IMOVH.CNSMOV = IMOV.CNSMOV
					INNER JOIN IART ON IMOVH.IDARTICULO = IART.IDARTICULO
					INNER JOIN IEXI ON IEXI.CNSMOV     = IMOVH.CNSMOV
					              AND IEXI.IDARTICULO = IMOVH.IDARTICULO
					              AND IEXI.NOLOTE     = IMOVH.NOLOTE
					              AND COALESCE(IEXI.NOLOTEPEDIDO, '') = COALESCE(IMOVH.NOLOTEPEDIDO, '')
					WHERE IMOVH.CNSMOV = @CNSMOV
					  AND COALESCE(IMOV.CNSTRAN, '') <> ''
					  AND COALESCE(IEXI.EXISLOTE, 0) > 0
					  AND IEXI.ID NOT IN (SELECT IDIEXI FROM APLIMF WHERE IDIEXI IS NOT NULL)
					  AND COALESCE(
							NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''),
							(SELECT TOP 1 S.IDSERVICIO FROM SER S WHERE S.IDARTICULO = IEXI.IDARTICULO)
					  ) IS NOT NULL
				),
				PENDIENTES_DIRECTO AS (
					SELECT
						APLIMF.ID       AS IDAPLIMF,
						APLI.IDAFILIADO,
						APLIMF.IDSERVICIO,
						ROW_NUMBER() OVER (
							PARTITION BY APLI.IDAFILIADO, APLIMF.IDSERVICIO
							ORDER BY COALESCE(APLIM.FECHA, '19000101') DESC, APLIMF.ID ASC
						) AS RN
					FROM APLIMF
					INNER JOIN APLIM ON APLIMF.IDAPLIM = APLIM.ID
					INNER JOIN APLI  ON APLIM.IDAPLI = APLI.ID
					INNER JOIN IMOV  ON IMOV.CNSMOV = @CNSMOV AND IMOV.CNSTRAN = APLI.IDAFILIADO
					WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
					  AND APLIMF.IDIEXI IS NULL
					  AND COALESCE(APLIM.APLICADO, 0) = 0
					  AND COALESCE(APLIM.ESTADO, '') NOT IN ('APLICADO', 'CANCELADA')
					  AND COALESCE(APLI.ESTADO, 'Activo') = 'Activo'
				),
				PARES_DIRECTO AS (
					SELECT L.IDIEXI, L.IDARTICULO, L.IDSERVICIO, P.IDAPLIMF
					FROM LOTES_DIRECTO L
					INNER JOIN PENDIENTES_DIRECTO P
						ON P.IDAFILIADO = L.IDAFILIADO
					   AND P.RN = L.RN
					   AND (
							L.IDSERVICIO = P.IDSERVICIO
						 OR EXISTS (
								SELECT 1 FROM SER S
								WHERE S.IDSERVICIO = P.IDSERVICIO
								  AND S.IDARTICULO = L.IDARTICULO
							)
					   )
				)
				UPDATE APLIMF
				SET
					APLIMF.ESTADO     = 'RESERVADO',
					APLIMF.IDARTICULO = COALESCE(
						NULLIF(LTRIM(RTRIM(P.IDARTICULO)), ''),
						NULLIF(NULLIF(LTRIM(RTRIM((
							SELECT TOP 1 SER.IDARTICULO FROM SER WHERE SER.IDSERVICIO = APLIMF.IDSERVICIO
						))), ''), 'NA')
					),
					APLIMF.IDIEXI     = P.IDIEXI
				FROM APLIMF
				INNER JOIN PARES_DIRECTO P ON P.IDAPLIMF = APLIMF.ID
				WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
				  AND APLIMF.IDIEXI IS NULL;

				-- Ruta 4: CROSS APPLY - cualquier lote de custodia del paciente (incluye entradas anteriores)
				UPDATE APLIMF
				SET
					APLIMF.ESTADO     = 'RESERVADO',
					APLIMF.IDARTICULO = COALESCE(
						NULLIF(NULLIF(LTRIM(RTRIM(LO.IDARTICULO)), ''), 'NA'),
						NULLIF(NULLIF(LTRIM(RTRIM(APLIMF.IDARTICULO)), ''), 'NA'),
						NULLIF(NULLIF(LTRIM(RTRIM((
							SELECT TOP 1 SER.IDARTICULO FROM SER WHERE SER.IDSERVICIO = APLIMF.IDSERVICIO
						))), ''), 'NA'),
						LO.IDARTICULO
					),
					APLIMF.IDIEXI     = LO.IDIEXI
				FROM APLIMF
				INNER JOIN APLIM ON APLIMF.IDAPLIM = APLIM.ID
				INNER JOIN APLI  ON APLIM.IDAPLI = APLI.ID
				INNER JOIN IMOV  ON IMOV.CNSMOV = @CNSMOV AND IMOV.CNSTRAN = APLI.IDAFILIADO
				CROSS APPLY (
					SELECT TOP 1 IEXI.ID AS IDIEXI, IEXI.IDARTICULO
					FROM IEXI
					INNER JOIN IMOV M ON IEXI.CNSMOV = M.CNSMOV AND M.CNSTRAN = APLI.IDAFILIADO
					INNER JOIN IBOD ON IEXI.IDBODEGA = IBOD.IDBODEGA AND COALESCE(IBOD.ESDECUSTODIA, 0) = 1
					INNER JOIN IART ON IEXI.IDARTICULO = IART.IDARTICULO
					WHERE COALESCE(IEXI.EXISLOTE, 0) > 0
					  AND NOT EXISTS (SELECT 1 FROM APLIMF X WHERE X.IDIEXI = IEXI.ID)
					  AND (
							IART.IDSERVICIO = APLIMF.IDSERVICIO
						 OR IEXI.IDARTICULO = APLIMF.IDARTICULO
						 OR IEXI.IDARTICULO LIKE APLIMF.IDSERVICIO + '-%'
						 OR IEXI.IDARTICULO LIKE APLIMF.IDSERVICIO + '%'
						 OR EXISTS (
								SELECT 1 FROM SER S
								WHERE S.IDSERVICIO = APLIMF.IDSERVICIO
								  AND (S.IDARTICULO = IEXI.IDARTICULO OR S.IDARTICULO = APLIMF.IDARTICULO)
							)
					  )
					ORDER BY IEXI.FECHAVENCE ASC, IEXI.ID ASC
				) LO
				WHERE APLIMF.ESTADO = 'PENDIENTE GESTION'
				  AND APLIMF.IDIEXI IS NULL
				  AND COALESCE(APLIM.APLICADO, 0) = 0
				  AND COALESCE(APLIM.ESTADO, '') NOT IN ('APLICADO', 'CANCELADA')
				  AND COALESCE(APLI.ESTADO, 'Activo') = 'Activo';

			END

		-- Propagar art�culo real a IZSOLD (evita NA / NO APLICA en solicitudes APLIM)
		UPDATE IZSOLD
		SET IZSOLD.IDARTICULO = APLIMF.IDARTICULO
		FROM IZSOLD
		INNER JOIN APLIMF ON IZSOLD.IDAPLIMF = APLIMF.ID
		WHERE APLIMF.ESTADO = 'RESERVADO'
		  AND APLIMF.IDARTICULO IS NOT NULL
		  AND NULLIF(LTRIM(RTRIM(APLIMF.IDARTICULO)), '') NOT IN ('NA')
		  AND (
				COALESCE(IZSOLD.IDARTICULO, '') <> APLIMF.IDARTICULO
			 OR COALESCE(IZSOLD.IDARTICULO, '') IN ('', 'NA')
		  )
		  AND EXISTS (
				SELECT 1
				FROM APLIM
				INNER JOIN APLI ON APLIM.IDAPLI = APLI.ID
				INNER JOIN IMOV M ON M.CNSMOV = @CNSMOV AND M.CNSTRAN = APLI.IDAFILIADO
				WHERE APLIM.ID = APLIMF.IDAPLIM
		  )

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT LEFT(CONCAT(
				ERROR_MESSAGE(),
				' [',
				COALESCE(ERROR_PROCEDURE(), 'CONF_ENTRADA'),
				' L',
				CAST(ERROR_LINE() AS VARCHAR(10)),
				']'
			), 2048)
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'ANULAR_ENTRADA'
	BEGIN
		SELECT @CNSMOV = CNSMOV, @IDBODEGA = IDBODEGA
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSMOV   VARCHAR(20) '$.CNSMOV',
			IDBODEGA VARCHAR(20) '$.IDBODEGA'
		)

		IF COALESCE(@CNSMOV, '') = '' OR COALESCE(@IDBODEGA, '') = ''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Debe indicar CNSMOV e IDBODEGA.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (SELECT 1 FROM IMOV WHERE IMOV.CNSMOV = @CNSMOV AND COALESCE(IMOV.ESTADO, 0) <> 0)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'S�lo se puede anular un movimiento sin confirmar.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (SELECT 1 FROM IMOVH WHERE IMOVH.CNSMOV = @CNSMOV)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se puede anular: el movimiento tiene detalle en IMOVH.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		UPDATE IMOV
		SET ESTADO = 2
		WHERE CNSMOV = @CNSMOV AND IDBODEGA = @IDBODEGA AND COALESCE(ESTADO, 0) = 0

		IF @@ROWCOUNT = 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se pudo anular el movimiento.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'TRASLADO_ENTRADA'
	BEGIN
		SELECT @CNSMOV = CNSMOV, @IDBODEGA = IDBODEGA, @IDITAR = IDITAR
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSMOV			VARCHAR(20)		'$.CNSMOV'
			,IDBODEGA		VARCHAR(20)		'$.IDBODEGA'
			,IDITAR			VARCHAR(20)		'$.IDITAR'
			)

		IF (SELECT COUNT(*) FROM IBODS WHERE IDBODEGA= @IDBODEGA AND 
					TIPO='ITAR' AND VALOR=@IDITAR AND ACCESO='Si') = 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'ERROR: La Bodega Destino No Tiene Permisos para usar el Tipo de Articulo.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		
		BEGIN TRY 
			UPDATE IMOV SET IDBODEGA = @IDBODEGA WHERE CNSMOV = @CNSMOV
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'AGREGAR_CANASTA'
	BEGIN
		SELECT @CNSMOV = CNSMOV, @IDBODEGA = IDBODEGA, @PROCEDENCIA = PROCEDENCIA, @IDSERVICIO_CIR = IDSERVICIO
		FROM OPENJSON (@PARAMETROS)
		WITH (
		  CNSMOV VARCHAR(20) '$.CNSMOV'
		 ,IDBODEGA VARCHAR(20) '$.IDBODEGA'
		 ,PROCEDENCIA VARCHAR(20) '$.PROCEDENCIA'
		 ,IDSERVICIO VARCHAR(20) '$.IDSERVICIO'
		)

		IF (SELECT  DBO.FNK_VALORVARIABLE('INVE_CIRU_TIPO_MOV')) IS NULL
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No tiene la variable ''INVE_CIRU_TIPO_MOV'' configurada'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF NOT EXISTS (SELECT 1 FROM ITMO WHERE TIPO = 'Debito' AND IDTIPOMOV = (SELECT  DBO.FNK_VALORVARIABLE('INVE_CIRU_TIPO_MOV')))
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La variable configurada no es de tipo salida. ''Debito'''
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		BEGIN TRY 
			IF UPPER(@PROCEDENCIA) = 'NUEVO'
			BEGIN
				SELECT @SYS_ComputerName = SYS_ComputerName, @IDSEDE=IDSEDE, @IDBODEGASOL=IDBODEGA FROM USUSU WHERE USUARIO=@USUARIO
				SELECT @TIPO_USUARIO = TIPO_USUARIO FROM MED INNER JOIN USUSU ON USUSU.IDMEDICO=MED.IDMEDICO WHERE USUARIO=@USUARIO
				SELECT @IDBODEGACONSUMO = IDBODEGA, @CCOSTO=CCOSTO FROM UBEQ WHERE SYS_COMPUTERNAME = @SYS_ComputerName

				EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE,@PREFIJO='@IZSOL', @NVOCONSEC=@CNSIZSOL OUTPUT  

			INSERT INTO IZSOL(CNSIZSOL,FECHASOL,USUARIOSOL,ESTADO,IDSEDE,SECTOR,IDBODEGASOLICITA,IDBODEGAATIENDE,CLASE,NOADMISION,SYS_COMPUTER,IDPLAN, SYS_ENTREGA)
			SELECT @CNSIZSOL,DBO.FNK_FECHA_SIN_MLS(GETDATE()),@USUARIO,1,@IDSEDE,'CANASTA',@IDBODEGA,@IDBODEGA,'Canasta', NULL, @SYS_ComputerName,NULL, @SYS_COMPUTERNAME


				EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE,@PREFIJO='@MOV',  @NVOCONSEC=@NVOCONSEC OUTPUT  
				INSERT INTO IMOV (CNSMOV, IDBODEGA, IDTIPOMOV, NODOCUMENTO, FECHAMOV, CCOSTO, IDSOLICITA, IDFUNCIONARIO,
									ESTADO, OBSERVACION, SUBIOCOMPRA, IDAREA, CONTABILIZADA, PROCEDENCIA, USUARIO, PARCIAL, 
									SYS_ComputerName, TIENECAMBIO, IDITAR, ESTRANSITO, IDBODEGAEXTERNA,IDTERCERO,IDPLAN,GENFACTURA,FACTURADA,
									IDSERVICIO)
				SELECT @NVOCONSEC, @IDBODEGA, DBO.FNK_VALORVARIABLE('INVE_CIRU_TIPO_MOV'), @CNSIZSOL, 
					DBO.FNK_FECHA_SIN_MLS(GETDATE()), 
					@CCOSTO, @USUARIO, @USUARIO, '0', '', 0, NULL,0, 'Consumo', @USUARIO, 0, @SYS_COMPUTERNAME, 0, '01', 0, @IDBODEGA,NULL,
					NULL,0,NULL, @IDSERVICIO_CIR

				UPDATE IZSOL SET CNSMOV = @NVOCONSEC WHERE CNSIZSOL = @CNSIZSOL
			
				SELECT TOP 1 @CNSMOV= CNSMOV, @IDBODEGA = IMOV.IDBODEGA, @IDBODEGA_DESC = IBOD.DESCRIPCION,@CNSIZSOL =NODOCUMENTO   FROM IMOV
				INNER JOIN IBOD ON IMOV.IDBODEGA = IBOD.IDBODEGA
				WHERE IMOV.NODOCUMENTO = @CNSIZSOL

				SELECT 'OK' OK , @CNSMOV CNSMOV, @IDBODEGA IDBODEGA, @IDBODEGA_DESC IDBODEGA_DESC, @CNSIZSOL CNSIZSOL
			END
			IF UPPER(@PROCEDENCIA) = 'EDITAR'
			BEGIN
				SELECT TOP 1 @CNSMOV= CNSMOV, @IDBODEGA = IMOV.IDBODEGA, @IDBODEGA_DESC = IBOD.DESCRIPCION,@CNSIZSOL =NODOCUMENTO,  
					@IDSERVICIO_CIR = IDSERVICIO
				FROM IMOV
				INNER JOIN IBOD ON IMOV.IDBODEGA = IBOD.IDBODEGA
				WHERE IMOV.CNSMOV = @CNSMOV

			SELECT 'OK' OK, @CNSMOV CNSMOV, @IDBODEGA IDBODEGA, @IDBODEGA_DESC IDBODEGA_DESC, @CNSIZSOL CNSIZSOL, @IDSERVICIO_CIR IDSERVICIO

	END
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END

	IF @METODO = 'TRAER_CANASTA'
	BEGIN
		DECLARE @IDSERVICIO_CIRUGIA VARCHAR(20);

		SELECT
			@CNSMOV = CNSMOV,
			@CNSIZSOL = CNSIZSOL,
			@IDSERVICIO_CIRUGIA = IDSERVICIO
		FROM OPENJSON(@PARAMETROS)
		WITH (
			CNSMOV      VARCHAR(20) '$.CNSMOV',
			CNSIZSOL    VARCHAR(20) '$.CNSIZSOL',
			IDSERVICIO  VARCHAR(20) '$.IDSERVICIO'
		);

		-- Si no viene CNSIZSOL, lo toma del movimiento
		IF COALESCE(@CNSIZSOL, '') = '' AND COALESCE(@CNSMOV, '') <> ''
		BEGIN
			SELECT @CNSIZSOL = NODOCUMENTO
			FROM IMOV
			WHERE CNSMOV = @CNSMOV;
		END

		-- Si no viene IDSERVICIO, lo toma del movimiento
		IF COALESCE(@IDSERVICIO_CIRUGIA, '') = '' AND COALESCE(@CNSMOV, '') <> ''
		BEGIN
			SELECT @IDSERVICIO_CIRUGIA = IDSERVICIO
			FROM IMOV
			WHERE CNSMOV = @CNSMOV;
		END

		IF COALESCE(@CNSIZSOL, '') = ''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se encontr� CNSIZSOL para traer canasta.';
			SELECT 'KO' OK;
			SELECT ERROR FROM @TBLERRORES;
			RETURN;
		END

		IF COALESCE(@IDSERVICIO_CIRUGIA, '') = ''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se encontr� IDSERVICIO (cirug�a) para traer canasta.';
			SELECT 'KO' OK;
			SELECT ERROR FROM @TBLERRORES;
			RETURN;
		END

		IF NOT EXISTS (SELECT 1 FROM HCINP WHERE CIRUGIA = @IDSERVICIO_CIRUGIA)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La cirug�a no tiene canasta configurada en HCINP.';
			SELECT 'KO' OK;
			SELECT ERROR FROM @TBLERRORES;
			RETURN;
		END

		BEGIN TRY
			;WITH CFG AS
			(
				SELECT
					H.CIRUGIA,
					H.IDSER,
					CANTIDAD = CAST(CASE WHEN COALESCE(H.CANTIDADEST,0) > 0 THEN H.CANTIDADEST ELSE 1 END AS INT)
				FROM HCINP H
				WHERE H.CIRUGIA = @IDSERVICIO_CIRUGIA
				  
			),
			MAPEO AS
			(SELECT C.CIRUGIA, C.IDSER, C.CANTIDAD, IA.IDARTICULO, IA.IDSERVICIO AS IDSERVICIO_ART
				FROM CFG C
				OUTER APPLY
				(
					SELECT TOP 1 IART.IDARTICULO, IART.IDSERVICIO
					FROM IART
					WHERE IART.ESTADO = 'Activo'
					  AND (
							IART.IDSERVICIO = C.IDSER
						 OR IART.IDARTICULO = C.IDSER
					  )
					ORDER BY
						CASE WHEN IART.IDARTICULO = C.IDSER THEN 0 ELSE 1 END,
						COALESCE(IART.PRINCIPAL,0) DESC,
						IART.IDARTICULO
				) IA
			)
			INSERT INTO IZSOLD (CNSIZSOL, IDARTICULO, CANTIDADSOL, ESTADO, CODOM, CANTIDAD, IDSERVICIO, NEWCNSIZOLD)
			SELECT @CNSIZSOL, M.IDARTICULO, M.CANTIDAD, 1, '', 0, COALESCE(M.IDSERVICIO_ART, M.IDSER), ''
			FROM MAPEO M
			WHERE M.IDARTICULO IS NOT NULL
			  AND NOT EXISTS
			  (SELECT 1 FROM IZSOLD Z WHERE Z.CNSIZSOL = @CNSIZSOL
					AND (Z.IDARTICULO = M.IDARTICULO
						OR Z.IDARTICULO = M.IDSER
						OR Z.IDSERVICIO = COALESCE(M.IDSERVICIO_ART, M.IDSER)
					)
			  );

			SELECT 'OK' OK, @@ROWCOUNT AS INSERTADOS, @CNSIZSOL AS CNSIZSOL;
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE();
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' OK;
			SELECT ERROR FROM @TBLERRORES;
			RETURN;
		END

		RETURN;
	END

	IF @METODO = 'AGREGAR_ARTICULO'
	BEGIN
		SELECT @CNSMOV = CNSMOV, @IDBODEGA = IDBODEGA, @IDARTICULO = IDARTICULO, @PROCEDENCIA = PROCEDENCIA , @CANTIDAD = CANTIDAD
	   FROM OPENJSON (@PARAMETROS)
	   WITH		 (
		CNSMOV					VARCHAR(20)			'$.CNSMOV'
		,IDBODEGA				VARCHAR(20)			'$.IDBODEGA'
		,PROCEDENCIA			VARCHAR(20)			'$.PROCEDENCIA'
		,IDARTICULO				VARCHAR(20)			'$.IDARTICULO'
		,CANTIDAD				INT					'$.CANTIDAD'
		)
		
		BEGIN TRY 
			IF UPPER(@PROCEDENCIA) = 'NUEVO'
			BEGIN
				
				EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE,@PREFIJO='@IZSOLD', @NVOCONSEC=@CNSIZSOLD OUTPUT  

				SELECT @CNSIZSOL = NODOCUMENTO FROM IMOV WHERE  CNSMOV = @CNSMOV
				SELECT @IDSERVICIO=IDSERVICIO FROM IART WHERE IDARTICULO=@IDARTICULO			
				INSERT INTO IZSOLD(CNSIZSOL,IDARTICULO,CANTIDADSOL,ESTADO,CODOM,CANTIDAD,IDSERVICIO, NEWCNSIZOLD)
				SELECT @CNSIZSOL,  @IDARTICULO, @CANTIDAD, 1, '', 0, @IDSERVICIO, ''
			END
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END	
	IF @METODO = 'VALIDA_VERIFICA'
	BEGIN
		SELECT @CNSITRA = CNSITRA
		FROM OPENJSON (@PARAMETROS)
		WITH (CNSITRA VARCHAR(20) '$.CNSITRA')

		SELECT @IDBODEGA = IDBODEGADES FROM ITRA WHERE CNSITRA = @CNSITRA
		IF EXISTS (
			SELECT 1 
			FROM IBOD INNER JOIN ITBOD ON IBOD.IDTBODEGA = ITBOD.IDTBODEGA 
			WHERE IDBODEGA = @IDBODEGA
			AND COALESCE(VERIFDOC, 'NO') <> 'Si'
		)
		BEGIN
			SELECT 'OK' OK, TIPODOC = 'NO'
				,IIF(COALESCE(FCOM.N_FACTURA,'') = '', 'ESREMISION', 'ESFACTURA')[ESFACT] 
			FROM ITRA LEFT JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM 
			WHERE  ITRA.CNSITRA = @CNSITRA 
			RETURN


		END

		BEGIN TRY 
			IF EXISTS (SELECT 1 FROM  ITRA 
					INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
					INNER JOIN VERIF ON FCOM.CNSFCOM = VERIF.REFERENCIA1
				WHERE ITRA.CNSITRA = @CNSITRA)
				BEGIN
					SELECT 'OK' OK, 'SI' TIPODOC, 'YA TIENE' ESFACT
				END
			ELSE 
				BEGIN
					SELECT 'OK' OK, 'NO' TIPODOC, CASE WHEN COALESCE(FCOM.N_FACTURA,'') = '' THEN 'ESREMISION' ELSE 'ESFACTURA' END [ESFACT] 
					FROM ITRA LEFT JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM WHERE  ITRA.CNSITRA = @CNSITRA 
					RETURN
				END

				SELECT @CNSFCOM =  FCOM.CNSFCOM FROM  ITRA 
					INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
				WHERE ITRA.CNSITRA = @CNSITRA


				SELECT 'OK' OK,
					DATOS = (SELECT COALESCE(TGEN.DESCRIPCION,'')DESCRIPCION, VERIF.CNSVERIF
					,VERIF.TIPO
					,VERIF.REFERENCIA1, VERIF.REFERENCIA2, CAST(VERIF.CUMPLE AS BIT) CUMPLE, VERIF.OBS
				FROM ITRA 
					INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
					INNER JOIN VERIF ON FCOM.CNSFCOM = VERIF.REFERENCIA1
					LEFT JOIN TGEN ON VERIF.REFERENCIA2 = TGEN.CODIGO AND TGEN.TABLA = 'VERIFICA' AND CAMPO = 'COMPRAS'
				WHERE ITRA.CNSFCOM = @CNSFCOM AND ITRA.CNSITRA = @CNSITRA
				FOR JSON PATH)

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'PROCESAR_VERIFICACION'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @COMPLETA = COMPLETA
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)			'$.CNSITRA'
		,COMPLETA			BIT					'$.COMPLETA'
		)
		BEGIN TRY 
			SELECT @CNSFCOM =  FCOM.CNSFCOM FROM  ITRA 
				INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
			WHERE ITRA.CNSITRA = @CNSITRA

			IF (SELECT @COMPLETA) = 0
			BEGIN 
				INSERT INTO VERIF (FECHA, TIPO, REFERENCIA1, REFERENCIA2, CUMPLE, OBS)
				SELECT DBO.FNK_FECHA_SIN_MLS(GETDATE()), 'COMPRAS', @CNSFCOM, TGEN.CODIGO, 0, ''
				FROM TGEN WHERE TGEN.CAMPO = 'COMPRAS' AND TGEN.TABLA = 'VERIFICA'
			END
			IF (SELECT @COMPLETA) = 1
			BEGIN 
				INSERT INTO VERIF (FECHA, TIPO, REFERENCIA1, REFERENCIA2, CUMPLE, OBS)
				SELECT DBO.FNK_FECHA_SIN_MLS(GETDATE()), 'COMPRAS', @CNSFCOM, 'REMI', 1, 'Orden de Compra Con Remisi�n'
			END

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK, @CNSITRA CNSITRA
		RETURN
	END
	IF @METODO = 'GUARDAR'
	BEGIN
		SELECT @DATOS =  DATOS
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
					DATOS			NVARCHAR(MAX) AS JSON
					)

		SELECT  * INTO #DATOS FROM OPENJSON (@DATOS) 
		WITH(
			 CNSVERIF	INT					'$.CNSVERIF'
			 ,CUMPLE	BIT					'$.CUMPLE'
			 ,OBS		VARCHAR(500)		'$.OBS'
		)  
		
		BEGIN TRY 
			UPDATE VERIF SET VERIF.CUMPLE = #DATOS.CUMPLE, VERIF.OBS = #DATOS.OBS FROM VERIF,#DATOS WHERE VERIF.CNSVERIF = #DATOS.CNSVERIF
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'DISTRIBUIR_MASIVO' --MLOTEO
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)			'$.CNSITRA'
		,IDBODEGA			VARCHAR(20)			'$.IDBODEGA'
		)
		SELECT @CNSFCOM =  FCOM.CNSFCOM FROM  ITRA 
				INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
			WHERE ITRA.CNSITRA = @CNSITRA
		
		IF NOT EXISTS( SELECT 1 FROM ITRAH WHERE CNSITRA = @CNSITRA AND COALESCE(ITRAH.INICIAL,0)=0 )
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No cuenta con registros para Lotear.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF EXISTS(SELECT  FCOM.CNSFCOM FROM  ITRA 
				INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
			WHERE ITRA.CNSITRA = @CNSITRA AND COALESCE(FCOM.CNSFCOM ,'') = '')
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No existe CNSFCOM'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF (SELECT COALESCE(VERIFDOC,'') FROM IBOD INNER JOIN ITBOD ON IBOD.IDTBODEGA=ITBOD.IDTBODEGA 
			 WHERE IBOD.IDBODEGA=@IDBODEGA) = 'Si' 
			 AND (SELECT COUNT(*) FROM VERIF WHERE TIPO='COMPRAS' AND REFERENCIA1 = @CNSFCOM) <= 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se Ha Diligenciado el Formato de Verificaci�n de Factura, Se debe Realizar la Verificaci�n Para Continuar.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF (SELECT COALESCE(VERIFDOC,'') FROM IBOD INNER JOIN ITBOD ON IBOD.IDTBODEGA=ITBOD.IDTBODEGA 
			 WHERE IBOD.IDBODEGA=@IDBODEGA) = 'Si' 
			 AND (SELECT COUNT(*) FROM VERIF WHERE TIPO='COMPRAS' AND REFERENCIA1 = @CNSFCOM AND CUMPLE = 0 ) > 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Existen Requisitos De la Verificaci�n de Factura Que no se Cumple... No se puede Continuar.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		
		BEGIN TRY 
			PRINT '**********************************'
			
			SELECT @CNSRPDX = NULL
			--EXEC SPK_GENCONSECUTIVO '01',@IDSEDE,'@RPDX',@CNSRPDX OUTPUT
			--SELECT @CNSRPDX = @IDSEDE + REPLACE(SPACE(8 - LEN(@CNSRPDX))+LTRIM(RTRIM(@CNSRPDX)),SPACE(1),0)
			EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE,@PREFIJO='@RPDX', @LONGITUD = 8, @NVOCONSEC=@CNSRPDX OUTPUT  


			SELECT @CNSRPDX_2 = NULL
			--EXEC SPK_GENCONSECUTIVO '01',@IDSEDE,'@RPDX',@CNSRPDX_2 OUTPUT
			--SELECT @CNSRPDX_2 = @IDSEDE + REPLACE(SPACE(8 - LEN(@CNSRPDX_2))+LTRIM(RTRIM(@CNSRPDX_2)),SPACE(1),0)
			EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE,@PREFIJO='@RPDX', @LONGITUD = 8, @NVOCONSEC=@CNSRPDX_2 OUTPUT  
			--PCSINIVA,PCOSTO,IVA
			DELETE FROM RPDX WHERE CNS = @CNSRPDX
			INSERT INTO RPDX (CNS,ID1,ID2,VALOR1,VALOR2,STRINGMEDIO1,ID3,STRINGGRANDE1,CANTIDAD,ID4,CANTIDAD1,CANTIDAD2
				,STRINGGRANDE2 -- ESTANTE
				)
			 SELECT @CNSRPDX,CNSITRA,IART.IDITAR,COALESCE(IVA,0) IVA,COALESCE(PCSINIVA,0) PCSINIVA,ITAR.DESCRIPCION,ITRAH.IDARTICULO,IART.DESCRIPCION,ITRAH.CANTIDADORI,IART.IDSERVICIO,CASE WHEN COALESCE(INICIAL,0)=0 THEN 0 ELSE ITRAH.CANTIDADDES END 
			,CASE WHEN COALESCE(INICIAL,0)=0 THEN ITRAH.CANTIDADORI ELSE (ITRAH.CANTIDADORI-ITRAH.CANTIDADDES) END
			,ESTANTE = (
				SELECT TOP 1 IARTE.ESTANTE
					,IDESTANTE = E.CODIGO
					,DESCESTANTE = E.DESCRIPCION
					,IDGRUPOEST = G.CODIGO
					,DESCGRUPOEST = G.DESCRIPCION
				FROM [dbo].[IARTE]
				INNER JOIN IART ON IARTE.IDARTICULO = IART.IDARTICULO
				INNER JOIN TGEN AS E ON E.CAMPO = 'ESTANTE' AND E.TABLA = IARTE.IDBODEGA AND CODIGO = IARTE.ESTANTE
				INNER JOIN TGEN AS G ON G.CAMPO = 'ESTANTE_P' AND E.TABLA = IARTE.IDBODEGA AND G.CODIGO = E.DATO1
				WHERE IARTE.IDBODEGA = @IDBODEGA
				AND IARTE.IDARTICULO = ITRAH.IDARTICULO
				ORDER BY E.DESCRIPCION
				FOR JSON PATH
			)
			 FROM ITRAH INNER JOIN IART ON ITRAH.IDARTICULO=IART.IDARTICULO 
						INNER JOIN ITAR ON IART.IDITAR=ITAR.IDITAR
			 WHERE ITRAH.CNSITRA= @CNSITRA
			 AND COALESCE(ITRAH.INICIAL,0)=0


		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK, @CNSRPDX CNSRPDX, @CNSRPDX_2 CNSRPDX_2

		RETURN
	END
	IF @METODO = 'SEL_RPDX'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSRPDX = CNSRPDX
		FROM OPENJSON (@PARAMETROS)
		WITH	(
			 CNSITRA	VARCHAR(20)		'$.CNSITRA'
			,IDBODEGA	VARCHAR(20)		'$.IDBODEGA'
			,CNSRPDX	VARCHAR(20)		'$.CNSRPDX'
		)
		--IDARTICULOORI
		SELECT @CNSFCOM =  FCOM.CNSFCOM 
		FROM  ITRA INNER JOIN FCOM ON ITRA.CNSFCOM = FCOM.CNSFCOM
		WHERE ITRA.CNSITRA = @CNSITRA
		
		SELECT 'OK' AS OK
--QUERY 3
--QUERY 3
		IF @IDBODEGA = DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')  
		BEGIN
			SELECT CNS, ITEM, ID1, ID2, ID3, ID4, CANTIDAD, CANTIDAD1, CANTIDAD2, STRINGMEDIO1, STRINGGRANDE1, FECHAREGISTRO 
				,IART.CODCUM,IART.REGINVIMA,IART.F_VIGENCIAINV,IART.CODBARRA,  COALESCE(RPDX.VALOR1,0)VALOR1 , COALESCE(RPDX.VALOR2,0) VALOR2 
				,ITRAH.PCOSTO, COALESCE(ITAR.MLOTEO,0) MLOTEO
			FROM RPDX 
				INNER JOIN IART ON RPDX.ID3 = IART.IDARTICULO
				INNER JOIN ITAR ON IART.IDITAR = ITAR.IDITAR 
				INNER JOIN ITRAH ON RPDX.ID1 = ITRAH.CNSITRA AND RPDX.ID3 = ITRAH.IDARTICULO AND RPDX.ID4 = IART.IDSERVICIO --AND ITRAH.INICIAL = 1
			WHERE CNS = @CNSRPDX
			ORDER BY  ITEM  ASC

		END
		ELSE
		BEGIN
			
			SELECT CNS, ITEM, ID1, ID2, ID3, ID4, CANTIDAD, CANTIDAD1, CANTIDAD2, STRINGMEDIO1, STRINGGRANDE1, FECHAREGISTRO 
				,IART.CODCUM,IART.REGINVIMA,IART.F_VIGENCIAINV,IART.CODBARRA,  COALESCE(RPDX.VALOR1,0)VALOR1 , COALESCE(RPDX.VALOR2,0) VALOR2 
				,ITRAH.PCOSTO, MLOTEO = COALESCE(ITAR.MLOTEO,0) 
				,ESTANTE = STRINGGRANDE2
			FROM RPDX 
				INNER JOIN IART ON RPDX.ID3 = IART.IDARTICULO
				INNER JOIN ITAR ON IART.IDITAR = ITAR.IDITAR 
				INNER JOIN ITRAH ON RPDX.ID1 = ITRAH.CNSITRA AND RPDX.ID3 = ITRAH.IDARTICULO AND RPDX.ID4 = IART.IDSERVICIO --AND ITRAH.INICIAL = 1
			WHERE CNS = @CNSRPDX
			GROUP BY CNS, ITEM, ID1, ID2, ID3, ID4, CANTIDAD, CANTIDAD1, CANTIDAD2, STRINGMEDIO1, STRINGGRANDE1, FECHAREGISTRO 
				,IART.CODCUM,IART.REGINVIMA,IART.F_VIGENCIAINV,IART.CODBARRA,  VALOR1 ,  VALOR2 
				,ITRAH.PCOSTO, COALESCE(ITAR.MLOTEO,0), STRINGGRANDE2  
			ORDER BY  ITEM  ASC

		END
		
		RETURN
	END
	IF @METODO = 'SEL_IART'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSRPDX = CNSRPDX, @ITEM = ITEM
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)					'$.CNSITRA'
		,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
		,CNSRPDX			VARCHAR(20)					'$.CNSRPDX'
		,ITEM				INT							'$.ITEM'
		)
			
		BEGIN TRY 
			SELECT 'OK' AS OK
			SELECT @IDARTICULO = ID3, @IDARTICULO_REAL = ID3 FROM RPDX WHERE ITEM = @ITEM
			IF @IDBODEGA = DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')  
			BEGIN
				SELECT IART.IDARTICULO, IART.DESCRIPCION, IART.REGINVIMA, IART.F_VIGENCIAINV,DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'HEMO') PRIORIDAD , IART.CODCUM, IART.IDALTERNA , IART.IDSERVICIO, COALESCE(IART.PRINCIPAL,0) PRINCIPAL
					,IART.CODBARRA, IART.IDITAR, ITAR.MFECHAVENCIMIENTO, COALESCE(ITAR.MPRINCIPAL,0) MPRINCIPAL
				FROM IART 
					LEFT JOIN ITAR ON IART.IDITAR = ITAR.IDITAR
				WHERE IART.IDARTICULO = @IDARTICULO		
				ORDER BY  COALESCE(PRINCIPAL,0) DESC ,IART.F_VIGENCIAINV  ASC
			END
			ELSE
			BEGIN

				IF NOT EXISTS(SELECT 1 FROM IART WHERE IDSERVICIO = @IDARTICULO AND PRINCIPAL=1) -- EZ PERU COMPRA FABRICANTES EN LUGAR DE PRINCIPAL
				BEGIN
					SELECT @IDARTICULO  = IDSERVICIO FROM IART WHERE IDARTICULO = @IDARTICULO
				END
				IF DBO.FNK_VALORVARIABLE('DEINVNODESER') = @IDARTICULO
				BEGIN
					SELECT IART.IDARTICULO	,IART.DESCRIPCION	,IART.REGINVIMA
						,IART.F_VIGENCIAINV	
						,PRIORIDAD = CASE COALESCE(IART.PRINCIPAL, 0) 
							WHEN 0 THEN DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'')
							ELSE NULL END 
						,PRIORIDAD_DESC = CASE WHEN COALESCE(IART.PRINCIPAL, 0) = 0 AND DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'') = 1 THEN 'INVIMA vencido' 
							WHEN COALESCE(IART.PRINCIPAL, 0) = 0 AND DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'') = 2 THEN 'INVIMA Vigente'
							WHEN COALESCE(IART.PRINCIPAL, 0) = 0 AND DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'') = 3 THEN 'INVIMA por Vencer'
							ELSE NULL END
						,IART.CODCUM	,IART.IDALTERNA			,IART.IDSERVICIO	
						,COALESCE(IART.PRINCIPAL, 0) PRINCIPAL	,IART.CODBARRA
						,IART.IDITAR	,ITAR.MFECHAVENCIMIENTO ,COALESCE(ITAR.MPRINCIPAL, 0) MPRINCIPAL
					
					FROM IART
					LEFT JOIN ITAR ON IART.IDITAR = ITAR.IDITAR
					WHERE IART.IDARTICULO = @IDARTICULO_REAL
					--AND (COALESCE(ITAR.MPRINCIPAL, 0) = 0 OR (COALESCE(ITAR.MPRINCIPAL, 0) = 1 AND COALESCE(IART.PRINCIPAL, 0)=0))
					ORDER BY COALESCE(PRINCIPAL, 0) DESC, IART.F_VIGENCIAINV ASC
				END
				IF DBO.FNK_VALORVARIABLE('DEINVNODESER') <> @IDARTICULO
				BEGIN
					SELECT IART.IDARTICULO	,IART.DESCRIPCION	,IART.REGINVIMA
						,IART.F_VIGENCIAINV	
						,PRIORIDAD = CASE COALESCE(IART.PRINCIPAL, 0) 
							WHEN 0 THEN DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'')
							ELSE NULL END 
						,PRIORIDAD_DESC = CASE WHEN COALESCE(IART.PRINCIPAL, 0) = 0 AND DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'') = 1 THEN 'INVIMA vencido' 
							WHEN COALESCE(IART.PRINCIPAL, 0) = 0 AND DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'') = 2 THEN 'INVIMA Vigente'
							WHEN COALESCE(IART.PRINCIPAL, 0) = 0 AND DBO.FNK_SEMAFORO_TRANSITO(IART.F_VIGENCIAINV,'') = 3 THEN 'INVIMA por Vencer'
							ELSE NULL END
						,IART.CODCUM	,IART.IDALTERNA			,IART.IDSERVICIO	
						,COALESCE(IART.PRINCIPAL, 0) PRINCIPAL	,IART.CODBARRA
						,IART.IDITAR	,ITAR.MFECHAVENCIMIENTO ,COALESCE(ITAR.MPRINCIPAL, 0) MPRINCIPAL
					FROM IART
					LEFT JOIN ITAR ON IART.IDITAR = ITAR.IDITAR
					WHERE IART.IDSERVICIO = @IDARTICULO
					--AND (COALESCE(ITAR.MPRINCIPAL, 0) = 0 OR (COALESCE(ITAR.MPRINCIPAL, 0) = 1 AND COALESCE(IART.PRINCIPAL, 0)=0))
					ORDER BY COALESCE(PRINCIPAL, 0) DESC, IART.F_VIGENCIAINV ASC
				END
				
			END
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'AGREGAR_IART'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSRPDX = CNSRPDX, @CNSRPDX_2 = CNSRPDX_2, @ITEM = ITEM, @IDARTICULO = IDARTICULO, @NOLOTE = NOLOTE, @CANTIDAD = CANTIDAD
		,@FECHAVENCE = FECHAVENCE, @PC_SINIVA = PC_SINIVA, @TEMPERATURA = TEMPERATURA, @CANTIDADREV = CANTIDADREV
		,@PIVA = PIVA	, @CUMPLE = CUMPLE , @APROBADO = APROBADO, @VALIDA_STOCKS = VALIDA_STOCKS
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
					CNSITRA				VARCHAR(20)					'$.CNSITRA'
					,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
					,CNSRPDX			VARCHAR(20)					'$.CNSRPDX'
					,CNSRPDX_2			VARCHAR(20)					'$.CNSRPDX_2'
					,ITEM				INT							'$.ITEM'
					,IDARTICULO			VARCHAR(20)					'$.IDARTICULO'
					,NOLOTE				VARCHAR(20)					'$.NOLOTE'
					,CANTIDAD			INT							'$.CANTIDAD'
					,FECHAVENCE			DATE						'$.FECHAVENCE'
					,PC_SINIVA			DECIMAL(14,2)				'$.PC_SINIVA'
					,TEMPERATURA		DECIMAL(14,2)				'$.TEMPERATURA'
					,CANTIDADREV		DECIMAL(14,2)				'$.CANTIDADREV'
					,PIVA				DECIMAL(14,2)				'$.PIVA'
					,CUMPLE				BIT							'$.CUMPLE'
					,APROBADO			BIT							'$.APROBADO'
					,VALIDA_STOCKS		VARCHAR(200)				'$.VALIDA_STOCKS'
					)
		SELECT @REGINVIMA = REGINVIMA, @F_VIGENCIAINV = F_VIGENCIAINV, @IDITAR = IDITAR FROM IART WHERE IDARTICULO = @IDARTICULO
		IF @IDBODEGA <> (SELECT DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')) AND COALESCE(@NOLOTE,'') = ''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Debe de ingresar un NOLOTE.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		IF (SELECT ID2 FROM RPDX WHERE RPDX.CNS = @CNSRPDX AND RPDX.ITEM = @ITEM ) = (SELECT DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')) 
		BEGIN
			IF COALESCE(@TEMPERATURA,0) = 0
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'Ingrese Temperatura.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
		END
	
		IF (SELECT ID2 FROM RPDX WHERE RPDX.CNS = @CNSRPDX AND RPDX.ITEM = @ITEM ) <> (SELECT DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')) 
		BEGIN
			IF @FECHAVENCE < ( GETDATE() +  COALESCE(DBO.FNK_VALORVARIABLE ('IDINVDIASPARAVENCER'),0) )
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'Producto Vencido no se puede Ingresar a la Bodega.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
			IF @FECHAVENCE < ( GETDATE() +  COALESCE(DBO.FNK_VALORVARIABLE ('NDIASANTESVENCE'),0) ) AND (SELECT ID2 FROM RPDX WHERE RPDX.CNS = @CNSRPDX AND RPDX.ITEM = @ITEM ) <> (SELECT DBO.FNK_VALORVARIABLE('IDITARHEMODERIVADOS')) 
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'El Nro de D�as Faltantes Por Vencer Es Menor Al Configurado.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
		END
		IF @FECHAVENCE < CONVERT(DATE, GETDATE())
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Producto Vencido no se puede Ingresar a la Bodega.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		-- VALID_INVIMA_HEMO (USVGS): SI o vac�o = valida vigencia INVIMA al lotear; NO = omite en bodega/tipo hemoderivados
		IF (SELECT MFECHAVENCIMIENTO FROM ITAR WHERE IDITAR = @IDITAR) = 1
			AND EXISTS (SELECT 1 FROM IART WHERE IDARTICULO = @IDARTICULO AND COALESCE(PRINCIPAL, 0) = 0)
			AND NOT (
				UPPER(LTRIM(RTRIM(COALESCE(DBO.FNK_VALORVARIABLE('VALID_INVIMA_HEMO'), 'SI')))) = 'NO'
				AND (
					@IDBODEGA = DBO.FNK_VALORVARIABLE('IDBOD_HEMODERIVADOS')
					OR @IDITAR = DBO.FNK_VALORVARIABLE('IDITARHEMODERIVADOS')
				)
			)
		BEGIN
			IF @REGINVIMA = '' OR @F_VIGENCIAINV ='' OR @F_VIGENCIAINV < (CONVERT(DATE,GETDATE()))
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'Debe Actualizar el Registro Invima antes de Continuar.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
		END

		WHILE COALESCE(@CODIGOBARRA,'') = ''
		BEGIN
			SELECT @CODIGOBARRA = NULL
			EXEC SPK_GENCONSECUTIVO @COMPANIA,@IDSEDE,'@ICBU',@CODIGOBARRA OUTPUT
			SELECT @CODIGOBARRA = @IDSEDE + 'L' + REPLACE(SPACE(8 - LEN(@CODIGOBARRA))+LTRIM(RTRIM(@CODIGOBARRA)),SPACE(1),0)
			SELECT @CODIGOBARRA = COALESCE(@CODIGOBARRA,'')
		END

		IF @CANTIDAD > (SELECT CANTIDAD2 FROM RPDX WHERE RPDX.CNS = @CNSRPDX AND RPDX.ITEM = @ITEM )
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se puede ingresar m�s de lo que est� pedido.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			SELECT 'OK' AS OK

			IF @PC_SINIVA>0
			BEGIN
				IF @PIVA>0
					SELECT @PCOSTO = @PC_SINIVA + ((@PC_SINIVA*@PIVA )/ 100)
				ELSE
					SELECT @PCOSTO = @PC_SINIVA 
			END
			ELSE
			BEGIN
				--SELECT @PCOSTO = 0
				SELECT TOP 1 @PCOSTO = ITRAH.PCOSTO
				FROM RPDX 
					INNER JOIN IART ON RPDX.ID3 = IART.IDARTICULO
					INNER JOIN ITRAH ON RPDX.ID1 = ITRAH.CNSITRA AND RPDX.ID3 = ITRAH.IDARTICULO AND RPDX.ID4 = ITRAH.IDARTICULO
				WHERE CNS = @CNSRPDX
			END

			INSERT INTO RPDX  (CNS, ID1, ID2,ID3,ID4,CANTIDAD,VALOR1, FECHA1, ID5, VALOR27,ID10  , ID11, ID12, ID13, ID14, ID15, ID16, ID17
			, FECHA2, ID9, VALOR5, VALOR11, CANTIDAD3, CANTIDAD4, CANTIDAD5, ID18,CANTIDAD1, CANTIDAD2, STRINGMEDIO1, STRINGGRANDE1, STRINGMEDIO3, ID19   )
			SELECT @CNSRPDX_2, R.ID1, @IDARTICULO, @CODIGOBARRA, @NOLOTE, @CANTIDAD, @PCOSTO, @FECHAVENCE,  '', @TEMPERATURA, R.ID4, R.ID3
			, '', '', '', '', '','', '', @REGINVIMA, 0, R.ITEM, @CANTIDADREV,@CUMPLE, @APROBADO, '',  0, 0, '', ''
			, JSON_VALUE(@PARAMETROS,'$.OBSERVACION'), JSON_VALUE(@PARAMETROS, '$.ESTANTE')
			FROM RPDX R WHERE R.CNS = @CNSRPDX AND R.ITEM = @ITEM

			SELECT CNS, ITEM, ID1, ID2, ID3, ID4, CANTIDAD, CANTIDAD1, CANTIDAD2
			, STRINGMEDIO1, STRINGGRANDE1, FECHAREGISTRO,ID9, ID10, ID11, ID15, VALOR1, VALOR11, FECHA1,VALOR27, CANTIDAD3, CANTIDAD4, CANTIDAD5 
			FROM RPDX WHERE RPDX.CNS = @CNSRPDX_2

			SELECT @CANTIDAD_TOTAL = (SELECT SUM(CANTIDAD) FROM RPDX R WHERE  R.CNS = @CNSRPDX_2 AND R.ID11 = (SELECT RPDX.ID3 FROM RPDX WHERE  RPDX.ITEM = @ITEM AND RPDX.CNS = @CNSRPDX) )
			UPDATE RPDX SET CANTIDAD1 = @CANTIDAD_TOTAL, CANTIDAD2 = (RPDX.CANTIDAD-@CANTIDAD_TOTAL) WHERE RPDX.ITEM = @ITEM


			IF EXISTS(SELECT 1 FROM RPDX WHERE RPDX.ITEM = @ITEM AND CANTIDAD = CANTIDAD1)
			BEGIN
				SELECT 'OK' OK, 'LLENO' ESTADO
			END
			ELSE
			BEGIN
				SELECT 'OK' OK, 'PENDIENTE' ESTADO
			END

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'GUARDA_CUM'
	BEGIN
		SELECT @IDARTICULO = IDARTICULO, @CODCUM = CODCUM
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		IDARTICULO				VARCHAR(20)					'$.IDARTICULO'
		,CODCUM					VARCHAR(20)					'$.CODCUM'
		)
			
		BEGIN TRY 
			UPDATE IART SET CODCUM = @CODCUM WHERE IDARTICULO = @IDARTICULO
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'ON_CERRAR'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @CNSRPDX = CNSRPDX, @IDBODEGA = IDBODEGA, @CNSRPDX_2 = CNSRPDX_2
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA						VARCHAR(20)					'$.CNSITRA'
		,CNSRPDX					VARCHAR(20)					'$.CNSRPDX'
		,CNSRPDX_2					VARCHAR(20)					'$.CNSRPDX_2'
		,IDBODEGA					VARCHAR(20)					'$.IDBODEGA'
		)
			
		BEGIN TRY 
			DELETE FROM RPDX WHERE RPDX.CNS = @CNSRPDX
			DELETE FROM RPDX WHERE RPDX.CNS = @CNSRPDX_2
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'ON_ELIMINAR'
	BEGIN
		SELECT @ITEM = ITEM, @CNSRPDX_2 = CNSRPDX_2
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		ITEM			INT					'$.ITEM'
		,CNSRPDX_2		VARCHAR(20)			'$.CNSRPDX_2'
		)
			
		BEGIN TRY 
			SELECT @ITEM_2 = VALOR11 FROM RPDX WHERE  ITEM = @ITEM
			SELECT @CNSRPDX = CNS, @CNSITRA = ID1 FROM RPDX WHERE ITEM = @ITEM_2
			DELETE FROM RPDX WHERE RPDX.ITEM = @ITEM

			SELECT @CANTIDAD_TOTAL = (SELECT SUM(CANTIDAD) FROM RPDX R WHERE  R.CNS = @CNSRPDX_2 AND R.ID11 = (SELECT RPDX.ID3 FROM RPDX WHERE  RPDX.ITEM = @ITEM_2 AND RPDX.CNS = @CNSRPDX) )
			--SELECT @CANTIDAD_TOTAL
			UPDATE RPDX SET CANTIDAD1 = @CANTIDAD_TOTAL, CANTIDAD2 = (RPDX.CANTIDAD-COALESCE(@CANTIDAD_TOTAL,0)) WHERE RPDX.ITEM = @ITEM_2

			SELECT 'OK' AS OK

			SELECT CNS, ITEM, ID1, ID2, ID3, ID4, CANTIDAD, CANTIDAD1, CANTIDAD2
			, STRINGMEDIO1, STRINGGRANDE1, FECHAREGISTRO,ID9, ID10, ID11, ID15, VALOR1, VALOR11, FECHA1,VALOR27, CANTIDAD3, CANTIDAD4, CANTIDAD5 
			FROM RPDX WHERE RPDX.CNS = @CNSRPDX_2
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'ON_PROCESAR'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSRPDX = CNSRPDX, @CNSRPDX_2 = CNSRPDX_2
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
			CNSITRA				VARCHAR(20)					'$.CNSITRA'
			,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
			,CNSRPDX			VARCHAR(20)					'$.CNSRPDX'
			,CNSRPDX_2			VARCHAR(20)					'$.CNSRPDX_2'
			)
			
		BEGIN TRY 
			UPDATE ITRAH SET NOLOTEPEDIDO = ''   WHERE COALESCE(ITRAH.NOLOTEPEDIDO,'') = '0' AND ITRAH.CNSITRA = @CNSITRA
			EXEC SPK_INSERT_ITRAH @CNSRPDX_2
			DELETE FROM RPDX WHERE RPDX.CNS = @CNSRPDX
			DELETE FROM RPDX WHERE RPDX.CNS = @CNSRPDX_2
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'VALIDAR_PROCESO'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @CNSFCOM = CNSFCOM, @IDBODEGA = IDBODEGA
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
			CNSITRA				VARCHAR(20)					'$.CNSITRA'
			,CNSFCOM			VARCHAR(20)					'$.CNSFCOM'
			,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
			)
		IF EXISTS (SELECT * FROM ITRA WHERE ( IDTIPOMOV = DBO.FNK_VALORVARIABLE('IDINVMOV_COMPRAS') OR IDTIPOMOV = DBO.FNK_VALORVARIABLE('IDINVMOV_COMPRAS')) AND CNSITRA = @CNSITRA )
		BEGIN
			IF (SELECT COALESCE(VERIFDOC,'')  FROM IBOD INNER JOIN ITBOD ON IBOD.IDTBODEGA=ITBOD.IDTBODEGA WHERE IBOD.IDBODEGA = @IDBODEGA ) = 'Si'
			BEGIN
				IF (SELECT COUNT(*) FROM VERIF WHERE TIPO='COMPRAS' AND REFERENCIA1 = @CNSFCOM ) <= 0
				BEGIN
					INSERT INTO @TBLERRORES(ERROR) SELECT 'No se Ha Diligenciado el Formato de Verificaci�n de Factura, Se debe Realizar la Verificaci�n Para Continuar.'
					SELECT 'KO' OK
					SELECT ERROR FROM @TBLERRORES
					RETURN
				END	
				ELSE
				BEGIN
					IF (SELECT COUNT(*) FROM VERIF WHERE TIPO='COMPRAS' AND REFERENCIA1=@CNSFCOM AND CUMPLE=0 ) > 0
					BEGIN
						INSERT INTO @TBLERRORES(ERROR) SELECT 'Existen Requisitos De la Verificaci�n de Factura Que no se Cumple... No se puede Continuar.'
						SELECT 'KO' OK
						SELECT ERROR FROM @TBLERRORES
						RETURN
					END	
				END	
			END	
		END	
		IF (SELECT COUNT(*) FROM IMOV WHERE IMOV.CNSITRA = @CNSITRA AND IMOV.ESTADO = 0) <> 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Este Transito ya Fue Traido en otra Estaci�n y esta en proceso de Entrada No se puede Continuar.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END	
		IF EXISTS (SELECT 1 FROM IART INNER JOIN ITAR ON IART.IDITAR = ITAR.IDITAR WHERE IART.IDARTICULO IN (SELECT ITRAH.IDARTICULO FROM ITRAH WHERE  ITRAH.CNSITRA = @CNSITRA AND COALESCE(INICIAL,0)=1 ) AND COALESCE(ITAR.MLOTEO,0) = 1  )
		BEGIN
			IF (SELECT COUNT(*) FROM ITRAH WHERE ITRAH.CNSITRA = @CNSITRA AND COALESCE(INICIAL,0)=1 ) = 0
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) SELECT 'No Se Ha Realizado La Distribuci�n de Lotes, Necesarias Para El Ingreso.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END	
		END

		-- Solo lectura: pendiente en l�neas base tras ON_PROCESAR (CANTIDADORI ya descontado)
		IF EXISTS (
			SELECT 1
			FROM ITRAH B
			WHERE B.CNSITRA = @CNSITRA
			  AND COALESCE(B.INICIAL, 0) = 0
			  AND COALESCE(B.CANTIDADORI, 0) > 0
		)
			SELECT 'OK'OK, 'SI' VENTANA
		ELSE
			SELECT 'OK'OK, 'NO' VENTANA

		RETURN
	END
	IF @METODO = 'ON_ACEPTA_TRANSITO'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @CNSFCOM = CNSFCOM, @IDBODEGA = IDBODEGA
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
			CNSITRA				VARCHAR(20)					'$.CNSITRA'
			,CNSFCOM			VARCHAR(20)					'$.CNSFCOM'
			,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
			)
		
		-- Validaci�n de causas: l�neas base INICIAL=0 con pendiente > 0 sin IDCAUSAL (tras ON_PROCESAR)
		DECLARE @HAY_PENDIENTE_SIN_CAUSA BIT = 0

		IF EXISTS (
			SELECT 1
			FROM ITRAH B
			WHERE B.CNSITRA = @CNSITRA
			  AND COALESCE(B.INICIAL, 0) = 0
			  AND COALESCE(B.IDCAUSAL, '') = ''
			  AND COALESCE(B.CANTIDADORI, 0) > 0
		)
			SET @HAY_PENDIENTE_SIN_CAUSA = 1

		IF @HAY_PENDIENTE_SIN_CAUSA = 1
		BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'Existen art�culos pendientes por no loteo sin causa asignada. Registre la causa (individual o masiva) antes de aceptar el tr�nsito.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		-- Compras: exige al menos una l�nea lotada (ITRAH INICIAL=1) para generar entrada con detalle
		IF EXISTS (
			SELECT 1
			FROM ITRA
			WHERE CNSITRA = @CNSITRA
			  AND (
				COALESCE(CNSFCOM, '') <> ''
				OR IDTIPOMOV = DBO.FNK_VALORVARIABLE('IDINVMOV_COMPRAS')
			  )
		)
		AND NOT EXISTS (
			SELECT 1
			FROM ITRAH
			WHERE CNSITRA = @CNSITRA
			  AND COALESCE(INICIAL, 0) = 1
			  AND COALESCE(CANTIDADORI, 0) > 0
			  AND COALESCE(NOLOTE, '') NOT IN ('', '0')
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'No se ha realizado la distribuci�n de lotes. Debe lotear al menos un art�culo antes de aceptar el tr�nsito de compras.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY 
			SELECT @IDTIPOMOV = IDTIPOMOV FROM ITRA WHERE CNSITRA = @CNSITRA
			IF (SELECT DBO.FNK_VALORVARIABLE('IDTS') ) = @IDTIPOMOV
				SELECT @IDTIPOMOV = (SELECT DBO.FNK_VALORVARIABLE('IDTE') )

			 IF NOT EXISTS (SELECT 1 FROM ITMO WHERE IDTIPOMOV = @IDTIPOMOV)
			BEGIN
				INSERT INTO @TBLERRORES(ERROR) 
				SELECT 'El tipo de movimiento (IDTIPOMOV: ' + ISNULL(@IDTIPOMOV, 'NULL') + ') no existe en la tabla ITMO. Por favor, verifique la configuraci�n de tipos de movimientos.'
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END

			PRINT 'ENTRA A SPK_INSERTENTTRANSITO'
			EXEC SPK_INSERTENTTRANSITO @CNSITRA, @USUARIO,@IDBODEGA,@IDTIPOMOV,@SYS_COMPUTERNAME,@COMPANIA,@SEDE

		
			UPDATE ITRA
			   SET ESTADO = 1
			 WHERE CNSITRA = @CNSITRA
			   AND COALESCE(ESTADO,0) = 0

		END TRY
		BEGIN CATCH
			IF XACT_STATE() = -1
				ROLLBACK TRANSACTION;
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'GUARDA_CAUSA'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDARTICULO = IDARTICULO, @NOLOTE = NOLOTE, @IDCAUSA = IDCAUSA
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
			CNSITRA				VARCHAR(20)					'$.CNSITRA'
			,IDARTICULO			VARCHAR(20)					'$.IDARTICULO'
			,NOLOTE			VARCHAR(20)					'$.NOLOTE'
			,IDCAUSA			VARCHAR(20)					'$.IDCAUSA'
			)
	
		BEGIN TRY 
			UPDATE ITRAH SET IDCAUSAL = @IDCAUSA
			   WHERE ITRAH.CNSITRA    = @CNSITRA
			     AND COALESCE(ITRAH.IDARTICULOORI, ITRAH.IDARTICULO) = @IDARTICULO
			     AND COALESCE(ITRAH.NOLOTE, '') = COALESCE(@NOLOTE, '')
			     AND COALESCE(ITRAH.INICIAL, 0) = 0
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'ON_CAUSA'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @CNSFCOM = CNSFCOM, @IDBODEGA = IDBODEGA, @IDCAUSA = IDCAUSA
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
			CNSITRA				VARCHAR(20)					'$.CNSITRA'
			,CNSFCOM			VARCHAR(20)					'$.CNSFCOM'
			,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
			,IDCAUSA			VARCHAR(20)					'$.IDCAUSA'
			)
	
		BEGIN TRY 
			DECLARE @DBG_CAUSA_TOTAL_BASE INT
			DECLARE @DBG_CAUSA_PEND_BASE INT
			DECLARE @DBG_CAUSA_SIN_CAUSA INT
			DECLARE @DBG_CAUSA_UPDATED INT

			SELECT @DBG_CAUSA_TOTAL_BASE = COUNT(*)
			FROM ITRAH
			WHERE CNSITRA = @CNSITRA
			  AND COALESCE(INICIAL,0)=0

			SELECT @DBG_CAUSA_SIN_CAUSA = COUNT(*)
			FROM ITRAH
			WHERE CNSITRA = @CNSITRA
			  AND COALESCE(INICIAL,0)=0
			  AND COALESCE(IDCAUSAL,'')=''

			SELECT @DBG_CAUSA_PEND_BASE = COUNT(*)
			FROM ITRAH H
			WHERE H.CNSITRA = @CNSITRA
			  AND COALESCE(H.INICIAL,0)=0
			  AND COALESCE(H.IDCAUSAL,'')=''
			  AND COALESCE(H.CANTIDADORI,0) > 0

			-- (debug removido)

			UPDATE ITRAH SET IDCAUSAL = @IDCAUSA
			WHERE ITRAH.CNSITRA = @CNSITRA
				AND COALESCE(ITRAH.INICIAL, 0) = 0
				AND COALESCE(ITRAH.IDCAUSAL,'') = ''
				AND COALESCE(ITRAH.CANTIDADORI, 0) > 0

			SET @DBG_CAUSA_UPDATED = @@ROWCOUNT
			-- (debug removido)

			IF @DBG_CAUSA_UPDATED = 0
			BEGIN
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'No se encontraron art�culos pendientes sin causa para aplicar la causa masiva.'
			END
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'GUARDA_INV'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSRPDX = CNSRPDX, @IDARTICULO = IDARTICULO
		, @REGINVIMA = REGINVIMA, @F_VIGENCIAINV = F_VIGENCIAINV, @CODBARRA = CODBARRA, @CODCUM = CODCUM
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)					'$.CNSITRA'
		,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
		,CNSRPDX			VARCHAR(20)					'$.CNSRPDX'
		,IDARTICULO			VARCHAR(20)					'$.IDARTICULO'
		,REGINVIMA			VARCHAR(20)					'$.REGINVIMA'
		,F_VIGENCIAINV		DATE						'$.F_VIGENCIAINV'
		,CODBARRA			VARCHAR(20)					'$.CODBARRA'
		,CODCUM				VARCHAR(20)					'$.CODCUM'
		)
		IF COALESCE(@REGINVIMA,'')<>'' AND LEN(@REGINVIMA)<10
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Codigo no valido... debe tener m�nimo 10 caracteres.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END	
		IF (SELECT REGINVIMA FROM IART WHERE  IDARTICULO = @IDARTICULO) = @REGINVIMA AND DBO.FNK_VALORVARIABLE('VALIDA_INVI') = 'SI'
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Para guardar por favor modifique el registro INVIMA.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END	
		IF @F_VIGENCIAINV < CONVERT(DATE,GETDATE())
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Fecha de vigencia no valida, no puede ser inferior a la actual.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END	
		BEGIN TRY 
			UPDATE IART SET CODBARRA = @CODBARRA ,REGINVIMA = @REGINVIMA,F_VIGENCIAINV = @F_VIGENCIAINV WHERE IART.IDARTICULO = @IDARTICULO 

			IF NOT EXISTS (SELECT 1 FROM  RINVIM WHERE IDARTICULO =  @IDARTICULO 
			AND NREGISTRO = @REGINVIMA )
			BEGIN
				SELECT @CNSRINVIMA = NULL
				EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE,@PREFIJO='@RINVIM', @LONGITUD=8, @NVOCONSEC=@CNSRINVIMA OUTPUT  

				INSERT INTO RINVIM (CNSRINVIMA, IDARTICULO, FINGRESO, NREGISTRO, FVENCE)
				SELECT @CNSRINVIMA, @IDARTICULO, DBO.FNK_GETDATE(), @REGINVIMA, @F_VIGENCIAINV

			END
			SELECT 'OK' AS OK
			SELECT CNSRINVIMA, IDARTICULO, FINGRESO, NREGISTRO, FVENCE FROM RINVIM WHERE IDARTICULO = @IDARTICULO
			ORDER BY  RINVIM.FINGRESO  DESC

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'SEL_RINVIM'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSRPDX = CNSRPDX, @IDARTICULO = IDARTICULO
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)					'$.CNSITRA'
		,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
		,CNSRPDX			VARCHAR(20)					'$.CNSRPDX'
		,IDARTICULO			VARCHAR(20)					'$.IDARTICULO'
		)
			
		BEGIN TRY 
			SELECT 'OK' AS OK
			SELECT CNSRINVIMA, IDARTICULO, FINGRESO, NREGISTRO, FVENCE FROM RINVIM WHERE IDARTICULO = @IDARTICULO
			ORDER BY  RINVIM.FINGRESO  DESC
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'CANCELAR_TRANSITO'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSFCOM = CNSFCOM
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)					'$.CNSITRA'
		,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
		,CNSFCOM			VARCHAR(20)					'$.CNSFCOM'
		)

		BEGIN TRY 
			IF (  SELECT IDTIPOMOV FROM ITRA WHERE ITRA.CNSITRA = @CNSITRA) = (SELECT DBO.FNK_VALORVARIABLE ('IDINVMOV_COMPRAS')) OR
				(  SELECT IDTIPOMOV FROM ITRA WHERE ITRA.CNSITRA = @CNSITRA) = (SELECT DBO.FNK_VALORVARIABLE ('IDTS'))
			BEGIN
				IF (SELECT COUNT(*) FROM IMOV WHERE CNSFCOM = @CNSFCOM)>0 OR (SELECT DBO.FNK_VALORVARIABLE('ANULA_TRANSITO_SINEN')) = 'SI' 
				BEGIN
					SELECT 'OK' AS OK, '1' PASO
				END	
				ELSE
				BEGIN
					SELECT 'OK' AS OK, '2' PASO
				END
			END	
			ELSE
				SELECT 'OK' AS OK, '2' PASO
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'CANCELA_1'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @CNSFCOM = CNSFCOM
		FROM OPENJSON (@PARAMETROS)
		WITH		 (
		CNSITRA				VARCHAR(20)					'$.CNSITRA'
		,IDBODEGA			VARCHAR(20)					'$.IDBODEGA'
		,CNSFCOM			VARCHAR(20)					'$.CNSFCOM'
		)

		BEGIN TRY 
			SELECT @CNSFCOM = COALESCE(NULLIF(LTRIM(RTRIM(@CNSFCOM)), ''), NULLIF(LTRIM(RTRIM(CNSFCOM)), ''))
			FROM ITRA WHERE CNSITRA = @CNSITRA

			UPDATE ITRA SET ESTADO = 3, USUARIOANU = @USUARIO , F_ANULA = DBO.FNK_GETDATE() WHERE ITRA.CNSITRA = @CNSITRA

			/* Registrar cancelaci�n de tr�nsito de OC (alerta UI en FCOM) */
			IF COALESCE(@CNSFCOM, '') <> '' AND OBJECT_ID('dbo.FCOMTRANEVT', 'U') IS NOT NULL
			BEGIN
				INSERT INTO FCOMTRANEVT (CNSFCOM, CNSITRA, TIPO, MOTIVO, USUARIO, FECHA)
				SELECT @CNSFCOM, @CNSITRA, 'CANCELA_TRANSITO',
					'Cancelaci�n completa del tr�nsito de compra', @USUARIO, DBO.FNK_GETDATE()
				WHERE NOT EXISTS (
					SELECT 1 FROM FCOMTRANEVT E
					WHERE E.CNSITRA = @CNSITRA AND E.TIPO = 'CANCELA_TRANSITO'
				)

				/* Marcar en FCOMD las l�neas del tr�nsito que no tuvieron entrada confirmada */
				INSERT INTO FCOMTRANEVT (
					CNSFCOM, CNSITRA, TIPO, IDARTICULO_ITRAH, IDARTICULO_FCOMD,
					IDARTICULOORI, NOLOTE, MOTIVO, USUARIO, FECHA
				)
				SELECT
					@CNSFCOM,
					H.CNSITRA,
					'ELIMINA_LINEA',
					H.IDARTICULO,
					COALESCE(
						(SELECT TOP 1 F.IDARTICULO FROM FCOMD F
						 WHERE F.CNSFCOM = @CNSFCOM
						   AND F.IDARTICULO IN (H.IDARTICULOORI, H.IDARTICULO,
								(SELECT TOP 1 HERMANO_MAYOR FROM VWK_HERMANOS_INVENTARIO V WHERE V.IDARTICULO = H.IDARTICULO))
						 ORDER BY CASE WHEN F.IDARTICULO = H.IDARTICULOORI THEN 0 WHEN F.IDARTICULO = H.IDARTICULO THEN 1 ELSE 2 END),
						COALESCE(NULLIF(H.IDARTICULOORI, ''), H.IDARTICULO)
					),
					H.IDARTICULOORI,
					H.NOLOTE,
					'L�nea pendiente al cancelar el tr�nsito',
					@USUARIO,
					DBO.FNK_GETDATE()
				FROM ITRAH H
				WHERE H.CNSITRA = @CNSITRA
				  AND COALESCE(H.INICIAL, 0) = 0
				  AND NOT EXISTS (
						SELECT 1 FROM IMOV M
						INNER JOIN IMOVH MH ON MH.CNSMOV = M.CNSMOV
						WHERE M.CNSITRA = H.CNSITRA
						  AND M.ESTADO = 1
						  AND MH.ESTADO = 1
						  AND MH.IDARTICULO = H.IDARTICULO
					)
				  AND NOT EXISTS (
						SELECT 1 FROM FCOMTRANEVT E
						WHERE E.CNSITRA = H.CNSITRA
						  AND E.TIPO = 'ELIMINA_LINEA'
						  AND E.IDARTICULO_ITRAH = H.IDARTICULO
					)
			END

			-- Si el tr�nsito no tiene movimientos asociados, se considera "vac�o/duplicado" y se anula sin generar reversas.
			-- Evita errores del tipo "Movimiento no cumple con los requisitos para ser devuelto".
			IF EXISTS (SELECT 1 FROM IMOV WHERE CNSITRA = @CNSITRA)
			   AND (SELECT IDTIPOMOV FROM ITRA WHERE ITRA.CNSITRA = @CNSITRA) = (SELECT DBO.FNK_VALORVARIABLE ('IDTS'))
			BEGIN
				SELECT @DATO = (SELECT DBO.FNK_VALORVARIABLE ('IDTE'))
				EXEC SPK_INSERTENTTRANSITO @CNSITRA, @USUARIO,@IDBODEGA,@DATO,@SYS_COMPUTERNAME,@COMPANIA,@SEDE
			END

			/* OC: al cancelar tr�nsito residual, cerrar recepci�n si ya no hay pendientes reales */
			IF COALESCE(@CNSFCOM, '') <> '' AND OBJECT_ID('dbo.SPK_FCOM_RECALCULA_RECEPCION', 'P') IS NOT NULL
				EXEC DBO.SPK_FCOM_RECALCULA_RECEPCION @CNSFCOM
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'QUITAR_LOTE'
	BEGIN
		SELECT @CNSITRA = CNSITRA, @IDBODEGA = IDBODEGA, @IDARTICULOORI = IDARTICULOORI
			,@NOLOTE = NOLOTE
		FROM OPENJSON (@PARAMETROS)
		WITH (
			 CNSITRA		VARCHAR(20)		'$.CNSITRA'
			,IDBODEGA		VARCHAR(20)		'$.IDBODEGA'
			,IDARTICULOORI	VARCHAR(20)		'$.IDARTICULOORI'
			,NOLOTE			VARCHAR(20)		'$.NOLOTE'
		)

		BEGIN TRY 
			SELECT @CNSFCOM = CNSFCOM FROM ITRA WHERE  CNSITRA = @CNSITRA

			DELETE FROM ITRAH WHERE CNSITRA = @CNSITRA AND IDARTICULOORI = @IDARTICULOORI

			INSERT INTO ITRAH (CNSITRA,IDARTICULO,NOLOTE,CANTIDADORI,CANTIDADDES,IDCAUSAL,ESTADO,PCOSTO,NOLOTEPEDIDO,FECHAVENCE,DETALLE,IDARTICULOORI, IVA, PCSINIVA) 
			SELECT @CNSITRA,IDARTICULO AS IDARTICULO, NOLOTE, CANTIDAD AS CANTIDADORI,0 AS CANTIDADDES, '' AS IDCAUSAL,0 AS ESTADO, 
			CASE TER.TIPOREGIMEN                                                                
				WHEN 'C' THEN CASE FCOM.DECONSUMO                                            
									WHEN 0 THEN FCOMD.VLR_UNITARIO                              
									ELSE FCOMD.VR_UNITMASIVA                                    
								END                                                              
				ELSE VR_UNITMASIVA                                                             
			END,                                                                                
			FCOMD.NOLOTE, FCOMD.FECHAVENCE, FCOMD.DETALLE,@IDARTICULOORI ,  FCOMD.FACTORIVA , FCOMD.VLR_UNITARIO     
			FROM FCOMD INNER JOIN FCOM ON FCOMD.CNSFCOM=FCOM.CNSFCOM                            
						INNER JOIN TER  ON FCOM.IDTERCERO=TER.IDTERCERO                          
			WHERE FCOMD.CNSFCOM= @CNSFCOM                                       
			AND FCOMD.IDARTICULO= @IDARTICULOORI

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK
		RETURN
	END
	IF @METODO = 'AGREGA_CUSTODIA'
	BEGIN
		SELECT @IDTERCERO = IDTERCERO, @OBSERVACION = OBSERVACION, @IDBODEGA = IDBODEGA
		FROM OPENJSON(@PARAMETROS)
		WITH(	IDTERCERO	VARCHAR(20) '$.IDTERCERO',OBSERVACION	VARCHAR(250) '$.OBSERVACION', IDBODEGA	VARCHAR(20) '$.IDBODEGA')

		IF COALESCE(DBO.FNK_VALORVARIABLE('IDINVTPROPIA'),'') = ''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Debe de configurar la variable IDINVTPROPIA'
		END
	
		IF (SELECT COUNT(*) FROM @TBLERRORES)> 0
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		ELSE
		BEGIN
			BEGIN TRY
				-- Blindaje CNSITRA (@ITRA): lock + reintentos + fallback MAX+1 (evita PK ITRACNSITRA por desfase de secuencia)
				DECLARE @LOCK_RES_CUST NVARCHAR(200) = N'QRYSTALOS:CONSEC:@ITRA:' + COALESCE(@COMPANIA,'') + N':' + COALESCE(@SEDE,'')
				DECLARE @LOCK_R_CUST INT
				DECLARE @LOCK_OK_CUST BIT = 0
				DECLARE @TRY_CUST INT = 0
				DECLARE @MAX_TRY_CUST INT = 50
				DECLARE @CNSITRA_RAW_CUST VARCHAR(20)
				DECLARE @LEN_NUM_ITRA INT = 8
				DECLARE @MAX_NUM_ITRA BIGINT
				DECLARE @SEDE_ITRA VARCHAR(5) = COALESCE(NULLIF(LTRIM(RTRIM(@SEDE)), ''), '01')

				EXEC @LOCK_R_CUST = sys.sp_getapplock
					@Resource = @LOCK_RES_CUST,
					@LockMode = 'Exclusive',
					@LockOwner = 'Session',
					@LockTimeout = 10000

				IF @LOCK_R_CUST < 0
				BEGIN
					INSERT INTO @TBLERRORES(ERROR)
					SELECT 'No fue posible obtener lock para generar CNSITRA (@ITRA) en custodia.'
				END
				ELSE
				BEGIN
					SET @LOCK_OK_CUST = 1
					SET @NUEVOCNS = NULL

					WHILE @TRY_CUST < @MAX_TRY_CUST
					BEGIN
						SET @TRY_CUST += 1
						SET @CNSITRA_RAW_CUST = SPACE(20)
						EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE_ITRA, '@ITRA', @CNSITRA_RAW_CUST OUTPUT
						SELECT @NUEVOCNS = @SEDE_ITRA
							+ REPLACE(SPACE(@LEN_NUM_ITRA - LEN(LTRIM(RTRIM(@CNSITRA_RAW_CUST))))
								+ LTRIM(RTRIM(@CNSITRA_RAW_CUST)), SPACE(1), 0)

						IF NOT EXISTS (SELECT 1 FROM ITRA WITH (NOLOCK) WHERE CNSITRA = @NUEVOCNS)
							BREAK

						SET @NUEVOCNS = NULL
					END

					-- Si la secuencia sigue atrasada: MAX(CNSITRA) de la sede + 1
					IF @NUEVOCNS IS NULL OR EXISTS (SELECT 1 FROM ITRA WITH (NOLOCK) WHERE CNSITRA = @NUEVOCNS)
					BEGIN
						SELECT @MAX_NUM_ITRA = MAX(TRY_CAST(
							CASE
								WHEN LEFT(CNSITRA, LEN(@SEDE_ITRA)) = @SEDE_ITRA
									THEN SUBSTRING(CNSITRA, LEN(@SEDE_ITRA) + 1, 50)
								ELSE NULL
							END AS BIGINT))
						FROM ITRA WITH (NOLOCK)
						WHERE CNSITRA LIKE @SEDE_ITRA + '%'
						  AND LEN(CNSITRA) <= LEN(@SEDE_ITRA) + @LEN_NUM_ITRA + 2

						SET @MAX_NUM_ITRA = COALESCE(@MAX_NUM_ITRA, 0) + 1
						SET @NUEVOCNS = @SEDE_ITRA
							+ RIGHT(REPLICATE('0', @LEN_NUM_ITRA) + CAST(@MAX_NUM_ITRA AS VARCHAR(20)), @LEN_NUM_ITRA)
					END

					IF @NUEVOCNS IS NULL OR @NUEVOCNS = ''
						OR EXISTS (SELECT 1 FROM ITRA WITH (NOLOCK) WHERE CNSITRA = @NUEVOCNS)
					BEGIN
						INSERT INTO @TBLERRORES(ERROR)
						SELECT 'Error al generar CNSITRA �nico (@ITRA) para custodia. Revise SEQ_'
							+ @SEDE_ITRA + '_@ITRA (posible desfase con MAX(CNSITRA)).'
					END
					ELSE
					BEGIN
						PRINT 'Consecutivo Transito Custodia: ' + @NUEVOCNS
						INSERT INTO ITRA(CNSITRA,IDBODEGAORI,IDBODEGADES,USUARIOORI,USUARIODES,USUARIOTRA,
										PROCEDENCIA,CNSMOVORI,CNSMOVDES,NOADMISION,FECHAING,FECHAEGR,ESTADO,
										IDTIPOMOV,IDDEP,CNSFCOM,CCOSTO,IDAREA,LOTEADO)
						SELECT @NUEVOCNS,'',@IDBODEGA,@USUARIO,'',@IDTERCERO,'INV',
							'CUSTODIA','','',DBO.FNK_FECHA_SIN_MLS(GETDATE()),'',0,DBO.FNK_VALORVARIABLE('IDINVTPROPIA'),'',NULL,NULL,NULL,0
					END
				END

				IF @LOCK_OK_CUST = 1
				BEGIN
					BEGIN TRY
						EXEC sys.sp_releaseapplock @Resource = @LOCK_RES_CUST, @LockOwner = 'Session'
					END TRY
					BEGIN CATCH
					END CATCH
				END
			END TRY
			BEGIN CATCH
				IF @LOCK_OK_CUST = 1
				BEGIN
					BEGIN TRY
						EXEC sys.sp_releaseapplock @Resource = @LOCK_RES_CUST, @LockOwner = 'Session'
					END TRY
					BEGIN CATCH
					END CATCH
				END
				INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE();
			END CATCH
			IF (SELECT COUNT(*) FROM @TBLERRORES)> 0
			BEGIN
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
			SELECT 'OK'OK, @NUEVOCNS CNSITRA
		END 
	END

	IF @METODO = 'CONSULTA_ARTICULOS_PRUEBA'
	BEGIN
		DECLARE @IDBODEGA_CONS VARCHAR(20) = NULL

		SELECT @IDBODEGA_CONS = IDBODEGA
		FROM OPENJSON(@PARAMETROS)
		WITH(
			IDBODEGA    VARCHAR(20)   '$.IDBODEGA'
		)

		SELECT 'OK' AS OK

		-- Recordset 1: Art�culos por fabricante activos permitidos en la bodega (IBODS), sin l�mite TOP
		SELECT
			IART.IDARTICULO,
			IART.DESCRIPCION,
			IART.IDITAR,
			IART.PRINCIPAL
		FROM IART
		INNER JOIN IBODS ON IBODS.IDBODEGA = @IDBODEGA_CONS
			AND IBODS.TIPO = 'ITAR'
			AND IBODS.VALOR = IART.IDITAR
			AND COALESCE(IBODS.ACCESO, 'Si') = 'Si'
		WHERE IART.ESTADO = 'Activo'
		  AND COALESCE(IART.PRINCIPAL, 0) = 0
		ORDER BY IART.IDARTICULO

		-- Recordset 2: Proveedores (TER con VWK_TEXCA IDCATEGORIA='PRO')
		SELECT 
			LTRIM(RTRIM(TER.NIT)) + CASE WHEN COALESCE(LTRIM(RTRIM(TER.DV)),'') <> '' THEN '-'+LTRIM(RTRIM(TER.DV)) ELSE '' END AS NIT,
			TER.RAZONSOCIAL,
			TER.IDTERCERO
		FROM TER
		INNER JOIN VWK_TEXCA ON VWK_TEXCA.IDTERCERO = TER.IDTERCERO
			AND VWK_TEXCA.IDCATEGORIA = 'PRO'
			AND VWK_TEXCA.ESTADO = 'Activo'
		WHERE TER.ESTADO = 'Activo'
			AND COALESCE(TER.NIT,'') <> ''
		ORDER BY TER.RAZONSOCIAL

		RETURN
	END


	IF @METODO = 'SUBIR_CUSTODIA_MASIVA'
	BEGIN
		SELECT 
			@DATOS_ARTICULOS = DATOS,
			@CNSITRA = CNSITRA,
			@IDBODEGA = IDBODEGA
		FROM OPENJSON(@PARAMETROS)
		WITH(
			DATOS       NVARCHAR(MAX) AS JSON,
			CNSITRA     VARCHAR(20)   '$.CNSITRA',
			IDBODEGA    VARCHAR(20)   '$.IDBODEGA'
		)

		-- Validar que la bodega sea de custodia (ESDECUSTODIA = 1)
		IF NOT EXISTS (SELECT 1 FROM IBOD WHERE IDBODEGA = @IDBODEGA AND COALESCE(ESDECUSTODIA, 0) = 1)
		BEGIN
			DECLARE @NOMBRE_BODEGA VARCHAR(200) = ''
			SELECT @NOMBRE_BODEGA = DESCRIPCION FROM IBOD WHERE IDBODEGA = @IDBODEGA
	
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'La bodega seleccionada (' + ISNULL(@NOMBRE_BODEGA, @IDBODEGA) + ') no est� configurada para custodia masiva.'

			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF NOT EXISTS (SELECT 1 FROM ITRA WHERE CNSITRA = @CNSITRA)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'El consecutivo de custodia no existe.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF (SELECT COALESCE(ESTADO, 0) FROM ITRA WHERE CNSITRA = @CNSITRA) <> 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'La custodia ya est� procesada o anulada.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 
			@IDSEDE = COALESCE((SELECT IDSEDE FROM UBEQ WHERE SYS_COMPUTERNAME = @SYS_COMPUTERNAME), @SEDE)
		FROM ITRA 
		WHERE CNSITRA = @CNSITRA

		-- Crear tabla temporal con datos del Excel
		SELECT 
			AC.CEDULA,
			AC.IDARTICULO,
			LTRIM(RTRIM(COALESCE(AC.PROVEEDOR,''))) AS PROVEEDOR,
			CASE WHEN COALESCE(AC.CANTIDAD, 0) < 1 THEN 1 ELSE AC.CANTIDAD END AS CANTIDAD,
			CASE
				WHEN AC.CANTIDADREV IS NULL THEN NULL
				WHEN AC.CANTIDADREV < 0 THEN 0
				WHEN AC.CANTIDADREV > CASE WHEN COALESCE(AC.CANTIDAD, 0) < 1 THEN 1 ELSE AC.CANTIDAD END
					THEN CASE WHEN COALESCE(AC.CANTIDAD, 0) < 1 THEN 1 ELSE AC.CANTIDAD END
				ELSE AC.CANTIDADREV
			END AS CANTIDADREV,
			AC.NOLOTEPEDIDO,
			AC.FECHAVENCE,
			COALESCE(AC.PCOSTO, 0) AS PCOSTO,
			COALESCE(AC.IVA, 0) AS IVA,
			AC.CUMPLE,
			AC.APROBADO,
			AC.TEMPERATURA,
			TER.IDTERCERO
		INTO #ARTICULOS_CUSTODIA
		FROM (
			SELECT CEDULA, IDARTICULO, PROVEEDOR, CANTIDAD, CANTIDADREV, NOLOTEPEDIDO, FECHAVENCE, PCOSTO, IVA, CUMPLE, APROBADO, TEMPERATURA
			FROM OPENJSON(@DATOS_ARTICULOS)
			WITH(
				CEDULA          VARCHAR(20)      '$.CEDULA',
				IDARTICULO      VARCHAR(20)      '$.IDARTICULO',
				PROVEEDOR       VARCHAR(20)      '$.PROVEEDOR',
				CANTIDAD        INT              '$.CANTIDAD',  
				CANTIDADREV     INT              '$.CANTIDADREV',
				NOLOTEPEDIDO    VARCHAR(50)      '$.NOLOTEPEDIDO',
				FECHAVENCE      VARCHAR(20)      '$.FECHAVENCE',
				PCOSTO          DECIMAL(14,2)    '$.PCOSTO',
				IVA             DECIMAL(14,2)    '$.IVA',
				CUMPLE          BIT              '$.CUMPLE',
				APROBADO        BIT              '$.APROBADO',
				TEMPERATURA     DECIMAL(14,2)    '$.TEMPERATURA'
			)
		) AC
		OUTER APPLY (
			SELECT TOP 1 TER.IDTERCERO
			FROM TER
			WHERE TER.ESTADO = 'Activo'
				AND (
					LTRIM(RTRIM(TER.NIT)) = LTRIM(RTRIM(COALESCE(AC.PROVEEDOR,'')))
					OR LTRIM(RTRIM(TER.NIT)) + ISNULL('-'+LTRIM(RTRIM(TER.DV)),'') = LTRIM(RTRIM(COALESCE(AC.PROVEEDOR,'')))
					OR LTRIM(RTRIM(COALESCE(AC.PROVEEDOR,''))) = LTRIM(RTRIM(TER.NIT)) + ISNULL('-'+LTRIM(RTRIM(TER.DV)),'')
				)
		) TER

		-- Validar que todos los proveedores existan
		IF EXISTS (SELECT 1 FROM #ARTICULOS_CUSTODIA WHERE COALESCE(PROVEEDOR,'') <> '' AND IDTERCERO IS NULL)
		BEGIN
			DECLARE @NITS_NO_ENCONTRADOS VARCHAR(MAX) = ''
			SELECT @NITS_NO_ENCONTRADOS = @NITS_NO_ENCONTRADOS + PROVEEDOR + ', '
			FROM (SELECT DISTINCT PROVEEDOR FROM #ARTICULOS_CUSTODIA WHERE COALESCE(PROVEEDOR,'') <> '' AND IDTERCERO IS NULL) T
			SET @NITS_NO_ENCONTRADOS = LEFT(@NITS_NO_ENCONTRADOS, LEN(@NITS_NO_ENCONTRADOS) - 1)
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'Los siguientes NIT de proveedor no existen en cat�logo TER: ' + @NITS_NO_ENCONTRADOS
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		-- Validaci�n de fechas, art�culos, IBODS, campos obligatorios (igual que antes)
		IF EXISTS (SELECT 1 FROM #ARTICULOS_CUSTODIA WHERE FECHAVENCE IS NOT NULL AND LTRIM(RTRIM(FECHAVENCE)) <> '' AND TRY_CONVERT(DATE, LTRIM(RTRIM(FECHAVENCE)), 120) IS NULL)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Hay fechas inv�lidas. Formato esperado: YYYY-MM-DD'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF (SELECT COUNT(*) FROM #ARTICULOS_CUSTODIA) = 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se encontraron art�culos para procesar.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (SELECT 1 FROM #ARTICULOS_CUSTODIA A WHERE NOT EXISTS (SELECT 1 FROM IART WHERE IART.IDARTICULO = A.IDARTICULO AND IART.ESTADO = 'Activo'))
		BEGIN
			DECLARE @ARTICULOS_NO_ENCONTRADOS VARCHAR(MAX) = ''
			SELECT @ARTICULOS_NO_ENCONTRADOS = @ARTICULOS_NO_ENCONTRADOS + A.IDARTICULO + ', '
			FROM #ARTICULOS_CUSTODIA A
			WHERE NOT EXISTS (SELECT 1 FROM IART WHERE IART.IDARTICULO = A.IDARTICULO AND IART.ESTADO = 'Activo')
			SET @ARTICULOS_NO_ENCONTRADOS = LEFT(@ARTICULOS_NO_ENCONTRADOS, LEN(@ARTICULOS_NO_ENCONTRADOS) - 1)
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Art�culos no existen o inactivos: ' + @ARTICULOS_NO_ENCONTRADOS
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		-- Custodia masiva: solo fabricantes/presentaciones (IART.PRINCIPAL = 0). No permitir art�culos principales.
		IF EXISTS (
			SELECT 1
			FROM #ARTICULOS_CUSTODIA A
			INNER JOIN IART ON IART.IDARTICULO = A.IDARTICULO
			WHERE COALESCE(IART.PRINCIPAL, 0) <> 0
		)
		BEGIN
			DECLARE @ART_PRINCIPALES VARCHAR(MAX) = ''
			SELECT @ART_PRINCIPALES = @ART_PRINCIPALES + A.IDARTICULO + ', '
			FROM (
				SELECT DISTINCT A.IDARTICULO
				FROM #ARTICULOS_CUSTODIA A
				INNER JOIN IART ON IART.IDARTICULO = A.IDARTICULO
				WHERE COALESCE(IART.PRINCIPAL, 0) <> 0
			) A
			SET @ART_PRINCIPALES = LEFT(@ART_PRINCIPALES, LEN(@ART_PRINCIPALES) - 1)
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'No se permiten art�culos principales (IART.PRINCIPAL = 1). Utilice e el c�digo del fabricante/presentaci�n (PRINCIPAL = 0): ' + @ART_PRINCIPALES
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (SELECT 1 FROM #ARTICULOS_CUSTODIA A INNER JOIN IART ON A.IDARTICULO = IART.IDARTICULO
			WHERE NOT EXISTS (SELECT 1 FROM IBODS WHERE TIPO = 'ITAR' AND VALOR = IART.IDITAR AND ACCESO = 'Si' AND IDBODEGA = @IDBODEGA))
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Algunos art�culos no est�n permitidos en esta bodega (IBODS).'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (SELECT 1 FROM #ARTICULOS_CUSTODIA WHERE COALESCE(CEDULA, '') = '' OR COALESCE(PROVEEDOR, '') = '' OR COALESCE(NOLOTEPEDIDO, '') = '' 
			OR COALESCE(FECHAVENCE, '') = '' OR CUMPLE IS NULL OR APROBADO IS NULL OR TEMPERATURA IS NULL
			OR COALESCE(CANTIDAD, 0) < 1 OR CANTIDADREV IS NULL OR CANTIDADREV < 0 OR CANTIDADREV > CANTIDAD)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) 
			SELECT 'Campos obligatorios vac�os o inv�lidos: CEDULA, PROVEEDOR (NIT), CANTIDAD (>=1), CANTIDADREV (>=0 y <= CANTIDAD), NOLOTEPEDIDO, FECHAVENCE, CUMPLE, APROBADO, TEMPERATURA.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (SELECT 1 FROM #ARTICULOS_CUSTODIA A WHERE NOT EXISTS (SELECT 1 FROM AFI WHERE LTRIM(RTRIM(AFI.DOCIDAFILIADO)) = LTRIM(RTRIM(A.CEDULA)) AND AFI.ESTADO = 'Activo'))
		BEGIN
			DECLARE @CEDULAS_NO_ENCONTRADAS VARCHAR(MAX) = ''
			SELECT @CEDULAS_NO_ENCONTRADAS = @CEDULAS_NO_ENCONTRADAS + A.CEDULA + ', '
			FROM #ARTICULOS_CUSTODIA A
			WHERE NOT EXISTS (SELECT 1 FROM AFI WHERE LTRIM(RTRIM(AFI.DOCIDAFILIADO)) = LTRIM(RTRIM(A.CEDULA)) AND AFI.ESTADO = 'Activo')
			SET @CEDULAS_NO_ENCONTRADAS = LEFT(@CEDULAS_NO_ENCONTRADAS, LEN(@CEDULAS_NO_ENCONTRADAS) - 1)
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Pacientes no existen o inactivos: ' + @CEDULAS_NO_ENCONTRADAS
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (
			SELECT 1
			FROM #ARTICULOS_CUSTODIA A
			INNER JOIN IART ON A.IDARTICULO = IART.IDARTICULO
			WHERE COALESCE(NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''), '') = ''
			  AND NOT EXISTS (SELECT 1 FROM SER S WHERE S.IDARTICULO = IART.IDARTICULO)
		)
		BEGIN
			DECLARE @ART_SIN_SERVICIO VARCHAR(MAX) = ''
			SELECT @ART_SIN_SERVICIO = @ART_SIN_SERVICIO + A.IDARTICULO + ', '
			FROM (
				SELECT DISTINCT A.IDARTICULO
				FROM #ARTICULOS_CUSTODIA A
				INNER JOIN IART ON A.IDARTICULO = IART.IDARTICULO
				WHERE COALESCE(NULLIF(LTRIM(RTRIM(IART.IDSERVICIO)), ''), '') = ''
				  AND NOT EXISTS (SELECT 1 FROM SER S WHERE S.IDARTICULO = IART.IDARTICULO)
			) A
			SET @ART_SIN_SERVICIO = LEFT(@ART_SIN_SERVICIO, LEN(@ART_SIN_SERVICIO) - 1)
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'Art�culos sin servicio asociado (IDSERVICIO/SER): ' + @ART_SIN_SERVICIO
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		BEGIN TRY
			DECLARE @CONTADOR INT = 0
			DECLARE @TOTAL_ARTICULOS INT = (SELECT SUM(COALESCE(CANTIDAD, 1)) FROM #ARTICULOS_CUSTODIA)
			DECLARE @CONTADOR_MOVIMIENTOS INT = 0
			DECLARE @PCSINIVA DECIMAL(14,2)
			DECLARE @CCOSTO_CUSTODIA VARCHAR(20) = NULL
			DECLARE @IDAREA_CUSTODIA VARCHAR(20) = NULL

			-- Obtener centro de costo e IDAREA de la bodega
			SELECT @CCOSTO_CUSTODIA = CCOSTO, @IDAREA_CUSTODIA = IDAREA
			FROM IBOD WHERE IDBODEGA = @IDBODEGA

			-- Tabla: mapeo IDTERCERO -> CNSITRA (un ITRA por tercero/proveedor)
			CREATE TABLE #ITRA_POR_TERCERO (IDTERCERO VARCHAR(20), CNSITRA VARCHAR(20))
			DECLARE @CNSITRA_USAR VARCHAR(20)
			DECLARE @IDTERCERO_ACT VARCHAR(20)
			DECLARE @CNSITRA_NUEVO VARCHAR(20)
			DECLARE @PRIMER_TERCERO BIT = 1

			INSERT INTO #ITRA_POR_TERCERO (IDTERCERO, CNSITRA)
			SELECT DISTINCT IDTERCERO, NULL FROM #ARTICULOS_CUSTODIA WHERE IDTERCERO IS NOT NULL

			-- Asignar CNSITRA: el primero usa el existente; los dem�s crean nuevo ITRA
			DECLARE CURSOR_TERCERO CURSOR FOR SELECT IDTERCERO FROM #ITRA_POR_TERCERO ORDER BY IDTERCERO
			OPEN CURSOR_TERCERO
			FETCH NEXT FROM CURSOR_TERCERO INTO @IDTERCERO_ACT
			WHILE @@FETCH_STATUS = 0
			BEGIN
				IF @PRIMER_TERCERO = 1
				BEGIN
					UPDATE #ITRA_POR_TERCERO SET CNSITRA = @CNSITRA WHERE IDTERCERO = @IDTERCERO_ACT
					UPDATE ITRA SET USUARIOTRA = @IDTERCERO_ACT WHERE CNSITRA = @CNSITRA
					SET @PRIMER_TERCERO = 0
				END
				ELSE
				BEGIN
					DECLARE @COMPANIA_TRA VARCHAR(2)
					DECLARE @LOCK_RES_CM NVARCHAR(200)
					DECLARE @LOCK_R_CM INT
					DECLARE @LOCK_OK_CM BIT = 0
					DECLARE @TRY_CM INT = 0
					DECLARE @MAX_TRY_CM INT = 50
					DECLARE @CNSITRA_RAW_CM VARCHAR(20)
					DECLARE @LEN_NUM_CM INT = 8
					DECLARE @MAX_NUM_CM BIGINT
					DECLARE @SEDE_CM VARCHAR(5) = COALESCE(NULLIF(LTRIM(RTRIM(@SEDE)), ''), '01')

					SELECT TOP 1 @COMPANIA_TRA = COALESCE(COMPANIA, '01') FROM UBEQ WHERE SYS_COMPUTERNAME = @SYS_COMPUTERNAME
					SET @CNSITRA_NUEVO = NULL
					SET @LOCK_RES_CM = N'QRYSTALOS:CONSEC:@ITRA:' + COALESCE(@COMPANIA_TRA,'') + N':' + @SEDE_CM

					EXEC @LOCK_R_CM = sys.sp_getapplock
						@Resource = @LOCK_RES_CM,
						@LockMode = 'Exclusive',
						@LockOwner = 'Session',
						@LockTimeout = 10000

					IF @LOCK_R_CM >= 0
					BEGIN
						SET @LOCK_OK_CM = 1

						WHILE @TRY_CM < @MAX_TRY_CM
						BEGIN
							SET @TRY_CM += 1
							SET @CNSITRA_RAW_CM = SPACE(20)
							EXEC SPK_GENCONSECUTIVO @COMPANIA_TRA, @SEDE_CM, '@ITRA', @CNSITRA_RAW_CM OUTPUT
							SET @CNSITRA_NUEVO = @SEDE_CM
								+ RIGHT(REPLICATE('0', @LEN_NUM_CM) + LTRIM(RTRIM(ISNULL(@CNSITRA_RAW_CM,'0'))), @LEN_NUM_CM)

							IF NOT EXISTS (SELECT 1 FROM ITRA WITH (NOLOCK) WHERE CNSITRA = @CNSITRA_NUEVO)
								BREAK

							SET @CNSITRA_NUEVO = NULL
						END

						IF @CNSITRA_NUEVO IS NULL OR EXISTS (SELECT 1 FROM ITRA WITH (NOLOCK) WHERE CNSITRA = @CNSITRA_NUEVO)
						BEGIN
							SELECT @MAX_NUM_CM = MAX(TRY_CAST(
								CASE
									WHEN LEFT(CNSITRA, LEN(@SEDE_CM)) = @SEDE_CM
										THEN SUBSTRING(CNSITRA, LEN(@SEDE_CM) + 1, 50)
									ELSE NULL
								END AS BIGINT))
							FROM ITRA WITH (NOLOCK)
							WHERE CNSITRA LIKE @SEDE_CM + '%'
							  AND LEN(CNSITRA) <= LEN(@SEDE_CM) + @LEN_NUM_CM + 2

							SET @MAX_NUM_CM = COALESCE(@MAX_NUM_CM, 0) + 1
							SET @CNSITRA_NUEVO = @SEDE_CM
								+ RIGHT(REPLICATE('0', @LEN_NUM_CM) + CAST(@MAX_NUM_CM AS VARCHAR(20)), @LEN_NUM_CM)
						END

						IF @CNSITRA_NUEVO IS NOT NULL AND @CNSITRA_NUEVO <> ''
							AND NOT EXISTS (SELECT 1 FROM ITRA WITH (NOLOCK) WHERE CNSITRA = @CNSITRA_NUEVO)
						BEGIN
							INSERT INTO ITRA (CNSITRA, IDBODEGAORI, IDBODEGADES, USUARIOORI, USUARIODES, USUARIOTRA, PROCEDENCIA, CNSMOVORI, CNSMOVDES, NOADMISION, FECHAING, FECHAEGR, ESTADO, IDTIPOMOV, IDDEP, CNSFCOM, CCOSTO, IDAREA, LOTEADO)
							SELECT @CNSITRA_NUEVO, IDBODEGAORI, IDBODEGADES, USUARIOORI, USUARIODES, @IDTERCERO_ACT, PROCEDENCIA, CNSMOVORI, CNSMOVDES, NOADMISION, FECHAING, FECHAEGR, ESTADO, IDTIPOMOV, IDDEP, CNSFCOM, CCOSTO, IDAREA, 0
							FROM ITRA WHERE CNSITRA = @CNSITRA
							UPDATE #ITRA_POR_TERCERO SET CNSITRA = @CNSITRA_NUEVO WHERE IDTERCERO = @IDTERCERO_ACT
						END
						ELSE
							UPDATE #ITRA_POR_TERCERO SET CNSITRA = @CNSITRA WHERE IDTERCERO = @IDTERCERO_ACT
					END
					ELSE
						UPDATE #ITRA_POR_TERCERO SET CNSITRA = @CNSITRA WHERE IDTERCERO = @IDTERCERO_ACT

					IF @LOCK_OK_CM = 1
					BEGIN
						BEGIN TRY
							EXEC sys.sp_releaseapplock @Resource = @LOCK_RES_CM, @LockOwner = 'Session'
						END TRY
						BEGIN CATCH
						END CATCH
					END
				END
				FETCH NEXT FROM CURSOR_TERCERO INTO @IDTERCERO_ACT
			END
			CLOSE CURSOR_TERCERO
			DEALLOCATE CURSOR_TERCERO

			-- Tabla: un IMOV por paciente + proveedor (tercero)
			CREATE TABLE #MOVIMIENTOS_POR_GRUPO (
				CEDULA VARCHAR(20),
				IDTERCERO VARCHAR(20),
				IDAFILIADO VARCHAR(20),
				CNSMOV VARCHAR(20)
			)

			CREATE TABLE #GRUPOS_PACIENTE_TERCERO (
				CEDULA VARCHAR(20),
				IDTERCERO VARCHAR(20),
				IDAFILIADO VARCHAR(20)
			)

			INSERT INTO #GRUPOS_PACIENTE_TERCERO (CEDULA, IDTERCERO, IDAFILIADO)
			SELECT DISTINCT
				LTRIM(RTRIM(AC.CEDULA)),
				AC.IDTERCERO,
				AFI.IDAFILIADO
			FROM #ARTICULOS_CUSTODIA AC
			INNER JOIN AFI ON LTRIM(RTRIM(AFI.DOCIDAFILIADO)) = LTRIM(RTRIM(AC.CEDULA)) AND AFI.ESTADO = 'Activo'

			DECLARE CURSOR_GRUPOS CURSOR FOR
			SELECT CEDULA, IDTERCERO, IDAFILIADO
			FROM #GRUPOS_PACIENTE_TERCERO
			ORDER BY IDTERCERO, CEDULA

			OPEN CURSOR_GRUPOS

			DECLARE @CEDULA_AGRUP VARCHAR(20), @IDTERCERO_AGRUP VARCHAR(20), @IDAFILIADO_AGRUP VARCHAR(20)

			FETCH NEXT FROM CURSOR_GRUPOS INTO @CEDULA_AGRUP, @IDTERCERO_AGRUP, @IDAFILIADO_AGRUP

			WHILE @@FETCH_STATUS = 0
			BEGIN
				SET @CNSMOV = NULL
				SET @CEDULA_AGRUP = LTRIM(RTRIM(@CEDULA_AGRUP))

				SELECT TOP 1 @CNSMOV = CNSMOV
				FROM #MOVIMIENTOS_POR_GRUPO
				WHERE LTRIM(RTRIM(CEDULA)) = @CEDULA_AGRUP AND IDTERCERO = @IDTERCERO_AGRUP

				SELECT @CNSITRA_USAR = CNSITRA FROM #ITRA_POR_TERCERO WHERE IDTERCERO = @IDTERCERO_AGRUP

				IF @CNSMOV IS NULL OR LTRIM(RTRIM(@CNSMOV)) = ''
				BEGIN
					EXEC SPQ_GENSEQUENCE @SEDE=@IDSEDE, @PREFIJO='@MOV', @NVOCONSEC=@CNSMOV OUTPUT
					IF @CNSMOV IS NULL OR @CNSMOV = ''
					BEGIN
						INSERT INTO @TBLERRORES(ERROR) VALUES ('Error al generar consecutivo para paciente ' + @CEDULA_AGRUP + ' / proveedor ' + ISNULL(@IDTERCERO_AGRUP, ''))
						FETCH NEXT FROM CURSOR_GRUPOS INTO @CEDULA_AGRUP, @IDTERCERO_AGRUP, @IDAFILIADO_AGRUP
						CONTINUE
					END
					DECLARE @NUM_MOV VARCHAR(20) = LTRIM(RTRIM(@CNSMOV))
					IF LEN(ISNULL(@IDSEDE,'01')) > 0 AND LEN(@NUM_MOV) >= LEN(@IDSEDE) AND LEFT(@NUM_MOV, LEN(@IDSEDE)) = @IDSEDE
						SET @NUM_MOV = SUBSTRING(@NUM_MOV, LEN(@IDSEDE) + 1, 20)
					SET @NUM_MOV = RIGHT(REPLICATE('0', 8) + RIGHT(ISNULL(@NUM_MOV,'0'), 8), 8)
					SET @CNSMOV = ISNULL(@IDSEDE, '01') + @NUM_MOV

					SELECT @NOMBRE_PACIENTE = NOMBREAFI FROM AFI WHERE IDAFILIADO = @IDAFILIADO_AGRUP

					INSERT INTO IMOV (CNSMOV, IDBODEGA, IDTIPOMOV, NODOCUMENTO, FECHAMOV, CCOSTO, IDSOLICITA, IDRECIBE, ESTADO, OBSERVACION, PROCEDENCIA, USUARIO, SYS_ComputerName, ESTRANSITO, CNSITRA, IDTERCERO, IDAREA, CNSTRAN, TIPO_DOC_COMPRA)
                    VALUES (@CNSMOV, @IDBODEGA, DBO.FNK_VALORVARIABLE('IDINVTPROPIA'), NULL, DBO.FNK_FECHA_SIN_MLS(GETDATE()), @CCOSTO_CUSTODIA, @USUARIO, @USUARIO, 0,
						'Custodia masiva - Paciente: ' + ISNULL(@NOMBRE_PACIENTE, 'N/A') + ' (' + @CEDULA_AGRUP + ') - Tr�nsito: ' + ISNULL(@CNSITRA_USAR, @CNSITRA), 'INV', @USUARIO, @SYS_COMPUTERNAME, 1, ISNULL(@CNSITRA_USAR, @CNSITRA), @IDTERCERO_AGRUP, @IDAREA_CUSTODIA, @IDAFILIADO_AGRUP, 'N')

					INSERT INTO #MOVIMIENTOS_POR_GRUPO (CEDULA, IDTERCERO, IDAFILIADO, CNSMOV)
					VALUES (@CEDULA_AGRUP, @IDTERCERO_AGRUP, @IDAFILIADO_AGRUP, @CNSMOV)
					SET @CONTADOR_MOVIMIENTOS = @CONTADOR_MOVIMIENTOS + 1
				END
				ELSE
				BEGIN
					SELECT @CNSMOV = CNSMOV FROM #MOVIMIENTOS_POR_GRUPO
					WHERE LTRIM(RTRIM(CEDULA)) = @CEDULA_AGRUP AND IDTERCERO = @IDTERCERO_AGRUP
				END

				-- Procesar cada fila del grupo: por cada unidad (CANTIDAD) genera 1 IMOVH + 1 ITRAH + 1 IEXI
				DECLARE CURSOR_FILAS CURSOR FOR
				SELECT CEDULA, IDARTICULO, NOLOTEPEDIDO, FECHAVENCE, PCOSTO, IVA, CUMPLE, APROBADO, TEMPERATURA, CANTIDAD, CANTIDADREV
				FROM #ARTICULOS_CUSTODIA
				WHERE LTRIM(RTRIM(CEDULA)) = @CEDULA_AGRUP AND IDTERCERO = @IDTERCERO_AGRUP
				ORDER BY IDARTICULO, NOLOTEPEDIDO, FECHAVENCE

				DECLARE @CANTIDAD_FILA INT
				DECLARE @CANTIDAD_REV_FILA INT
				DECLARE @U INT

				OPEN CURSOR_FILAS
				FETCH NEXT FROM CURSOR_FILAS INTO @CEDULA, @IDARTICULO, @NOLOTEPEDIDO, @FECHAVENCE, @PCOSTO, @IVA_PORCENTAJE, @CUMPLE_CONDICIONES, @ESTA_APROBADO, @TEMP_ALMACENAMIENTO, @CANTIDAD_FILA, @CANTIDAD_REV_FILA

				WHILE @@FETCH_STATUS = 0
				BEGIN
					IF COALESCE(@CANTIDAD_FILA, 0) < 1 SET @CANTIDAD_FILA = 1
					IF COALESCE(@CANTIDAD_REV_FILA, 0) < 0 SET @CANTIDAD_REV_FILA = 0
					IF @CANTIDAD_REV_FILA > @CANTIDAD_FILA SET @CANTIDAD_REV_FILA = @CANTIDAD_FILA
					SET @U = 1

					WHILE @U <= @CANTIDAD_FILA
					BEGIN
						DECLARE @CANTIDAD_FIJA INT = 1
						DECLARE @CANTIDADREV_UNIDAD DECIMAL(14,2) = CASE WHEN @U <= @CANTIDAD_REV_FILA THEN 1 ELSE 0 END
						SET @NOLOTE = SPACE(20)  
						EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@ICBU', @NOLOTE OUTPUT  
						SELECT @NOLOTE = @SEDE + 'L' + REPLACE(SPACE(7 - LEN(@NOLOTE)) + LTRIM(RTRIM(@NOLOTE)), SPACE(1), 0)
						IF @IVA_PORCENTAJE > 0 SET @PCSINIVA = @PCOSTO / (1 + (@IVA_PORCENTAJE / 100))
						ELSE SET @PCSINIVA = @PCOSTO

						INSERT INTO IMOVH (CNSMOV, IDARTICULO, CANTIDAD, PCOSTO, NOLOTE, NOLOTEPEDIDO, FECHAVENCE, ESTADO, DETALLE, PIVA, VLRIVA, IDITAR, CNSTRAN)
						SELECT @CNSMOV, @IDARTICULO, @CANTIDAD_FIJA, @PCOSTO, @NOLOTE, @NOLOTEPEDIDO, TRY_CONVERT(DATE, LTRIM(RTRIM(@FECHAVENCE)), 120), 0,
							'Custodia masiva - Paciente: ' + @CEDULA + ' - Medicamento: ' + @IDARTICULO + ' - Cumple: ' + 
							CASE WHEN @CUMPLE_CONDICIONES = 1 THEN 'SI' ELSE 'NO' END + ' - Aprobado: ' + CASE WHEN @ESTA_APROBADO = 1 THEN 'SI' ELSE 'NO' END,
							@IVA_PORCENTAJE, (@PCOSTO - @PCSINIVA) * @CANTIDAD_FIJA, IART.IDITAR, @IDAFILIADO_AGRUP   
						FROM IART WHERE IART.IDARTICULO = @IDARTICULO

						INSERT INTO ITRAH (CNSITRA, IDARTICULO, NOLOTE, CANTIDADORI, CANTIDADDES, CANTIDADREV, IDCAUSAL, ESTADO, PCOSTO, NOLOTEPEDIDO, FECHAVENCE, DETALLE, IDARTICULOORI, ODESFERA, OIESFERA, ODCILINDRO, OICILINDRO, ODEJE, OIEJE, ODADICION, OIADICION, ODALT, OIALT, ODAVL, OIAVL, ODTLENTE, OITLENTE, ODDNP, OIDNP, IVA, PCSINIVA, INICIAL, TEMPETURA, CUMPLE, APROBADO)
						VALUES (ISNULL(@CNSITRA_USAR, @CNSITRA), @IDARTICULO, @NOLOTE, @CANTIDAD_FIJA, @CANTIDAD_FIJA, @CANTIDADREV_UNIDAD, NULL, 0, @PCOSTO, @NOLOTEPEDIDO, TRY_CONVERT(DATE, LTRIM(RTRIM(@FECHAVENCE)), 120), 'Custodia masiva - Paciente: ' + @CEDULA, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, @IVA_PORCENTAJE, @PCSINIVA, 1, @TEMP_ALMACENAMIENTO, @CUMPLE_CONDICIONES, @ESTA_APROBADO)

						INSERT INTO IEXI (IDBODEGA, IDARTICULO, NOLOTE, NOLOTEPEDIDO, FECHAVENCE, EXISLOTE, CANTINICIAL, ESTADO, CNSMOV, PCOSTO, FECHAMOV, IDTERCERO)
						SELECT @IDBODEGA, IMOVH.IDARTICULO, IMOVH.NOLOTE, IMOVH.NOLOTEPEDIDO, IMOVH.FECHAVENCE, 0, @CANTIDAD_FIJA, 'Activo', @CNSMOV, IMOVH.PCOSTO, IMOV.FECHAMOV, IMOV.IDTERCERO
						FROM IMOVH
						INNER JOIN IMOV ON IMOV.CNSMOV = IMOVH.CNSMOV
						WHERE IMOVH.CNSMOV = @CNSMOV
						  AND IMOVH.IDARTICULO = @IDARTICULO
						  AND IMOVH.NOLOTE = @NOLOTE
						  AND NOT EXISTS (
								SELECT 1 FROM IEXI E
								WHERE E.IDBODEGA = @IDBODEGA
								  AND E.IDARTICULO = IMOVH.IDARTICULO
								  AND E.NOLOTE = IMOVH.NOLOTE
						  )

						SET @CONTADOR = @CONTADOR + 1
						SET @U = @U + 1
					END

					FETCH NEXT FROM CURSOR_FILAS INTO @CEDULA, @IDARTICULO, @NOLOTEPEDIDO, @FECHAVENCE, @PCOSTO, @IVA_PORCENTAJE, @CUMPLE_CONDICIONES, @ESTA_APROBADO, @TEMP_ALMACENAMIENTO, @CANTIDAD_FILA, @CANTIDAD_REV_FILA
				END

				CLOSE CURSOR_FILAS
				DEALLOCATE CURSOR_FILAS
				FETCH NEXT FROM CURSOR_GRUPOS INTO @CEDULA_AGRUP, @IDTERCERO_AGRUP, @IDAFILIADO_AGRUP
			END

			CLOSE CURSOR_GRUPOS
			DEALLOCATE CURSOR_GRUPOS
			DROP TABLE #GRUPOS_PACIENTE_TERCERO

			-- Cerrar tr�nsitos procesados: ya no deben aparecer en cat�logo ITRA (ESTADO=0).
			UPDATE T
			SET T.LOTEADO = 1,
				T.ESTADO = 2,
				T.CNSMOVDES = CASE WHEN M.CNT_MOV > 1 THEN 'VARIOS' ELSE M.CNSMOV_UNICO END
			FROM ITRA T
			INNER JOIN (
				SELECT IPT.CNSITRA,
					   COUNT(DISTINCT MPG.CNSMOV) AS CNT_MOV,
					   MIN(MPG.CNSMOV) AS CNSMOV_UNICO
				FROM #ITRA_POR_TERCERO IPT
				INNER JOIN #MOVIMIENTOS_POR_GRUPO MPG ON MPG.IDTERCERO = IPT.IDTERCERO
				WHERE IPT.CNSITRA IS NOT NULL
				GROUP BY IPT.CNSITRA
			) M ON M.CNSITRA = T.CNSITRA

			DROP TABLE #ITRA_POR_TERCERO

		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 'OK' AS OK, @CONTADOR AS ARTICULOS_PROCESADOS, @TOTAL_ARTICULOS AS ARTICULOS_TOTALES, @CNSITRA AS CNSITRA, @CONTADOR_MOVIMIENTOS AS MOVIMIENTOS_GENERADOS

		SELECT CEDULA, IDAFILIADO, IDTERCERO, CNSMOV,
			NOMBREAFI = (SELECT NOMBREAFI FROM AFI WHERE AFI.IDAFILIADO = #MOVIMIENTOS_POR_GRUPO.IDAFILIADO),
			RAZONSOCIAL = (SELECT RAZONSOCIAL FROM TER WHERE TER.IDTERCERO = #MOVIMIENTOS_POR_GRUPO.IDTERCERO),
			TOTAL_ARTICULOS = (
				SELECT SUM(COALESCE(AC.CANTIDAD, 1))
				FROM #ARTICULOS_CUSTODIA AC
				WHERE LTRIM(RTRIM(AC.CEDULA)) = LTRIM(RTRIM(#MOVIMIENTOS_POR_GRUPO.CEDULA))
				  AND AC.IDTERCERO = #MOVIMIENTOS_POR_GRUPO.IDTERCERO
			)
		FROM #MOVIMIENTOS_POR_GRUPO
		ORDER BY IDTERCERO, CEDULA

		DROP TABLE #MOVIMIENTOS_POR_GRUPO
		RETURN
	END

	IF @METODO = 'AGREGA_ARTICULO_ITRAH'
	BEGIN
		SELECT @IDARTICULO = IDARTICULO, @CANTIDAD = CANTIDAD, @CNSITRA = CNSITRA, @PROCESO = PROCESO
		FROM OPENJSON(@PARAMETROS)
		WITH(	IDARTICULO	VARCHAR(20)		'$.IDARTICULO', CANTIDAD	INT		'$.CANTIDAD', CNSITRA	VARCHAR(20)		'$.CNSITRA'
				, PROCESO	VARCHAR(20)		'$.PROCESO')

		IF 'VALIDACION' <> 'VALIDACION'
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'MENSAJE'
		END
	
		IF (SELECT COUNT(*) FROM @TBLERRORES)> 0
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		ELSE
		BEGIN
			BEGIN TRY
				IF @PROCESO = 'Nuevo'
				BEGIN
					SET @NOLOTE=SPACE(20)  
					EXEC SPK_GENCONSECUTIVO @COMPANIA,@SEDE,'@ICBU',@NOLOTE OUTPUT  
					SELECT @NOLOTE = @SEDE +'L'+ REPLACE(SPACE(7 - LEN(@NOLOTE))+LTRIM(RTRIM(@NOLOTE)),SPACE(1),0)  
					PRINT 'Insertando Articulo: '+@IDARTICULO+', NOLOTE: '+@NOLOTE

					INSERT INTO ITRAH (CNSITRA,IDARTICULO,NOLOTE,CANTIDADORI,CANTIDADDES,IDCAUSAL,ESTADO,  
							PCOSTO,NOLOTEPEDIDO,FECHAVENCE,DETALLE,IDARTICULOORI,ODESFERA,OIESFERA,ODCILINDRO,OICILINDRO,ODEJE,OIEJE,
							ODADICION,OIADICION,ODALT,OIALT,ODAVL,OIAVL,ODTLENTE,OITLENTE,ODDNP,OIDNP,IVA,PCSINIVA)
					SELECT @CNSITRA, @IDARTICULO, @NOLOTE, @CANTIDAD, 0, NULL, 0, 0, NULL, NULL,  NULL, NULL, NULL, NULL, NULL, NULL
					, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL

				END
			END TRY  
			BEGIN CATCH 
				INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE() ;  
			END CATCH  
			IF (SELECT COUNT(*) FROM @TBLERRORES)> 0
			BEGIN
				SELECT 'KO' OK
				SELECT ERROR FROM @TBLERRORES
				RETURN
			END
			SELECT 'OK'OK
		END 
	END
	IF @METODO='CAMBIAR_FACTURA'     
	BEGIN         
		SELECT @CNSMOV = CNSMOV, @CNSFCOM = CNSFCOM, @NODOCUMENTO=NROFACTURA,@NOADMISION=FACTUANTE
		FROM   OPENJSON (@PARAMETROS)
		WITH (           
		CNSMOV  VARCHAR(20)     '$.CNSMOV',
		CNSFCOM  VARCHAR(20)    '$.CNSFCOM',
		FACTUANTE  VARCHAR(20) '$.FACTUANTE',
		NROFACTURA  VARCHAR(20) '$.NROFACTURA'
		)
		IF EXISTS(SELECT 1 FROM FCXP WHERE CNSFCOM=@CNSFCOM AND ESTADO<>'A' AND COALESCE(CONTABILIZADA,0)=0 AND NOREFERENCIA=@NOADMISION)
		BEGIN
			UPDATE FCXP SET NOREFERENCIA=@NODOCUMENTO WHERE CNSFCOM=@CNSFCOM AND ESTADO<>'A' AND COALESCE(CONTABILIZADA,0)=0 AND NOREFERENCIA=@NOADMISION
			UPDATE IMOV SET NODOCUMENTO=@NODOCUMENTO WHERE CNSMOV=@CNSMOV
			UPDATE FCOM SET N_FACTURA=@NODOCUMENTO WHERE CNSFCOM=@CNSFCOM
		END
		ELSE
		BEGIN
			IF EXISTS(SELECT 1 FROM FCXP WHERE CNSFCOM=@CNSFCOM AND ESTADO<>'A' AND COALESCE(CONTABILIZADA,0)<>0 AND NOREFERENCIA=@NOADMISION)
			BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'La cuenta por pagar asociada a esta Orden de compra ya fue contabilizada, no se permite Realizar Cambios '
			END
			ELSE
			BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'No se encontro cuenta por pagar Asociada a esta orden de compra, no se permite Cambios, Comuniquese con el administrador del sistema '
			END
		END
		IF(SELECT COUNT(*) FROM @TBLERRORES)>0
		BEGIN
			SELECT 'KO' OK, ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' OK 
		RETURN 
	END


	-- =====================================================================
	-- ANULAR_CANASTA
	-- Anula un movimiento de canasta (IMOV.ESTADO = 2).
	-- Solo permite anular si est� en estado 0 (Pendiente) y es de tipo CN.
	-- =====================================================================
	IF @METODO = 'ANULAR_CANASTA'
	BEGIN
		DECLARE
			@CNSMOV_AN   VARCHAR(20),
			@MOTIVO_AN   VARCHAR(200),
			@ESTADO_AN   INT,
			@TIPOMOV_CN  VARCHAR(20)

		SELECT
			@CNSMOV_AN  = P.CNSMOV,
			@USUARIO    = ISNULL(P.USUARIO, @USUARIO),
			@MOTIVO_AN  = P.MOTIVO
		FROM OPENJSON(@PARAMETROS) WITH (
			CNSMOV  VARCHAR(20)  '$.CNSMOV',
			USUARIO VARCHAR(50)  '$.USUARIO',
			MOTIVO  VARCHAR(200) '$.MOTIVO'
		) P

		SELECT TOP 1 @TIPOMOV_CN = DATO FROM USVGS WHERE IDVARIABLE = 'INVE_CIRU_TIPO_MOV'

		SELECT @ESTADO_AN = ESTADO FROM IMOV WHERE CNSMOV = @CNSMOV_AN

		IF @ESTADO_AN IS NULL
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Canasta no encontrada: ' + ISNULL(@CNSMOV_AN,'')
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END
		IF @ESTADO_AN <> 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT CONCAT('La canasta no est� Pendiente (estado actual: ',
				CASE @ESTADO_AN WHEN 1 THEN 'Confirmado' WHEN 2 THEN 'Anulado' ELSE CAST(@ESTADO_AN AS VARCHAR) END,
				'). No se puede anular.')
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END
		IF NOT EXISTS (SELECT 1 FROM IMOV WHERE CNSMOV = @CNSMOV_AN AND IDTIPOMOV = @TIPOMOV_CN)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'El movimiento no corresponde a una Canasta de Cirug�a.'
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END

		BEGIN TRY
			BEGIN TRAN

			UPDATE IMOV
			SET    ESTADO      = 2,
				   OBSERVACION = ISNULL(OBSERVACION,'')
							   + ' | ANULADO: ' + ISNULL(@MOTIVO_AN,'S/M')
							   + ' USR:'       + ISNULL(@USUARIO,'')
							   + ' '           + CONVERT(VARCHAR(20), GETDATE(), 120)
			WHERE  CNSMOV = @CNSMOV_AN
			  AND  ESTADO = 0   -- doble check anti-race

			IF @@ROWCOUNT = 0
			BEGIN
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'No se pudo anular: la canasta fue modificada por otro proceso.'
				ROLLBACK
				SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
			END

			UPDATE IZSOL
			SET ESTADO = 2,
				USUARIOCIERRA = COALESCE(USUARIOCIERRA, @USUARIO),
				F_CANCEL = COALESCE(F_CANCEL, DBO.FNK_FECHA_SIN_MLS(GETDATE()))
			WHERE CNSIZSOL = @CNSMOV_AN

			COMMIT
		END TRY
		BEGIN CATCH
			IF @@TRANCOUNT > 0 ROLLBACK
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END
		SELECT 'OK' AS OK, @CNSMOV_AN AS CNSMOV, 'Canasta anulada correctamente.' AS MENSAJE
		RETURN
	END

	-- =====================================================================
	-- DATOS_ETIQUETA
	-- Devuelve los datos necesarios para imprimir la etiqueta de la canasta.
	-- El c�digo de barras (CODEBAR) es el propio CNSMOV.
	-- =====================================================================
	IF @METODO = 'DATOS_ETIQUETA'
	BEGIN
		DECLARE @CNSMOV_ET VARCHAR(20)

		SELECT @CNSMOV_ET = P.CNSMOV
		FROM OPENJSON(@PARAMETROS) WITH (CNSMOV VARCHAR(20) '$.CNSMOV') P

		IF NOT EXISTS (SELECT 1 FROM IMOV WHERE CNSMOV = @CNSMOV_ET)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Canasta no encontrada: ' + ISNULL(@CNSMOV_ET,'')
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END

		SELECT
			'OK'                                     AS OK,
			M.CNSMOV,
			M.CNSMOV                                 AS CODEBAR,
			M.FECHAMOV                               AS FECHA,
			M.IDBODEGA,
			B.DESCRIPCION                            AS NOMBODEGA,
			M.IDTIPOMOV,
			M.ESTADO,
			CASE M.ESTADO
				WHEN 0 THEN 'PENDIENTE'
				WHEN 1 THEN 'CONFIRMADO'
				WHEN 2 THEN 'ANULADO'
				ELSE CAST(M.ESTADO AS VARCHAR(5))
			END                                      AS ESTADO_DESC,
			S.DESCSERVICIO                           AS CIRUGIA_DESC,
			M.IDSOLICITA                             AS IDUSUARIO,
			U.NOMBRE                                 AS USUARIO_NOMBRE,
			IZ.CNSIZSOL,
			IZ.NOADMISION,
			IZ.SECTOR,
			(SELECT COUNT(DISTINCT D.IDARTICULO)
			 FROM IZSOLD D WHERE D.CNSIZSOL = IZ.CNSIZSOL) AS TOTAL_ARTICULOS,
			(SELECT ISNULL(SUM(D.CANTIDADSOL),0)
			 FROM IZSOLD D WHERE D.CNSIZSOL = IZ.CNSIZSOL) AS TOTAL_CANTIDAD
		FROM IMOV M
		LEFT JOIN IZSOL  IZ ON IZ.CNSIZSOL  = M.NODOCUMENTO
		LEFT JOIN SER    S  ON S.IDSERVICIO = M.IDSERVICIO
		LEFT JOIN IBOD   B  ON B.IDBODEGA   = M.IDBODEGA
		LEFT JOIN USUSU  U  ON U.USUARIO    = M.IDSOLICITA
		WHERE M.CNSMOV = @CNSMOV_ET
		RETURN
	END

	-- =====================================================================
	-- LEER_ETIQUETA
	-- Procesa el escaneo de la etiqueta en pabell�n:
	--   3.2.1 Actualiza campos en IZSOL (sector, clase, noadmision, usuario)
	--   3.2.2 Cambia IMOV.IDTIPOMOV a Venta a Paciente
	--   3.2.3 Llama SPQ_IZSOLDT CONFIRMARENTREGA
	-- Incluye idempotencia: rechaza si ya fue procesada.
	-- =====================================================================
	IF @METODO = 'LEER_ETIQUETA'
	BEGIN
		DECLARE
			@CNSMOV_LE       VARCHAR(20),
			@NOADMISION_LE   VARCHAR(30),
			@SECTOR_LE       VARCHAR(30),
			@NOPROG_LE       INT,
			@IDCIRUGIA_LE    VARCHAR(20),   -- IDSERVICIO de la cirug�a (dataCXPS.IDSERVICIO)
			@IDTIPOMOV_VTA   VARCHAR(20),
			@TIPOMOV_CN_LE   VARCHAR(20),
			@ESTADO_LE       INT,
			@CNSIZSOL_LE     VARCHAR(20),
			@IDBODEGA_LE     VARCHAR(20)    -- Bodega donde se prepar� la canasta

		SELECT
			@CNSMOV_LE     = P.CNSMOV,
			@NOADMISION_LE = P.NOADMISION,
			@SECTOR_LE     = P.SECTOR,
			@NOPROG_LE     = P.NOPROGRAMACION,
			@IDCIRUGIA_LE  = P.IDCIRUGIA
		FROM OPENJSON(@PARAMETROS) WITH (
			CNSMOV         VARCHAR(20) '$.CNSMOV',
			NOADMISION     VARCHAR(30) '$.NOADMISION',
			SECTOR         VARCHAR(30) '$.SECTOR',
			NOPROGRAMACION INT         '$.NOPROGRAMACION',
			IDCIRUGIA      VARCHAR(20) '$.IDCIRUGIA'
		) P

		SELECT TOP 1 @TIPOMOV_CN_LE  = DATO FROM USVGS WHERE IDVARIABLE = 'INVE_CIRU_TIPO_MOV'
		SET @IDTIPOMOV_VTA = DBO.FNK_VALORVARIABLE('IDINVMOV_VENTAS')

		-- Leer estado actual y bodega de la canasta
		SELECT @ESTADO_LE   = M.ESTADO,
			   @CNSIZSOL_LE = M.NODOCUMENTO,
			   @IDBODEGA_LE = M.IDBODEGA
		FROM IMOV M
		WHERE M.CNSMOV = @CNSMOV_LE

		IF @ESTADO_LE IS NULL
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Etiqueta/canasta no encontrada: ' + ISNULL(@CNSMOV_LE,'')
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END

		-- Idempotencia: ya fue procesada
		IF @ESTADO_LE <> 0
		BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT CONCAT('Esta canasta ya fue procesada (estado: ',
				CASE @ESTADO_LE WHEN 1 THEN 'CONFIRMADO' WHEN 2 THEN 'ANULADO'
				ELSE CAST(@ESTADO_LE AS VARCHAR) END,
				'). No se puede procesar dos veces.')
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END

		-- Verificar que es una canasta de cirug�a
		IF NOT EXISTS (SELECT 1 FROM IMOV WHERE CNSMOV = @CNSMOV_LE AND IDTIPOMOV = @TIPOMOV_CN_LE)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'El c�digo escaneado no corresponde a una Canasta de Cirug�a.'
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END

		-- Verificar que el servicio (cirug�a) de la canasta coincide con el del programa activo
		DECLARE @IDSERVICIO_CANASTA_LE VARCHAR(20)
		SELECT @IDSERVICIO_CANASTA_LE = IDSERVICIO
		FROM IMOV
		WHERE CNSMOV = @CNSMOV_LE

		IF ISNULL(@IDSERVICIO_CANASTA_LE, '') <> ISNULL(@IDCIRUGIA_LE, '')
		BEGIN
			INSERT INTO @TBLERRORES(ERROR)
			SELECT CONCAT(
				'La canasta ', @CNSMOV_LE,
				' fue preparada para la cirug�a [', ISNULL(@IDSERVICIO_CANASTA_LE, 'N/A'), ']',
				' y no coincide con la cirug�a activa [', ISNULL(@IDCIRUGIA_LE, 'N/A'), '].'
			)
			SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
		END

		BEGIN TRY
			BEGIN TRAN

			-- Lock anti-race
			SELECT @ESTADO_LE = ESTADO
			FROM IMOV WITH (UPDLOCK, HOLDLOCK)
			WHERE CNSMOV = @CNSMOV_LE

			IF @ESTADO_LE <> 0
			BEGIN
				INSERT INTO @TBLERRORES(ERROR)
				SELECT 'La canasta fue modificada por otro proceso durante el bloqueo.'
				ROLLBACK
				SELECT 'KO' AS OK; SELECT ERROR FROM @TBLERRORES; RETURN
			END

			-- 3.1 Descargar IMOVH ? CXPSI (insumos de la canasta en la programaci�n quir�rgica)
			-- Solo inserta los que a�n no existen para esa combinaci�n NOPROGRAMACION+CNSMOV+IDSERVICIO
			INSERT INTO CXPSI (
				NOPROGRAMACION, IDCIRUGIA, IDSERVICIO,
				CANTIDADEST, CANTIDADREAL,
				PCOSTO, PVENTA,
				PEDIDOINV, CANTIDADDEV,
				CNSMOV, INDDEV, BASICO
			)
			SELECT
				@NOPROG_LE,
				@IDCIRUGIA_LE,
				IART.IDSERVICIO,
				H.CANTIDAD,
				H.CANTIDAD,
				ISNULL(H.PCOSTO, 0),
				ISNULL(H.PVENTA, 0),
				1,   -- ya fue pedido/entregado v�a canasta
				0,
				@CNSMOV_LE,
				0,
				0
			FROM IMOVH H
			INNER JOIN IART ON IART.IDARTICULO = H.IDARTICULO
			WHERE H.CNSMOV = @CNSMOV_LE
			  AND NOT EXISTS (
				  SELECT 1 FROM CXPSI C
				  WHERE C.NOPROGRAMACION = @NOPROG_LE
					AND C.CNSMOV         = @CNSMOV_LE
					AND C.IDSERVICIO     = IART.IDSERVICIO
			  )

			-- 3.2.1 Actualizar IZSOL
			UPDATE IZSOL
			SET    SECTOR      = @SECTOR_LE,
				   CLASE       = 'QXPGCX',
				   NOADMISION  = @NOADMISION_LE,
				   USUARIOSOL  = @USUARIO
			WHERE  CNSIZSOL    = @CNSIZSOL_LE

			-- 3.2.2 Cambiar tipo de movimiento a Venta a Paciente
			-- NO se toca ESTADO aqu�; SPK_CONFIRMASAL_CM (llamado en 3.2.3) es quien
			-- hace la transici�n 0?1 junto con toda la l�gica de contabilizaci�n.
			-- El cambio de IDTIPOMOV es suficiente para garantizar idempotencia:
			-- un segundo escaneo fallar�a en la validaci�n IDTIPOMOV = @TIPOMOV_CN_LE.
			UPDATE IMOV
			SET    IDTIPOMOV = @IDTIPOMOV_VTA, IMOV.PROCEDENCIA = 'CM_SOL'
			WHERE  CNSMOV = @CNSMOV_LE
			  AND  ESTADO = 0

			COMMIT
		END TRY
		BEGIN CATCH
			IF @@TRANCOUNT > 0 ROLLBACK
			INSERT INTO @TBLERRORES(ERROR) SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		-- 3.2.3 Confirmar entrega usando la IDSEDE de la canasta (no la del computador de cirug�a).
		-- Se usa el mismo patr�n que CONF_MOVIMIENTO para que SPK_CONFIRMASAL_CM opere
		-- con el contexto de bodega correcto (farmacia que prepar� la canasta).
		DECLARE @IDSEDE_CANASTA VARCHAR(20)
		SELECT @IDSEDE_CANASTA = IDSEDE
		FROM IZSOL
		WHERE CNSIZSOL = @CNSIZSOL_LE

		EXEC SPK_CONFIRMASAL_CM @CNSMOV_LE, @USUARIO, @IDSEDE_CANASTA, 'LOG_PROD'

		SELECT 'OK' AS OK, @CNSMOV_LE AS CNSMOV, 'Canasta procesada correctamente en cirug�a.' AS MENSAJE
		RETURN
	END

	IF @METODO = 'REPORTE_RESTANTES_LOTEAR_MASIVO'
	BEGIN
		SELECT 'OK' AS OK

		SELECT CNSITRA
		INTO #CNSITRAS
		FROM OPENJSON(@PARAMETROS, '$.CNSITRAS')
		WITH (CNSITRA VARCHAR(20) '$')

		IF NOT EXISTS (SELECT 1 FROM #CNSITRAS WHERE COALESCE(CNSITRA,'') <> '')
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se recibieron CNSITRAS para generar el reporte.'
			SELECT 'KO' AS OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		CREATE TABLE #OUT (
			CNSITRA VARCHAR(20),
			PROVEEDOR VARCHAR(300),
			N_FACTURA VARCHAR(16),
			IDARTICULOORI VARCHAR(20),
			DESCRIPCION VARCHAR(900),
			CANT_OC DECIMAL(14,2),
			LOTEADO DECIMAL(14,2),
			RESTANTE DECIMAL(14,2)
		)

		DECLARE @CNSITRA_X    VARCHAR(20)
		DECLARE @N_FACTURA_X  VARCHAR(16)
		DECLARE @PROVEEDOR_X  VARCHAR(300)

		DECLARE CURSOR_CNS CURSOR FOR
			SELECT CNSITRA FROM #CNSITRAS WHERE COALESCE(CNSITRA,'') <> ''
		OPEN CURSOR_CNS
		FETCH NEXT FROM CURSOR_CNS INTO @CNSITRA_X
		WHILE @@FETCH_STATUS = 0
		BEGIN
			DECLARE @CNSFCOM_X VARCHAR(20)
			SELECT @CNSFCOM_X = CNSFCOM FROM ITRA WHERE CNSITRA = @CNSITRA_X

			-- Proveedor y N� Factura desde FCOM
			SET @N_FACTURA_X = ''
			SET @PROVEEDOR_X = ''
			IF COALESCE(@CNSFCOM_X,'') <> ''
				SELECT
					@N_FACTURA_X = COALESCE(F.N_FACTURA,''),
					@PROVEEDOR_X = COALESCE(T.RAZONSOCIAL,'')
				FROM FCOM F
				LEFT JOIN TER T ON T.IDTERCERO = F.IDTERCERO
				WHERE F.CNSFCOM = @CNSFCOM_X

			DECLARE @BASE_EXISTS_X BIT = 0
			IF EXISTS (SELECT 1 FROM ITRAH WHERE CNSITRA = @CNSITRA_X AND COALESCE(INICIAL,0) = 0)
				SET @BASE_EXISTS_X = 1

			IF @BASE_EXISTS_X = 1
			BEGIN
				;WITH LOTE AS (
					SELECT
						IDARTICULOORI = COALESCE(IDARTICULOORI, IDARTICULO),
						LOTEADO = SUM(COALESCE(CANTIDADORI,0))
					FROM ITRAH
					WHERE CNSITRA = @CNSITRA_X
					  AND COALESCE(INICIAL,0) = 1
					GROUP BY COALESCE(IDARTICULOORI, IDARTICULO)
				),
				BASE AS (
					SELECT
						IDARTICULOORI = COALESCE(IDARTICULOORI, IDARTICULO),
						CANT_OC = SUM(COALESCE(CANTIDADORI,0))
					FROM ITRAH
					WHERE CNSITRA = @CNSITRA_X
					  AND COALESCE(INICIAL,0) = 0
					GROUP BY COALESCE(IDARTICULOORI, IDARTICULO)
				)
				INSERT INTO #OUT (CNSITRA, PROVEEDOR, N_FACTURA, IDARTICULOORI, DESCRIPCION, CANT_OC, LOTEADO, RESTANTE)
				SELECT
					@CNSITRA_X,
					@PROVEEDOR_X,
					@N_FACTURA_X,
					B.IDARTICULOORI,
					IART.DESCRIPCION,
					B.CANT_OC,
					COALESCE(L.LOTEADO,0),
					B.CANT_OC - COALESCE(L.LOTEADO,0)
				FROM BASE B
				LEFT JOIN LOTE L ON L.IDARTICULOORI = B.IDARTICULOORI
				LEFT JOIN IART ON IART.IDARTICULO = B.IDARTICULOORI
				WHERE (B.CANT_OC - COALESCE(L.LOTEADO,0)) > 0
			END
			ELSE IF COALESCE(@CNSFCOM_X,'') <> ''
			BEGIN
				;WITH LOTE AS (
					SELECT
						IDARTICULOORI = COALESCE(H1.IDARTICULOORI, H1.IDARTICULO),
						LOTEADO = SUM(COALESCE(H1.CANTIDADORI,0))
					FROM ITRA T1
					INNER JOIN ITRAH H1 ON H1.CNSITRA = T1.CNSITRA
					WHERE T1.CNSFCOM = @CNSFCOM_X
					  AND COALESCE(T1.ESTADO,0) <> 3
					  AND COALESCE(H1.INICIAL,0) = 1
					GROUP BY COALESCE(H1.IDARTICULOORI, H1.IDARTICULO)
				),
				OC_AGG AS (
					SELECT
						D.IDARTICULO,
						CANT_OC = SUM(COALESCE(D.CANTIDAD,0))
					FROM FCOMD D
					INNER JOIN IART IA0 ON IA0.IDARTICULO = D.IDARTICULO
					WHERE D.CNSFCOM = @CNSFCOM_X
					GROUP BY D.IDARTICULO
				)
				INSERT INTO #OUT (CNSITRA, PROVEEDOR, N_FACTURA, IDARTICULOORI, DESCRIPCION, CANT_OC, LOTEADO, RESTANTE)
				SELECT
					@CNSITRA_X,
					@PROVEEDOR_X,
					@N_FACTURA_X,
					O.IDARTICULO,
					IART.DESCRIPCION,
					O.CANT_OC,
					COALESCE(L.LOTEADO,0),
					O.CANT_OC - COALESCE(L.LOTEADO,0)
				FROM OC_AGG O
				LEFT JOIN LOTE L ON L.IDARTICULOORI = O.IDARTICULO
				LEFT JOIN IART ON IART.IDARTICULO = O.IDARTICULO
				WHERE (O.CANT_OC - COALESCE(L.LOTEADO,0)) > 0
			END

			FETCH NEXT FROM CURSOR_CNS INTO @CNSITRA_X
		END
		CLOSE CURSOR_CNS
		DEALLOCATE CURSOR_CNS

		SELECT CNSITRA, PROVEEDOR, N_FACTURA, IDARTICULOORI, DESCRIPCION, CANT_OC, LOTEADO, RESTANTE
		FROM #OUT
		ORDER BY CNSITRA, IDARTICULOORI
		RETURN
	END

	-- =====================================================================
	-- CONSULTA_DESHACER_ENTREGA
	-- Lista art�culos/lotes pendientes de recepci�n por enfermer�a (RENFER 0/2)
	-- de un movimiento confirmado, para el dialog "Deshacer entrega".
	-- =====================================================================
	IF @METODO = 'CONSULTA_DESHACER_ENTREGA'
	BEGIN
		SELECT @CNSMOV = CNSMOV
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSMOV		VARCHAR(20)		'$.CNSMOV'
		)

		IF COALESCE(@CNSMOV,'') = ''
		BEGIN
			SELECT 'KO' OK
			SELECT 'Debe indicar el movimiento (CNSMOV).' ERROR
			RETURN
		END

		IF NOT EXISTS (SELECT 1 FROM IMOV WHERE CNSMOV = @CNSMOV AND ESTADO = 1 AND PROCEDENCIA <> 'DEVOLUCION')
		BEGIN
			SELECT 'KO' OK
			SELECT 'El movimiento no existe, no est� confirmado o no aplica para deshacer entrega.' ERROR
			RETURN
		END

		SELECT 'OK' OK

		SELECT
			H.CNSMOV,
			H.IDARTICULO,
			A.DESCRIPCION,
			H.NOLOTE,
			H.NOLOTEPEDIDO,
			H.CANTIDAD,
			COALESCE(H.CANTREP,0) CANTREP,
			COALESCE(H.RENFER,0) RENFER,
			H.FECHAVENCE
		FROM IMOVH H WITH (NOLOCK)
		INNER JOIN IART A WITH (NOLOCK) ON A.IDARTICULO = H.IDARTICULO
		WHERE H.CNSMOV = @CNSMOV
		  AND COALESCE(H.RENFER,0) IN (0,2)
		ORDER BY A.DESCRIPCION, H.NOLOTE

		RETURN
	END

	-- =====================================================================
	-- DESHACER_ENTREGA
	-- No-recibir forzado desde farmacia: marca l�neas pendientes, recupera
	-- siempre existencias (SPK_RECUPERA_NORECIBIDOS_ENF) y deja auditor�a.
	-- Uso: dispensaci�n al paciente incorrecto (enfermer�a a�n no recibi�).
	-- =====================================================================
	IF @METODO = 'DESHACER_ENTREGA'
	BEGIN
		DECLARE @MOTIVO_DESH VARCHAR(500)
		DECLARE @IDITAR_HEMO VARCHAR(20)
		DECLARE @IDART_DESH VARCHAR(20)
		DECLARE @NOLOTE_DESH VARCHAR(20)

		SELECT
			@CNSMOV = CNSMOV,
			@MOTIVO_DESH = LTRIM(RTRIM(MOTIVO))
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSMOV		VARCHAR(20)		'$.CNSMOV',
			MOTIVO		VARCHAR(500)	'$.MOTIVO'
		)

		IF COALESCE(@CNSMOV,'') = ''
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Debe indicar el movimiento (CNSMOV).'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF COALESCE(@MOTIVO_DESH,'') = '' OR LEN(@MOTIVO_DESH) < 5
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Debe indicar el motivo del deshacer entrega (m�nimo 5 caracteres).'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF NOT EXISTS (
			SELECT 1 FROM IMOV
			WHERE CNSMOV = @CNSMOV AND ESTADO = 1 AND PROCEDENCIA IN ('CM_SOL','Consumo')
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'El movimiento no existe, no est� confirmado o su procedencia no permite deshacer entrega.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF EXISTS (
			SELECT 1 FROM IMOVH WITH (NOLOCK)
			WHERE CNSMOV = @CNSMOV AND COALESCE(RENFER,0) = 1
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'Enfermer�a ya recibi� uno o m�s art�culos de este movimiento. No es posible deshacer la entrega.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		IF NOT EXISTS (
			SELECT 1 FROM IMOVH WITH (NOLOCK)
			WHERE CNSMOV = @CNSMOV AND COALESCE(RENFER,0) IN (0,2)
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No hay art�culos pendientes de recepci�n por enfermer�a para deshacer.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT @IDITAR_HEMO = DBO.FNK_VALORVARIABLE('IDITARHEMODERIVADOS')
		IF COALESCE(@IDITAR_HEMO,'') <> '' AND EXISTS (
			SELECT 1
			FROM IMOVH H WITH (NOLOCK)
			INNER JOIN IART A WITH (NOLOCK) ON A.IDARTICULO = H.IDARTICULO
			WHERE H.CNSMOV = @CNSMOV
			  AND COALESCE(H.RENFER,0) IN (0,2)
			  AND A.IDITAR = @IDITAR_HEMO
		)
		BEGIN
			INSERT INTO @TBLERRORES(ERROR) SELECT 'No se puede deshacer entrega de hemocomponentes. Comun�quese con el administrador del sistema.'
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT
			@CNSIZSOL = IMOV.NODOCUMENTO,
			@IDBODEGA = IMOV.IDBODEGA
		FROM IMOV WHERE CNSMOV = @CNSMOV

		SELECT
			@NOADMISION = IZSOL.NOADMISION,
			@IDSEDE = COALESCE(NULLIF(LTRIM(RTRIM(IZSOL.IDSEDE)),''), @IDSEDE, @SEDE)
		FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL

		IF COALESCE(@NOADMISION,'') = ''
		BEGIN
			SET @NOADMISION = @CNSIZSOL
		END

		BEGIN TRY
			/* Auditor�a con columnas existentes: IMOV.OBSERVACION + USLOG (no existen USUDESHACERENTREGA/FDESHACERENTREGA/MOTIVODESHACERENTREGA) */
			UPDATE IMOV SET
				OBSERVACION = LEFT(
					LTRIM(RTRIM(
						CASE
							WHEN COALESCE(LTRIM(RTRIM(OBSERVACION)), '') = '' THEN ''
							ELSE LTRIM(RTRIM(OBSERVACION)) + ' | '
						END
						+ 'DESHACER ENTREGA ['
						+ CONVERT(VARCHAR(19), DBO.FNK_FECHA_SIN_MLS(GETDATE()), 120)
						+ '] '
						+ @USUARIO
						+ ': '
						+ @MOTIVO_DESH
					)),
					255
				)
			WHERE CNSMOV = @CNSMOV

			EXEC SPK_GENCONSECUTIVO @COMPANIA, @SEDE, '@LOG', @NVOCONSEC OUTPUT
			SELECT @NVOCONSEC = @SEDE + REPLACE(SPACE(8 - LEN(@NVOCONSEC)) + LTRIM(RTRIM(@NVOCONSEC)), SPACE(1), 0)

			INSERT INTO USLOG (CNSLOG, COMPANIA, NOADMISION, PROCESO, REQUEST, REFERENCIA, USUARIO, FECHA, SYS_ComputerName)
			SELECT
				@NVOCONSEC,
				@COMPANIA,
				@CNSMOV,
				'DESHACER_ENTREGA',
				'PROCESS',
				LEFT(@MOTIVO_DESH, 250),
				@USUARIO,
				DBO.FNK_GETDATE(),
				@SYS_COMPUTERNAME

			INSERT INTO USLOGH (CNSLOG, ITEM, CAMPO, VALORANT, VALORNVO)
			SELECT @NVOCONSEC, 1, 'CNSMOV', @CNSMOV, NULL
			UNION ALL
			SELECT @NVOCONSEC, 2, 'CNSIZSOL', @CNSIZSOL, NULL
			UNION ALL
			SELECT @NVOCONSEC, 3, 'MOTIVO', LEFT(@MOTIVO_DESH, 250), NULL

			DECLARE CUR_DESH CURSOR LOCAL FAST_FORWARD FOR
			SELECT H.IDARTICULO, H.NOLOTE
			FROM IMOVH H
			WHERE H.CNSMOV = @CNSMOV
			  AND COALESCE(H.RENFER,0) IN (0,2)

			OPEN CUR_DESH
			FETCH NEXT FROM CUR_DESH INTO @IDART_DESH, @NOLOTE_DESH
			WHILE @@FETCH_STATUS = 0
			BEGIN
				-- Marca no recibido (mismo patr�n enfermer�a); SPK_RECUPERA pone RENFER=1 y CANTREP al recuperar
				UPDATE IMOVH
				SET USUARIOR = @USUARIO, RENFER = 4
				WHERE CNSMOV = @CNSMOV
				  AND IDARTICULO = @IDART_DESH
				  AND NOLOTE = @NOLOTE_DESH

				EXEC SPK_RECUPERA_NORECIBIDOS_ENF
					@CNSMOV,
					@IDART_DESH,
					@NOLOTE_DESH,
					@NOADMISION,
					@USUARIO,
					@IDSEDE,
					@SYS_COMPUTERNAME,
					1

				-- Invalida v�nculo de dispensaci�n en la solicitud (sin tocar IEXI: el stock ya lo recuper� SPK_RECUPERA)
				UPDATE IZSOLD
				SET ESTADO = 1,
					TIPOENT = NULL
				WHERE CNSIZSOLD IN (
					SELECT DISTINCT DT.CNSIZSOLD
					FROM IZSOLDT DT
					WHERE DT.CNSMOV = @CNSMOV
					  AND (
						DT.IDARTICULOREAL = @IDART_DESH
						OR DT.IDARTICULO = @IDART_DESH
					  )
					  AND DT.NOLOTE = @NOLOTE_DESH
				)

				DELETE FROM IZSOLDT
				WHERE CNSMOV = @CNSMOV
				  AND NOLOTE = @NOLOTE_DESH
				  AND (
					IDARTICULOREAL = @IDART_DESH
					OR IDARTICULO = @IDART_DESH
				  )

				FETCH NEXT FROM CUR_DESH INTO @IDART_DESH, @NOLOTE_DESH
			END
			CLOSE CUR_DESH
			DEALLOCATE CUR_DESH

			-- Reabre solicitud si qued� cerrada y a�n hay detalle pendiente
			IF EXISTS (SELECT 1 FROM IZSOL WHERE CNSIZSOL = @CNSIZSOL AND ESTADO = 2)
			   AND EXISTS (SELECT 1 FROM IZSOLD WHERE CNSIZSOL = @CNSIZSOL AND COALESCE(ESTADO,0) <> 0)
			BEGIN
				UPDATE IZSOL
				SET ESTADO = 1,
					USUARIOCIERRA = NULL,
					F_CANCEL = NULL
				WHERE CNSIZSOL = @CNSIZSOL
			END
		END TRY
		BEGIN CATCH
			IF CURSOR_STATUS('local', 'CUR_DESH') >= 0
			BEGIN
				CLOSE CUR_DESH
				DEALLOCATE CUR_DESH
			END
			INSERT INTO @TBLERRORES(ERROR)
			SELECT 'Error al deshacer entrega: ' + ERROR_MESSAGE()
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 'OK' OK, CNSMOV = @CNSMOV
		RETURN
	END

	IF @METODO = 'FIRMAR_PACIENTE_MOV'
	BEGIN
		DECLARE @IDFIRMAPAC VARCHAR(50)
		SELECT @CNSMOV = CNSMOV, @IDFIRMAPAC = FIRMA
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSMOV VARCHAR(20) '$.CNSMOV',
			FIRMA VARCHAR(50) '$.FIRMA'
		)

		IF COALESCE(@CNSMOV, '') = '' OR COALESCE(@IDFIRMAPAC, '') = ''
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR = 'Debe indicar el movimiento y la firma'
			RETURN
		END

		IF COL_LENGTH('dbo.IMOV', 'FIRMA_PACIENTE') IS NULL
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR = 'Falta la columna IMOV.FIRMA_PACIENTE. Ejecute sql/ALTER_IMOV_FIRMA_PACIENTE.sql'
			RETURN
		END

		IF NOT EXISTS (
			SELECT 1 FROM IMOV WITH (NOLOCK)
			WHERE CNSMOV = @CNSMOV AND COALESCE(ESTADO, 0) > 0
		)
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR = 'El movimiento no est� confirmado o no existe'
			RETURN
		END

		BEGIN TRY
			-- No se borra el DOCS anterior: queda hist�rico
			UPDATE IMOV
			SET FIRMA_PACIENTE = @IDFIRMAPAC
			WHERE CNSMOV = @CNSMOV
		END TRY
		BEGIN CATCH
			INSERT INTO @TBLERRORES(ERROR)
			SELECT ERROR_MESSAGE()
		END CATCH

		IF EXISTS(SELECT 1 FROM @TBLERRORES)
		BEGIN
			SELECT 'KO' OK
			SELECT ERROR FROM @TBLERRORES
			RETURN
		END

		SELECT 'OK' OK, CNSMOV = @CNSMOV, FIRMA_PACIENTE = @IDFIRMAPAC
		RETURN
	END

	IF @METODO = 'DISPENSACIONES_AUT'
	BEGIN
		/* Sin CNSIZSOL: Autorizador / transcripciones / resto ? entregas de toda la AUT.
		   Con CNSIZSOL: solo Nueva dispensaci�n (POR_SOLICITUD): l�neas de ESA solicitud. */
		SELECT @IDAUT = IDAUT, @CNSIZSOL = CNSIZSOL
		FROM OPENJSON (@PARAMETROS)
		WITH (
			IDAUT VARCHAR(20) '$.IDAUT',
			CNSIZSOL VARCHAR(20) '$.CNSIZSOL'
		)

		SELECT 'OK' OK

		IF COALESCE(NULLIF(@CNSIZSOL, ''), '') <> ''
		BEGIN
			/* Entregado: SKU real (IZSOLDT) + lote. Pendiente: servicio de la l�nea IZSOLD. */
			SELECT
				IDARTICULO = COALESCE(NULLIF(T.IDARTICULOREAL, ''), NULLIF(T.IDARTICULO, ''), D.IDARTICULO),
				DESCRIPCION = MAX(COALESCE(IART.DESCRIPCION, T.IDARTICULO, D.IDARTICULO)),
				NOLOTE = T.NOLOTE,
				NOLOTEPEDIDO = MAX(COALESCE(NULLIF(LX.NOLOTEPEDIDO, ''), IH.NOLOTEPEDIDO)),
				FECHAVENCE = MAX(COALESCE(LX.FECHAVENCE, IH.FECHAVENCE)),
				IDSERVICIO = MAX(COALESCE(NULLIF(D.IDSERVICIO, ''), IART.IDSERVICIO, D.IDARTICULO)),
				DESCSERVICIO = MAX(SER.DESCSERVICIO),
				CANTIDAD = CAST(SUM(COALESCE(T.CANTIDADSOL, 0)) AS DECIMAL(18,4)),
				CANTENTREGADA = CAST(SUM(COALESCE(T.CANTIDADSOL, 0)) AS DECIMAL(18,4)),
				PENDIENTE = CAST(0 AS DECIMAL(18,4)),
				FECHA_DISPENSACION = MAX(M.FECHAMOV),
				CNSMOV = MAX(T.CNSMOV)
			FROM IZSOL Z WITH (NOLOCK)
			INNER JOIN IZSOLD D WITH (NOLOCK) ON D.CNSIZSOL = Z.CNSIZSOL
			INNER JOIN IZSOLDT T WITH (NOLOCK) ON T.CNSIZSOLD = D.CNSIZSOLD
			LEFT JOIN IMOV M WITH (NOLOCK) ON M.CNSMOV = T.CNSMOV
			LEFT JOIN IART WITH (NOLOCK) ON IART.IDARTICULO = COALESCE(NULLIF(T.IDARTICULOREAL, ''), NULLIF(T.IDARTICULO, ''), D.IDARTICULO)
			LEFT JOIN SER WITH (NOLOCK) ON SER.IDSERVICIO = COALESCE(NULLIF(D.IDSERVICIO, ''), IART.IDSERVICIO)
			OUTER APPLY (
				SELECT TOP 1 IEXI.NOLOTEPEDIDO, IEXI.FECHAVENCE
				FROM IEXI WITH (NOLOCK)
				WHERE IEXI.IDARTICULO = COALESCE(NULLIF(T.IDARTICULOREAL, ''), NULLIF(T.IDARTICULO, ''), D.IDARTICULO)
					AND IEXI.NOLOTE = T.NOLOTE
					AND (M.IDBODEGA IS NULL OR IEXI.IDBODEGA = M.IDBODEGA)
				ORDER BY IEXI.ID
			) LX
			OUTER APPLY (
				SELECT TOP 1 IMOVH.NOLOTEPEDIDO, IMOVH.FECHAVENCE
				FROM IMOVH WITH (NOLOCK)
				WHERE T.CNSMOV IS NOT NULL
					AND IMOVH.CNSMOV = T.CNSMOV
					AND COALESCE(IMOVH.NOLOTE, '') = COALESCE(T.NOLOTE, '')
					AND IMOVH.IDARTICULO = COALESCE(NULLIF(T.IDARTICULOREAL, ''), NULLIF(T.IDARTICULO, ''), D.IDARTICULO)
			) IH
			WHERE Z.CNSIZSOL = @CNSIZSOL
				AND COALESCE(T.CANTIDADSOL, 0) > 0
				AND (T.CNSMOV IS NULL OR COALESCE(M.ESTADO, 0) IN (0, 1))
			GROUP BY
				COALESCE(NULLIF(T.IDARTICULOREAL, ''), NULLIF(T.IDARTICULO, ''), D.IDARTICULO),
				T.NOLOTE

			UNION ALL

			SELECT
				IDARTICULO = MAX(D.IDARTICULO),
				DESCRIPCION = MAX(IART.DESCRIPCION),
				NOLOTE = CAST(NULL AS VARCHAR(20)),
				NOLOTEPEDIDO = CAST(NULL AS VARCHAR(20)),
				FECHAVENCE = CAST(NULL AS DATETIME),
				IDSERVICIO = COALESCE(NULLIF(MAX(D.IDSERVICIO), ''), MAX(IART.IDSERVICIO), MAX(D.IDARTICULO)),
				DESCSERVICIO = MAX(COALESCE(SER.DESCSERVICIO, IART.DESCRIPCION, D.IDSERVICIO)),
				CANTIDAD = CAST(SUM(D.CANTIDADSOL) AS DECIMAL(18,4)),
				CANTENTREGADA = CAST(0 AS DECIMAL(18,4)),
				PENDIENTE = CAST(SUM(D.CANTIDADSOL) - SUM(COALESCE(E.ENTREGADO, 0)) AS DECIMAL(18,4)),
				FECHA_DISPENSACION = CAST(NULL AS DATETIME),
				CNSMOV = CAST(NULL AS VARCHAR(20))
			FROM IZSOL Z WITH (NOLOCK)
			INNER JOIN IZSOLD D WITH (NOLOCK) ON D.CNSIZSOL = Z.CNSIZSOL
			OUTER APPLY (
				SELECT ENTREGADO = SUM(COALESCE(T.CANTIDADSOL, 0))
				FROM IZSOLDT T WITH (NOLOCK)
				LEFT JOIN IMOV M WITH (NOLOCK) ON M.CNSMOV = T.CNSMOV
				WHERE T.CNSIZSOLD = D.CNSIZSOLD
					AND (T.CNSMOV IS NULL OR COALESCE(M.ESTADO, 0) IN (0, 1))
			) E
			LEFT JOIN IART WITH (NOLOCK) ON IART.IDARTICULO = D.IDARTICULO
			LEFT JOIN SER WITH (NOLOCK) ON SER.IDSERVICIO = COALESCE(NULLIF(D.IDSERVICIO, ''), IART.IDSERVICIO)
			WHERE Z.CNSIZSOL = @CNSIZSOL
			GROUP BY COALESCE(NULLIF(D.IDSERVICIO, ''), D.IDARTICULO)
			HAVING SUM(D.CANTIDADSOL) - SUM(COALESCE(E.ENTREGADO, 0)) > 0
			RETURN
		END

		SELECT
			IDSERVICIO = COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), IART.IDSERVICIO, D.IDARTICULO),
			CANTENTREGADA = CAST(SUM(COALESCE(T.CANTIDADSOL, 0)) AS DECIMAL(18,4)),
			FECHA_DISPENSACION = MAX(M.FECHAMOV),
			CNSMOV = M.CNSMOV
		FROM IZSOL Z WITH (NOLOCK)
		INNER JOIN IZSOLD D WITH (NOLOCK) ON D.CNSIZSOL = Z.CNSIZSOL
		INNER JOIN IZSOLDT T WITH (NOLOCK) ON T.CNSIZSOLD = D.CNSIZSOLD
		LEFT JOIN IMOV M WITH (NOLOCK) ON M.CNSMOV = T.CNSMOV
		LEFT JOIN IART WITH (NOLOCK) ON IART.IDARTICULO = COALESCE(NULLIF(LTRIM(RTRIM(T.IDARTICULO)), ''), D.IDARTICULO)
		WHERE Z.NOADMISION = @IDAUT
			AND UPPER(LTRIM(RTRIM(COALESCE(Z.CLASE, '')))) IN ('CE', 'FORMEDCE')
			AND (T.CNSMOV IS NULL OR COALESCE(M.ESTADO, 0) IN (0, 1))
		GROUP BY
			COALESCE(NULLIF(LTRIM(RTRIM(D.IDSERVICIO)), ''), IART.IDSERVICIO, D.IDARTICULO),
			M.CNSMOV
		HAVING SUM(COALESCE(T.CANTIDADSOL, 0)) > 0
		RETURN
	END

	/* Formato de transfusi�n: componente, sello, grupo de la bolsa y caducidad.
	   Hasta 3 filas, que son las del formato. La reserva seleccionada va primero. */
	IF @METODO = 'FORMATO_TRANSFUSION'
	BEGIN
		SELECT @CNSIZSOL = NULLIF(LTRIM(RTRIM(CNSIZSOL)), '')
			, @CNSRES = NULLIF(LTRIM(RTRIM(CNSRES)), '')
			, @IDBODEGA_FMT = NULLIF(LTRIM(RTRIM(IDBODEGA)), '')
		FROM OPENJSON (@PARAMETROS)
		WITH (
			CNSIZSOL VARCHAR(20) '$.CNSIZSOL',
			CNSRES   VARCHAR(20) '$.CNSRES',
			IDBODEGA VARCHAR(20) '$.IDBODEGA'
		)

		SELECT TOP 3
			BSRES.CNSRES,
			BSRES.ESTADO,
			COMPONENTE = IART.DESCRIPCION,
			SELLO_CALIDAD = COALESCE(NULLIF(LTRIM(RTRIM(BSRES.SELLOCALIDAD)), ''), L.SELLOCALIDAD, ''),
			GRUPO_BOLSA = LTRIM(RTRIM(CONCAT(
				COALESCE(NULLIF(LTRIM(RTRIM(BSRES.FACTORABO)), ''), L.GRUPOABO, ''),
				' ',
				COALESCE(NULLIF(LTRIM(RTRIM(BSRES.FACTORRH)), ''), L.GRUPORH, '')
			))),
			FECHA_CADUCIDAD = CONVERT(VARCHAR(10), L.FECHAVENCE, 103)
		FROM BSRES WITH (NOLOCK)
		INNER JOIN IZSOLD WITH (NOLOCK) ON IZSOLD.CNSIZSOLD = BSRES.CNSIZSOLD
		INNER JOIN IART WITH (NOLOCK) ON IART.IDARTICULO = BSRES.IDARTICULO
		OUTER APPLY (
			SELECT TOP 1 IEXI.SELLOCALIDAD, IEXI.GRUPOABO, IEXI.GRUPORH, IEXI.FECHAVENCE
			FROM IEXI WITH (NOLOCK)
			WHERE IEXI.NOLOTE = BSRES.LOTE
				AND IEXI.IDARTICULO = BSRES.IDARTICULO
			ORDER BY CASE WHEN COALESCE(@IDBODEGA_FMT, '') <> '' AND IEXI.IDBODEGA = @IDBODEGA_FMT THEN 0 ELSE 1 END
				, IEXI.ID
		) L
		WHERE IZSOLD.CNSIZSOL = @CNSIZSOL
			AND (
				BSRES.ESTADO IN ('Recibido', 'Reservada')
				OR (COALESCE(@CNSRES, '') <> '' AND BSRES.CNSRES = @CNSRES)
			)
		ORDER BY
			CASE WHEN COALESCE(@CNSRES, '') <> '' AND BSRES.CNSRES = @CNSRES THEN 0 ELSE 1 END,
			CASE WHEN BSRES.ESTADO = 'Recibido' THEN 0 ELSE 1 END,
			BSRES.F_CREA DESC
		RETURN
	END

	END TRY
	BEGIN CATCH
		-- Blindaje global: cualquier error no controlado deshace la transacci�n abierta
		IF @@TRANCOUNT > 0
			ROLLBACK TRAN;

		INSERT INTO @TBLERRORES(ERROR)
		SELECT COALESCE(ERROR_MESSAGE(), 'Error no controlado en SPQ_IZSOL')

		SELECT 'KO' OK,
			ERROR_MESSAGE() AS ERROR,
			ERROR_NUMBER() AS ERROR_NUMBER,
			ERROR_LINE() AS ERROR_LINE,
			COALESCE(ERROR_PROCEDURE(), 'SPQ_IZSOL') AS ERROR_PROCEDURE

		SELECT ERROR FROM @TBLERRORES
		RETURN
	END CATCH

END
